  const I18N_EN_HTML = {"help": "\n            <li><b>Paint</b>: tap or drag over cells. <b>Fill</b>: colors a whole connected area of the same color at once.</li>\n            <li>Tap the selected paint color again (or right-click a color) to change or remove that palette slot. Cells you've already painted keep their color.</li>\n            <li><b>Current row</b> counts from the bottom as row 1 and is outlined on the grid.</li>\n            <li>The background is the color of unpainted cells, so changing it later keeps your pattern intact.</li>\n            <li>In Text to pattern, choose a <b>Shadow</b> direction to lay a shadow color behind the letters. Set the style to <b>Glitch (two colors)</b> to shift two colors in opposite directions. <b>Outline</b> wraps the letters by one or two cells, corners included.</li>\n            <li>Drag the text and let go to lock it in place. Placed it wrong? Tap <b>Undo</b>.</li>\n            <li><b>Rotate</b> turns the whole pattern 90° or 270° clockwise — handy when working rows vertically.</li>\n            <li>Add words one at a time and move each to stagger lines.</li>\n            <li><b>Text flow</b> makes letters wave, bounce, or climb up and down diagonally.</li>\n            <li>Make your own decorations with <b>Draw new decoration</b> in the Decor tab, or select something on the canvas and tap <b>Add to my decorations</b>.</li>\n            <li>Use the <b>Select</b> tool to drag a box around placed text or decorations to move them again — each connected blob can be moved on its own.</li>\n            <li><b>Copy</b> and <b>Paste</b> floating text, decorations or selections as many times as you like. Keys: Ctrl+C · Ctrl+X · Ctrl+V · Delete · Esc · Enter · arrows</li>\n            <li>After adding text, tap <b>Move letters</b> to pick and move each letter freely — great for fine-tuning a wave layout.</li>\n            <li>While moving text, tap <b>↔ Center · ↕ Center</b> to center it on the grid.</li>\n            <li><b>Save image</b> downloads a PNG file right away. On a phone it may go to your Downloads folder instead of your photo gallery. To add it to your gallery, tap <b>Share</b> next to it and save from there.</li>\n            <li>Use the arrow button at the right end of the toolbar (below it on phones) to collapse it so the pattern fills the screen. Tap the small arrow handle at the top right to bring it back. Keyboard: Ctrl+\\ (Cmd+\\ on Mac)</li>\n          ", "credits": "\n              <li><b>DungGeunMo</b> — original by Kim Jung-tae, conversion by Kil Hyung-jin · Public domain</li>\n              <li><b>NeoDunggeunmo</b> — © 2017–2024 Eunbin Jeong (Dalgona.) · <a href=\"https://openfontlicense.org\" target=\"_blank\" rel=\"noopener\">SIL OFL 1.1</a> · <a href=\"https://github.com/neodgm/neodgm\" target=\"_blank\" rel=\"noopener\">github.com/neodgm</a></li>\n              <li><b>DenkiChip Hangul</b> (x10y12pxDenkiChipHangul) — © 2026 Lee Minseo, x8y12pxDenkiChip Project Authors · <a href=\"https://openfontlicense.org\" target=\"_blank\" rel=\"noopener\">SIL OFL 1.1</a></li>\n              <li><b>Galmuri</b> — © 2019–2025 Lee Minseo, Reserved Font Name \"Galmuri\" · <a href=\"https://openfontlicense.org\" target=\"_blank\" rel=\"noopener\">SIL OFL 1.1</a> · <a href=\"https://github.com/quiple/galmuri\" target=\"_blank\" rel=\"noopener\">github.com/quiple/galmuri</a></li>\n              <li><b>DOS Gothic · DOS Myungjo · DOS Pilgi · DOS Iyagi Bold</b> — © 2016–2022 Damheo Lee (leedheo) · MIT License · <a href=\"https://github.com/hurss/fonts\" target=\"_blank\" rel=\"noopener\">github.com/hurss/fonts</a></li>\n              <li><b>DOS Saemmul</b> — © 2016 Damheo Lee (leedheo) · MIT License · <a href=\"https://github.com/hurss/fonts\" target=\"_blank\" rel=\"noopener\">github.com/hurss/fonts</a></li>\n              <li><b>Miraero</b> (by leedheo) — © 2016–2022 Damheo Lee (leedheo), Reserved Font Name \"MiraeroNormal\" · MIT License · <a href=\"https://github.com/hurss/fonts\" target=\"_blank\" rel=\"noopener\">github.com/hurss/fonts</a></li>\n              <li><b>Nanum Pen</b> — © 2010 NHN Corporation (now NAVER), Reserved Font Names \"Nanum\", \"NanumPen\" and others · <a href=\"https://openfontlicense.org\" target=\"_blank\" rel=\"noopener\">SIL OFL 1.1</a> · <a href=\"https://hangeul.naver.com/font\" target=\"_blank\" rel=\"noopener\">hangeul.naver.com</a></li>\n              <li><b>Mulmaru</b> — © 2025 Mushsooni, Reserved Font Name \"물마루\", \"Mulmaru\" · <a href=\"https://openfontlicense.org\" target=\"_blank\" rel=\"noopener\">SIL OFL 1.1</a> · <a href=\"https://github.com/mushsooni/mulmaru\" target=\"_blank\" rel=\"noopener\">github.com/mushsooni/mulmaru</a></li>\n              <li><b>Mona12 · Mona10x12</b> — © 2025 Monad ABXY, Reserved Font Name \"Mona\" · <a href=\"https://openfontlicense.org\" target=\"_blank\" rel=\"noopener\">SIL OFL 1.1</a> · <a href=\"https://monadabxy.com/fonts/mona/\" target=\"_blank\" rel=\"noopener\">monadabxy.com</a></li>\n\n              <li><b>Departure Mono</b> — © 2022–2024 Helena Zhang · <a href=\"https://openfontlicense.org\" target=\"_blank\" rel=\"noopener\">SIL OFL 1.1</a> · <a href=\"https://departuremono.com\" target=\"_blank\" rel=\"noopener\">departuremono.com</a></li>\n              <li><b>Noto Serif KR</b> — © 2017–2024 Adobe · <a href=\"https://openfontlicense.org\" target=\"_blank\" rel=\"noopener\">SIL OFL 1.1</a> · <a href=\"https://github.com/notofonts/noto-cjk\" target=\"_blank\" rel=\"noopener\">github.com/notofonts/noto-cjk</a></li>\n              <li><b>Dongle Bold</b> — Copyright 2021 The Dongle Project Authors (https://github.com/yangheeryu/Dongle) · <a href=\"https://openfontlicense.org\" target=\"_blank\" rel=\"noopener\">SIL OFL 1.1</a> · <a href=\"https://github.com/google/fonts/tree/main/ofl/dongle\" target=\"_blank\" rel=\"noopener\">github.com/google/fonts</a></li>\n              <li><b>Single Day</b> — Copyright 2015 DXKorea Inc. All rights reserved. · <a href=\"https://openfontlicense.org\" target=\"_blank\" rel=\"noopener\">SIL OFL 1.1</a> · <a href=\"https://github.com/google/fonts/tree/main/ofl/singleday\" target=\"_blank\" rel=\"noopener\">github.com/google/fonts</a></li>\n              <li><b>East Sea Dokdo</b> — Copyright (c) YoonDesign Inc. All Rights Reserved. · <a href=\"https://openfontlicense.org\" target=\"_blank\" rel=\"noopener\">SIL OFL 1.1</a> · <a href=\"https://github.com/google/fonts/tree/main/ofl/eastseadokdo\" target=\"_blank\" rel=\"noopener\">github.com/google/fonts</a></li>\n              <li><b>Leckerli One</b> — Copyright (c) 2011 Gesine Todt (www.gesine-todt.de), with Reserved Font Names \"Leckerli\" and \"Leckerli One\". · <a href=\"https://openfontlicense.org\" target=\"_blank\" rel=\"noopener\">SIL OFL 1.1</a> · <a href=\"https://github.com/google/fonts/tree/main/ofl/leckerlione\" target=\"_blank\" rel=\"noopener\">github.com/google/fonts</a></li>\n              <li><b>Pirata One</b> — Copyright (c) 2012, Rodrigo Fuenzalida, Nicolas Massi (www.taip.com.ar / abc.taip.com.ar), with Reserved Font Name 'Pirata' · <a href=\"https://openfontlicense.org\" target=\"_blank\" rel=\"noopener\">SIL OFL 1.1</a> · <a href=\"https://github.com/google/fonts/tree/main/ofl/pirataone\" target=\"_blank\" rel=\"noopener\">github.com/google/fonts</a></li>\n              <li><b>Abril Fatface</b> — Copyright (c) 2011, TypeTogether (www.type-together.com), with Reserved Font Names \"Abril\" and \"Abril Fatface\" · <a href=\"https://openfontlicense.org\" target=\"_blank\" rel=\"noopener\">SIL OFL 1.1</a> · <a href=\"https://github.com/google/fonts/tree/main/ofl/abrilfatface\" target=\"_blank\" rel=\"noopener\">github.com/google/fonts</a></li>\n              <li><b>Dancing Script</b> — Copyright 2016 The Dancing Script Project Authors (https://github.com/googlefonts/DancingScript), with Reserved Font Name 'Dancing Script'. · <a href=\"https://openfontlicense.org\" target=\"_blank\" rel=\"noopener\">SIL OFL 1.1</a> · <a href=\"https://github.com/google/fonts/tree/main/ofl/dancingscript\" target=\"_blank\" rel=\"noopener\">github.com/google/fonts</a></li>\n              <li><b>UnifrakturMaguntia</b> — Copyright (c) 2010, j. 'mach' wust, with Reserved Font Name UnifrakturMaguntia. Copyright (c) 2009, Peter Wiegel. · <a href=\"https://openfontlicense.org\" target=\"_blank\" rel=\"noopener\">SIL OFL 1.1</a> · <a href=\"https://github.com/google/fonts/tree/main/ofl/unifrakturmaguntia\" target=\"_blank\" rel=\"noopener\">github.com/google/fonts</a></li>\n            "};
  // 언어는 페이지 주소로 정함: /en/pattern/은 HTML에서 window.FORCE_LANG = 'en'을 두고, 한국어 /pattern/은 항상 한국어.
  // (예전에 쓰던 저장 이름 crochet-ui-lang은 이제 읽지도 쓰지도 않음. 지우지도 않음)
  const FORCED_LANG = window.FORCE_LANG === 'en' ? 'en' : null;
  let LANG = FORCED_LANG || 'ko';
  function t(ko, vars){
    let str = (LANG === 'en' && Object.prototype.hasOwnProperty.call(I18N_EN, ko)) ? I18N_EN[ko] : ko;
    if(vars) str = str.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m));
    return str;
  }
  // 화면의 고정 문구 바꾸기: 처음 본 한국어 원문을 기억해 두고 언어에 맞게 교체
  const I18N_ATTRS = ['title', 'aria-label', 'placeholder', 'label'];
  const i18nOrig = new WeakMap();
  function translateStatic(){
    const skip = el => el.closest('script,style,textarea,[data-dyn],[data-i18n-html]');
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    const nodes = [];
    while(walker.nextNode()) nodes.push(walker.currentNode);
    nodes.forEach(n => {
      if(!n.parentElement || skip(n.parentElement)) return;
      if(!i18nOrig.has(n)){
        if(!/[가-힣]/.test(n.nodeValue)) return;
        i18nOrig.set(n, n.nodeValue);
      }
      const ko = i18nOrig.get(n);
      const key = ko.replace(/\s+/g, ' ').trim();
      const lead = ko.match(/^\s*/)[0], trail = ko.match(/\s*$/)[0];
      n.nodeValue = LANG === 'en' && I18N_EN[key] ? lead + I18N_EN[key] + trail : ko;
    });
    document.querySelectorAll('[title],[aria-label],[placeholder],optgroup[label]').forEach(el => {
      if(el.closest('[data-i18n-html]')) return;
      if(el.closest('[data-dyn]') && el.closest('[data-dyn]') !== el) return;
      I18N_ATTRS.forEach(a => {
        if(!el.hasAttribute(a)) return;
        const store = 'ko' + a.replace(/-/g, '');
        if(el.dataset[store] === undefined){
          if(!/[가-힣]/.test(el.getAttribute(a))) return;
          el.dataset[store] = el.getAttribute(a);
        }
        const ko = el.dataset[store];
        el.setAttribute(a, LANG === 'en' && I18N_EN[ko] ? I18N_EN[ko] : ko);
      });
    });
    document.querySelectorAll('[data-i18n-html]').forEach(el => {
      if(!el.dataset.koHtml) el.dataset.koHtml = el.innerHTML;
      const en = I18N_EN_HTML[el.dataset.i18nHtml];
      el.innerHTML = LANG === 'en' && en ? en : el.dataset.koHtml;
    });
    document.documentElement.lang = LANG;
    // 탭 제목은 <head>의 <title>을 그대로 씀 (영어 페이지는 HTML에 영어 제목이 있으므로 덮어쓰지 않음)
    if(!FORCED_LANG) document.title = '도안 만들기 (Crochet Pattern Maker) | 도트뜨개 Crochet Alpha';
  }

  /* ===== 화면 모드 (시스템 / 밝게 / 어둡게) ===== */
  let THEME_PREF = 'auto';
  try{ THEME_PREF = localStorage.getItem('crochet-ui-theme') || 'auto'; }catch(e){}
  const THEME = { labelBg:'#EAE3D2', labelInk:'#4E5045', badgeBg:'#24261F', badgeInk:'#FFFFFF' };
  function lumOf(c){
    const n = parseInt(String(c).slice(1), 16);
    if(isNaN(n)) return 255;
    return ((n>>16)&255)*0.299 + ((n>>8)&255)*0.587 + (n&255)*0.114;
  }
  function readThemeColors(){
    const cs = getComputedStyle(document.documentElement);
    const v = k => cs.getPropertyValue(k).trim();
    THEME.labelBg = v('--paper-2') || THEME.labelBg;
    THEME.labelInk = v('--ink-soft') || THEME.labelInk;
    THEME.badgeBg = v('--ink') || THEME.badgeBg;
    THEME.badgeInk = v('--paper') || THEME.badgeInk;
  }
  function applyThemeAttr(){
    if(THEME_PREF === 'auto') document.documentElement.removeAttribute('data-theme');
    else document.documentElement.setAttribute('data-theme', THEME_PREF);
    readThemeColors();
  }
  applyThemeAttr();

  /* ===== 색 추가 창 (헥스코드 입력) ===== */
  const hexModal = document.getElementById('hexModal');
  const hexText = document.getElementById('hexText');
  const hexNative = document.getElementById('hexNative');
  const hexPreview = document.getElementById('hexPreview');
  const hexOk = document.getElementById('hexOk');
  const hexErr = document.getElementById('hexErr');
  let hexCallback = null;
  function normHex(v){
    v = String(v || '').trim().replace(/^#/, '');
    if(/^[0-9a-fA-F]{3}$/.test(v)) v = v.split('').map(ch => ch + ch).join('');
    return /^[0-9a-fA-F]{6}$/.test(v) ? '#' + v.toUpperCase() : null;
  }
  function updateHexUI(fromNative){
    const c = normHex(hexText.value);
    hexOk.disabled = !c;
    hexErr.textContent = (!c && hexText.value.trim()) ? t('#RRGGBB 형식으로 입력해 주세요 (예: #FF8800)') : '';
    if(c){ hexPreview.style.background = c; if(!fromNative) hexNative.value = c.toLowerCase(); }
  }
  function openHexPicker(initial, title, cb, okLabel){
    hexCallback = cb;
    document.getElementById('hexTitle').textContent = t(title);
    hexOk.textContent = t(okLabel || '추가');
    const c = normHex(initial) || '#222222';
    hexText.value = c; hexNative.value = c.toLowerCase();
    updateHexUI();
    hexModal.classList.add('show');
    setTimeout(()=>{ hexText.focus(); hexText.select(); }, 30);
  }
  function closeHexPicker(){ hexModal.classList.remove('show'); hexCallback = null; }
  hexText.addEventListener('input', ()=>updateHexUI(false));
  hexNative.addEventListener('input', ()=>{ hexText.value = hexNative.value.toUpperCase(); updateHexUI(true); });
  function confirmHex(){
    const c = normHex(hexText.value);
    if(!c || !hexCallback) return;
    const cb = hexCallback; closeHexPicker(); cb(c);
  }
  hexOk.addEventListener('click', confirmHex);
  hexText.addEventListener('keydown', e=>{ if(e.key === 'Enter') confirmHex(); if(e.key === 'Escape') closeHexPicker(); });
  document.getElementById('hexCancel').addEventListener('click', closeHexPicker);
  hexModal.addEventListener('click', e=>{ if(e.target === hexModal) closeHexPicker(); });

  /* ===== 팔레트 칸 바꾸기 · 지우기 ===== */
  // 칠한 칸(gridData)에는 색 값이 직접 들어 있어서, 팔레트 칸을 바꾸거나 지워도 도안은 그대로임.
  // 고른 색을 한 번 더 누르거나(휴대폰) 오른쪽 클릭하면 이 대화상자가 열림.
  const swatchModal = document.getElementById('swatchModal');
  let swatchIdx = -1;
  function openSwatchMenu(i){
    const c = PRESET_COLORS[i];
    if(!c) return;
    swatchIdx = i;
    document.getElementById('swatchChip').style.background = c;
    document.getElementById('swatchTitle').textContent = c.toUpperCase();
    const only = PRESET_COLORS.length <= 1;
    document.getElementById('swatchDelete').disabled = only;
    document.getElementById('swatchNote').textContent = only
      ? t('색이 하나뿐이라 지울 수 없어요.')
      : t('지워도 이미 칠한 칸의 색은 그대로예요.');
    swatchModal.classList.add('show');
    document.addEventListener('keydown', swatchKey, true);
    setTimeout(()=>document.getElementById('swatchChange').focus(), 30);
  }
  function closeSwatchMenu(){
    swatchModal.classList.remove('show');
    document.removeEventListener('keydown', swatchKey, true);
  }
  function swatchKey(e){ if(e.key === 'Escape'){ e.stopPropagation(); closeSwatchMenu(); } }
  function afterPaletteEdit(){
    buildPalette();
    if(stamp) drawGrid();
    saveState();
  }
  document.getElementById('swatchChange').addEventListener('click', ()=>{
    const i = swatchIdx, old = PRESET_COLORS[i];
    closeSwatchMenu();
    if(!old) return;
    openHexPicker(old, '이 칸 색 바꾸기', c => {
      if(c === old.toUpperCase()) return;
      if(PRESET_COLORS.some((p, k) => k !== i && p.toUpperCase() === c)){ toast(t('이미 팔레트에 있는 색이에요')); return; }
      PRESET_COLORS[i] = c;
      if(activeColor === old) activeColor = c;
      afterPaletteEdit();
    }, '바꾸기');
  });
  document.getElementById('swatchDelete').addEventListener('click', ()=>{
    const i = swatchIdx, old = PRESET_COLORS[i];
    closeSwatchMenu();
    if(!old || PRESET_COLORS.length <= 1) return;
    PRESET_COLORS.splice(i, 1);
    // 지운 색을 쓰고 있었으면 그 자리로 당겨진 오른쪽 색을, 맨 끝이었으면 왼쪽 색을 고름
    if(activeColor === old) activeColor = PRESET_COLORS[i] || PRESET_COLORS[i-1];
    afterPaletteEdit();
    toast(t('팔레트에서 지웠어요. 칠한 칸은 그대로예요'));
  });
  document.getElementById('swatchCancel').addEventListener('click', closeSwatchMenu);
  swatchModal.addEventListener('click', e=>{ if(e.target === swatchModal) closeSwatchMenu(); });

  /* ===== 도안 만들기 (격자 배색) ===== */
  const canvas = document.getElementById('gridCanvas');
  const ctx = canvas.getContext('2d');
  const rowsInput = document.getElementById('rowsInput');
  const colsInput = document.getElementById('colsInput');
  const paletteEl = document.getElementById('palette');

  // 배경색: 칠하지 않은 칸(빈칸)이 보이는 색. 칸 데이터는 그대로 빈칸이라
  // 나중에 배경색을 바꿔도 칠한 무늬는 유지되고 바탕만 바뀜.
  const DEFAULT_BG = '#FFFFFF';
  let bgColor = DEFAULT_BG;
  const isLight = c => {
    const n = parseInt(c.slice(1), 16);
    return (((n>>16)&255)*0.299 + ((n>>8)&255)*0.587 + (n&255)*0.114) > 225;
  };
  function renderBgPalette(){
    const el = document.getElementById('bgPalette');
    el.innerHTML = '';
    const list = [DEFAULT_BG, ...PRESET_COLORS.filter(c => c.toUpperCase() !== DEFAULT_BG)];
    if(!list.some(c => c.toUpperCase() === bgColor.toUpperCase())) list.push(bgColor);
    list.forEach(c => {
      const sw = document.createElement('div');
      sw.className = 'swatch' + (isLight(c) ? ' light' : '') + (c.toUpperCase() === bgColor.toUpperCase() ? ' selected' : '');
      sw.style.background = c;
      sw.title = c.toUpperCase() === DEFAULT_BG ? t('흰색 (기본)') : c;
      sw.addEventListener('click', ()=>setBg(c));
      el.appendChild(sw);
    });
    const add = document.createElement('button');
    add.type = 'button'; add.className = 'bg-add'; add.textContent = '+'; add.title = t('다른 색 (헥스코드 입력)');
    add.addEventListener('click', ()=>openHexPicker(bgColor, '배경색 고르기', c=>setBg(c)));
    el.appendChild(add);
  }
  function setBg(c){
    if(c === bgColor) return;
    bgColor = c;
    renderBgPalette();
    buildPalette();
    drawGrid();
    saveState();
  }

  const DEFAULT_PALETTE = ['#222222', '#D32F2F', '#FBC02D', '#1976D2', '#388E3C']; // 검정·빨강·노랑·파랑·초록
  const PRESET_COLORS = DEFAULT_PALETTE.slice();

  let rows = 20, cols = 20;
  let gridData = [];
  let activeColor = PRESET_COLORS[0]; // null = 지우개
  let cellW = 16, cellH = 16; // 화면에서 한 칸의 너비·높이 (실제 비율로 보기를 켜면 서로 달라짐)
  let zoomLevel = 1;
  // 게이지: 10cm 안의 코 수(gaugeSt)·단 수(gaugeRow). 한 칸의 높이/너비 = gaugeSt / gaugeRow
  let gaugeSt = 10, gaugeRow = 10;
  let realRatio = false; // 실제 비율로 보기
  const GAUGE_MIN = 1, GAUGE_MAX = 99;
  function cellAspect(){ return realRatio ? gaugeSt / gaugeRow : 1; }
  let painting = false;
  let flipped = false;
  let currentRow = 1; // 맨 아래를 1단으로 세는 현재 작업 단
  let knitMode = false; // '작업 시작하기' 화면 (도구를 숨기고 뜨기에 집중)
  let knitTap = null;   // 작업 화면에서 누른 위치 (끌었는지 톡 눌렀는지 구분)

  function buildPalette(){
    paletteEl.innerHTML = '';
    PRESET_COLORS.forEach((c, i)=>{
      const sw = document.createElement('div');
      sw.className = 'swatch' + (c === activeColor ? ' selected' : '');
      sw.style.background = c;
      sw.title = c === activeColor ? t('한 번 더 누르면 바꾸기·지우기') : c.toUpperCase();
      // 오른쪽 클릭(컴퓨터)으로도 바로 바꾸기·지우기
      sw.addEventListener('contextmenu', e=>{
        e.preventDefault();
        if(activeColor !== c){ activeColor = c; buildPalette(); if(stamp) drawGrid(); saveState(); }
        openSwatchMenu(i);
      });
      sw.addEventListener('click', ()=>{
        if(c === activeColor){ openSwatchMenu(i); return; } // 고른 색을 한 번 더 누르면 바꾸기·지우기
        activeColor = c;
        buildPalette();
        if(stamp) drawGrid();
        saveState();
      });
      paletteEl.appendChild(sw);
    });
    const eraser = document.createElement('div');
    eraser.className = 'swatch eraser' + (activeColor === null ? ' selected' : '');
    eraser.title = t('지우개 (배경색으로 되돌림)');
    if(bgColor !== DEFAULT_BG) eraser.style.background = bgColor;
    eraser.addEventListener('click', ()=>{ activeColor = null; buildPalette(); if(stamp) drawGrid(); saveState(); });
    paletteEl.appendChild(eraser);

    const addBtn = document.createElement('button');
    addBtn.type = 'button';
    addBtn.className = 'add-color';
    addBtn.textContent = '+';
    addBtn.title = t('색 추가 (헥스코드 입력)');
    addBtn.addEventListener('click', ()=>openHexPicker(activeColor || '#222222', '칠할 색 추가', c=>{
      if(!PRESET_COLORS.some(p => p.toUpperCase() === c)) PRESET_COLORS.push(c);
      activeColor = PRESET_COLORS.find(p => p.toUpperCase() === c);
      buildPalette();
      if(stamp) drawGrid();
      saveState();
    }));
    paletteEl.appendChild(addBtn);
    if(typeof refreshReplaceUI === 'function') refreshReplaceUI(true);
    renderBgPalette();
    if(typeof buildDecorRow === 'function' && document.getElementById('decorRow')) { try{ buildDecorRow(); }catch(e){} }
    if(typeof buildUserDecors === 'function') { try{ buildUserDecors(); }catch(e){} }
    if(typeof renderShadowUI === 'function' && document.getElementById('shadowPalette')) { try{ renderShadowUI(); }catch(e){} }
  }

  let undoStack = [];
  const MAX_UNDO = 30;
  let redoStack = [];
  // 새 작업을 기록하면 다시하기 기록은 비움 (되돌리기만큼 다시하기 가능)
  function recordUndo(snap){
    undoStack.push(snap);
    if(undoStack.length > MAX_UNDO) undoStack.shift();
    redoStack = [];
    updateUndoButtons();
  }
  function pushUndo(){ recordUndo({ rows, cols, data: gridData.slice() }); }
  // 배경색까지 바꾸는 작업(도안 열기)의 기록에만 bg가 들어 있음.
  // 그 기록을 되돌리거나 다시할 때는 반대쪽 기록에도 지금 배경색을 담아 둠.
  function currentSnap(like){
    const s = { rows, cols, data: gridData.slice() };
    if(like && like.bg) s.bg = bgColor;
    return s;
  }
  function restoreSnap(snap){
    rows = snap.rows; cols = snap.cols; gridData = snap.data;
    rowsInput.value = rows; colsInput.value = cols;
    if(snap.bg && snap.bg !== bgColor){ bgColor = snap.bg; buildPalette(); }
    sizeCanvas();
    drawGrid();
    saveState();
  }
  function undo(){
    if(stamp){ cancelStamp(); updateUndoButtons(); return; } // 옮기던 글자가 있으면 먼저 취소
    if(undoStack.length === 0) return;
    const snap = undoStack.pop();
    redoStack.push(currentSnap(snap));
    restoreSnap(snap);
    updateUndoButtons();
  }
  function redo(){
    if(stamp || redoStack.length === 0) return;
    const snap = redoStack.pop();
    undoStack.push(currentSnap(snap));
    if(undoStack.length > MAX_UNDO) undoStack.shift();
    restoreSnap(snap);
    updateUndoButtons();
  }
  function updateUndoButtons(){
    const u = document.getElementById('undoBtn'), r = document.getElementById('redoBtn');
    if(u) u.disabled = undoStack.length === 0 && !stamp;
    if(r) r.disabled = redoStack.length === 0 || !!stamp;
  }

  function initGrid(r, c){
    rows = r; cols = c;
    gridData = new Array(rows * cols).fill(null);
    sizeCanvas();
    drawGrid();
  }

  function padGrid(top, bottom, left, right){
    pushUndo();
    const newRows = rows + top + bottom;
    const newCols = cols + left + right;
    const newData = new Array(newRows * newCols).fill(null);
    for(let y=0; y<rows; y++){
      for(let x=0; x<cols; x++){
        newData[(y+top)*newCols + (x+left)] = gridData[y*cols+x];
      }
    }
    rows = newRows; cols = newCols;
    gridData = newData;
    rowsInput.value = rows; colsInput.value = cols;
    sizeCanvas();
    drawGrid();
    saveState();
  }

  // 여백 줄이기: 가장자리 줄을 한 칸씩 없앰. 그린 칸이 잘려 나가지 않도록
  // 없앨 줄이 모두 빈칸일 때만 줄이고, 아니면 알려 주고 그대로 둠.
  function trimGrid(top, bottom, left, right){
    if(stamp) cancelStamp();
    const newRows = rows - top - bottom;
    const newCols = cols - left - right;
    if(newRows < 1 || newCols < 1){ toast(t('더 줄일 수 없어요')); return; }
    for(let y=0; y<rows; y++){
      for(let x=0; x<cols; x++){
        const inside = y >= top && y < rows - bottom && x >= left && x < cols - right;
        if(!inside && gridData[y*cols+x] !== null){
          toast(t('가장자리에 칠한 칸이 있어서 줄일 수 없어요'));
          return;
        }
      }
    }
    pushUndo();
    const newData = new Array(newRows * newCols);
    for(let y=0; y<newRows; y++){
      for(let x=0; x<newCols; x++){
        newData[y*newCols + x] = gridData[(y+top)*cols + (x+left)];
      }
    }
    rows = newRows; cols = newCols;
    gridData = newData;
    rowsInput.value = rows; colsInput.value = cols;
    currentRow = Math.min(currentRow, rows);
    sizeCanvas();
    drawGrid();
    saveState();
  }

  const LABEL_SIZE = 24;

  function sizeCanvas(){
    // 캔버스 영역(여백 제외)의 너비와 높이에 모두 맞춰서, '맞춤'일 때 격자 전체가 한 화면에 보이도록
    const wrapEl = canvas.parentElement;
    const cs = getComputedStyle(wrapEl);
    const padX = parseFloat(cs.paddingLeft) + parseFloat(cs.paddingRight);
    const padY = parseFloat(cs.paddingTop) + parseFloat(cs.paddingBottom);
    const availW = Math.max(120, wrapEl.clientWidth - padX);
    const availH = wrapEl.clientHeight - padY;
    // 칸 너비를 기준으로 맞춤. 높이 = 너비 × 비율이므로, 세로로 들어갈 너비는 (높이 ÷ 단 수) ÷ 비율
    const aspect = cellAspect();
    const fitW = Math.floor((availW - LABEL_SIZE) / cols);
    const fitH = availH > 120 ? Math.floor((availH - LABEL_SIZE) / rows / aspect) : fitW;
    const baseCellSize = Math.max(4, Math.min(fitW, Math.max(fitH, 8)));
    cellW = Math.max(1, Math.round(baseCellSize * zoomLevel));
    cellH = Math.max(1, Math.round(cellW * aspect));
    const dpr = window.devicePixelRatio || 1;
    const cssW = LABEL_SIZE + cellW * cols;
    const cssH = LABEL_SIZE + cellH * rows;
    canvas.style.width = cssW + 'px';
    canvas.style.height = cssH + 'px';
    canvas.width = cssW * dpr;
    canvas.height = cssH * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  // 격자 숫자 라벨: 5, 10, 15 … 에 더해 마지막 칸/단(n)도 항상 표시.
  // 마지막 숫자가 바로 앞 5단위 숫자와 너무 붙으면(minGap칸 미만) 앞 숫자를 빼서 겹치지 않게 함.
  function gridLabelNums(n, minGap){
    const nums = [];
    for(let k=5; k<=n; k+=5) nums.push(k);
    if(n > 0 && n % 5 !== 0){
      if(nums.length && n - nums[nums.length-1] < minGap) nums.pop();
      nums.push(n);
    }
    return nums;
  }

  function drawGrid(){
    const gridW = cellW * cols;
    const gridH = cellH * rows;
    const cellMin = Math.min(cellW, cellH); // 글자·테두리 크기는 칸의 짧은 쪽에 맞춤
    const cssW = LABEL_SIZE + gridW;
    const cssH = LABEL_SIZE + gridH;
    ctx.clearRect(0, 0, cssW, cssH);

    // 라벨 영역 배경
    ctx.fillStyle = THEME.labelBg;
    ctx.fillRect(0, 0, cssW, LABEL_SIZE);
    ctx.fillRect(0, 0, LABEL_SIZE, cssH);

    const dispCol = (j) => flipped ? (cols - 1 - j) : j;

    // 현재 단 강조 (맨 아래를 1단으로 계산), 격자 크기가 바뀌어도 범위를 벗어나지 않도록 보정
    currentRow = Math.max(1, Math.min(rows, currentRow));
    const rowLabelEl = document.getElementById('rowLabel');
    if(rowLabelEl) rowLabelEl.textContent = t('{n}단', {n: currentRow});
    const highlightRowIdx = rows - currentRow;

    // cells: 바탕을 한 번에 칠한 뒤 칠한 칸만 그림 (색이 바뀔 때만 fillStyle 변경)
    ctx.fillStyle = bgColor;
    ctx.fillRect(LABEL_SIZE, LABEL_SIZE, gridW, gridH);
    let lastFill = null;
    for(let i=0; i<rows; i++){
      const rowBase = i*cols, y = LABEL_SIZE + i*cellH;
      for(let j=0; j<cols; j++){
        const color = gridData[rowBase + j];
        if(color == null) continue;
        if(color !== lastFill){ ctx.fillStyle = color; lastFill = color; }
        ctx.fillRect(LABEL_SIZE + dispCol(j)*cellW, y, cellW, cellH);
      }
    }

    // grid lines (항상 표시, 5칸마다 굵게)
    // 배경색이 어두우면 밝은 선으로 (야간 모드·어두운 배경색에서도 격자가 보이도록)
    const darkBg = lumOf(bgColor) < 110;
    const lineBold = darkBg ? 'rgba(255,255,255,0.45)' : 'rgba(36,38,31,0.4)';
    const lineThin = darkBg ? 'rgba(255,255,255,0.2)' : 'rgba(36,38,31,0.2)';
    [false, true].forEach(boldPass => {
      ctx.strokeStyle = boldPass ? lineBold : lineThin;
      ctx.lineWidth = boldPass ? 1.6 : 1;
      ctx.beginPath();
      for(let i=0; i<=rows; i++){
        if(((rows - i) % 5 === 0) !== boldPass) continue; // 맨 아래를 1단으로 세므로 굵은 선도 아래 기준
        ctx.moveTo(LABEL_SIZE, LABEL_SIZE + i*cellH + 0.5);
        ctx.lineTo(cssW, LABEL_SIZE + i*cellH + 0.5);
      }
      for(let j=0; j<=cols; j++){
        if((j % 5 === 0) !== boldPass) continue;
        ctx.moveTo(LABEL_SIZE + j*cellW + 0.5, LABEL_SIZE);
        ctx.lineTo(LABEL_SIZE + j*cellW + 0.5, cssH);
      }
      ctx.stroke();
    });

    // 현재 단 강조 표시 (셀 영역을 가리지 않도록 왼쪽 여백 안에만 그림)
    if(highlightRowIdx >= 0 && highlightRowIdx < rows){
      const markerY = LABEL_SIZE + highlightRowIdx*cellH + cellH/2;
      void markerY; // 번호표·테두리로 표시 (아래에서 그림)
    }

    // 작업 화면: 지금 단이 눈에 띄도록 나머지 단을 살짝 흐리게
    if(knitMode && highlightRowIdx >= 0 && highlightRowIdx < rows){
      ctx.fillStyle = darkBg ? 'rgba(0,0,0,0.4)' : 'rgba(243,239,228,0.45)';
      ctx.fillRect(LABEL_SIZE, LABEL_SIZE, gridW, highlightRowIdx*cellH);
      ctx.fillRect(LABEL_SIZE, LABEL_SIZE + (highlightRowIdx+1)*cellH, gridW, gridH - (highlightRowIdx+1)*cellH);
    }

    // 현재 작업 단: 칸 색을 가리지 않도록 테두리로만 강조
    if(highlightRowIdx >= 0 && highlightRowIdx < rows){
      const y0 = LABEL_SIZE + highlightRowIdx*cellH;
      ctx.lineWidth = Math.max(2, Math.min(3, cellMin/6));
      ctx.strokeStyle = '#24261F';
      ctx.strokeRect(LABEL_SIZE + 1, y0 + 0.5, cols*cellW - 1, cellH);
      ctx.lineWidth = 1;
      ctx.strokeStyle = '#FFFFFF';
      ctx.strokeRect(LABEL_SIZE + 2.5, y0 + 2, cols*cellW - 4, cellH - 3);
    }

    // 작업 화면: 지금 단의 같은 색 묶음마다 몇 코인지 숫자로 (예: 빨강 6 · 흰색 1 · 빨강 2)
    if(knitMode && highlightRowIdx >= 0 && highlightRowIdx < rows && cellMin >= 9){
      const y = LABEL_SIZE + highlightRowIdx*cellH + cellH/2;
      ctx.font = '700 ' + Math.min(15, Math.round(cellMin*0.7)) + 'px "IBM Plex Mono", ui-monospace, monospace';
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      currentRowRuns().forEach(r => {
        const x = LABEL_SIZE + (r.start + r.len/2)*cellW;
        const dark = lumOf(r.color || bgColor) < 140;
        ctx.lineWidth = 3; ctx.lineJoin = 'round';
        ctx.strokeStyle = dark ? 'rgba(0,0,0,0.55)' : 'rgba(255,255,255,0.85)';
        ctx.strokeText(String(r.len), x, y + 0.5);
        ctx.fillStyle = dark ? '#FFFFFF' : '#24261F';
        ctx.fillText(String(r.len), x, y + 0.5);
      });
      ctx.lineWidth = 1;
    }

    // 5칸 간격 숫자 라벨
    ctx.fillStyle = THEME.labelInk;
    ctx.font = '600 10.5px "IBM Plex Mono", ui-monospace, monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    for(const col of gridLabelNums(cols, Math.ceil(20 / cellW))){
      const x = LABEL_SIZE + dispCol(col-1)*cellW + cellW/2;
      ctx.fillText(String(col), x, LABEL_SIZE/2);
    }
    for(const row of gridLabelNums(rows, Math.ceil(12 / cellH))){
      if(row === currentRow) continue; // 현재 단 번호와 겹치지 않도록
      const y = LABEL_SIZE + (rows - row)*cellH + cellH/2; // 아래에서부터 row단
      ctx.fillText(String(row), LABEL_SIZE/2, y);
    }

    // 현재 단 번호는 5칸 간격이 아니어도 항상 강조 표시
    if(highlightRowIdx >= 0 && highlightRowIdx < rows){
      const y = LABEL_SIZE + highlightRowIdx*cellH + cellH/2;
      const h = Math.min(16, Math.max(12, cellH));
      ctx.fillStyle = THEME.badgeBg;
      ctx.beginPath();
      if(ctx.roundRect) ctx.roundRect(1, y - h/2, LABEL_SIZE - 3, h, 4); else ctx.rect(1, y - h/2, LABEL_SIZE - 3, h);
      ctx.fill();
      ctx.fillStyle = THEME.badgeInk;
      ctx.font = '700 10.5px "IBM Plex Mono", ui-monospace, monospace';
      ctx.fillText(String(currentRow), (LABEL_SIZE - 2)/2, y + 0.5);
    }
    if(typeof drawStampOverlay === 'function') drawStampOverlay();
    if(typeof drawSelRect === 'function') drawSelRect();
    if(typeof updateClipButtons === 'function') updateClipButtons();
    if(typeof updateStatus === 'function') updateStatus();
    if(typeof refreshReplaceUI === 'function') refreshReplaceUI();
    if(knitMode && typeof updateKnitBar === 'function') updateKnitBar();
  }

  // 지금 작업 단을 같은 색끼리 묶음 (화면에 보이는 왼쪽→오른쪽 순서, start는 화면 기준 칸 위치)
  function currentRowRuns(){
    const i = rows - currentRow, runs = [];
    if(i < 0 || i >= rows) return runs;
    for(let d=0; d<cols; d++){
      const j = flipped ? (cols - 1 - d) : d;
      const color = gridData[i*cols + j] || null;
      const last = runs[runs.length-1];
      if(last && last.color === color) last.len++;
      else runs.push({ color, start: d, len: 1 });
    }
    return runs;
  }

  let lastPaint = null;
  function drawCellQuick(i, j){
    const x = LABEL_SIZE + (flipped ? (cols - 1 - j) : j) * cellW, y = LABEL_SIZE + i*cellH;
    ctx.fillStyle = gridData[i*cols+j] || bgColor;
    if(cellW >= 4 && cellH >= 4) ctx.fillRect(x + 1, y + 1, cellW - 1.5, cellH - 1.5);
    else ctx.fillRect(x, y, cellW, cellH);
  }
  function paintAt(clientX, clientY){
    const c = cellFromPoint(clientX, clientY);
    if(!c) return;
    // 직전 칸에서 지금 칸까지 직선으로 이어 칠함 (빠르게 끌 때 끊김 방지)
    const from = lastPaint || c;
    const di = c.i - from.i, dj = c.j - from.j, steps = Math.max(Math.abs(di), Math.abs(dj), 1);
    for(let s=1; s<=steps || (s === 1 && !lastPaint); s++){
      const i = Math.round(from.i + di*s/steps), j = Math.round(from.j + dj*s/steps);
      const idx = i*cols + j;
      if(gridData[idx] !== activeColor){
        gridData[idx] = activeColor;
        strokeChanged = true;
        drawCellQuick(i, j);
      }
      if(!lastPaint) break;
    }
    lastPaint = c;
  }

  // 한 번의 터치(드래그 포함) 동안 실제로 칸이 바뀐 경우에만 실행 취소 기록을 남김
  let strokeSnapshot = null, strokeChanged = false;
  function endStroke(){
    lastPaint = null;
    if(painting && strokeChanged && strokeSnapshot){
      recordUndo(strokeSnapshot);
      saveState();
      drawGrid(); // 칠하는 동안 생략했던 단 테두리·글자 등을 다시 그림
    }
    painting = false; strokeSnapshot = null; strokeChanged = false;
  }

  function cellFromPoint(clientX, clientY){
    const rect = canvas.getBoundingClientRect();
    let j = Math.floor((clientX - rect.left - LABEL_SIZE) / cellW);
    const i = Math.floor((clientY - rect.top - LABEL_SIZE) / cellH);
    if(i<0 || j<0 || i>=rows || j>=cols) return null;
    if(flipped) j = cols - 1 - j;
    return { i, j };
  }

  // 같은 색으로 이어진(상하좌우) 칸을 한 번에 칠하기
  function floodFill(si, sj){
    const target = gridData[si*cols+sj];
    if(target === activeColor) return false;
    const stack = [si*cols+sj];
    const seen = new Uint8Array(rows*cols);
    while(stack.length){
      const idx = stack.pop();
      if(seen[idx]) continue;
      seen[idx] = 1;
      if(gridData[idx] !== target) continue;
      gridData[idx] = activeColor;
      const y = Math.floor(idx / cols), x = idx % cols;
      if(y > 0) stack.push(idx - cols);
      if(y < rows-1) stack.push(idx + cols);
      if(x > 0) stack.push(idx - 1);
      if(x < cols-1) stack.push(idx + 1);
    }
    return true;
  }

  let tool = 'paint'; // 'paint' | 'fill'
  const toolPaintBtn = document.getElementById('toolPaintBtn');
  const toolFillBtn = document.getElementById('toolFillBtn');
  function setTool(t){
    tool = t;
    toolPaintBtn.classList.toggle('active', t === 'paint');
    toolFillBtn.classList.toggle('active', t === 'fill');
    document.getElementById('toolSelectBtn').classList.toggle('active', t === 'select');
  }
  document.getElementById('toolSelectBtn').addEventListener('click', ()=>{
    setTool('select');
    if(!stamp) toast(t('격자를 끌어서 옮기거나 복사할 부분을 골라주세요'));
  });
  toolPaintBtn.addEventListener('click', ()=>setTool('paint'));
  toolFillBtn.addEventListener('click', ()=>setTool('fill'));

  let drawPending = false;
  function requestDraw(){
    if(drawPending) return;
    drawPending = true;
    requestAnimationFrame(() => { drawPending = false; drawGrid(); });
  }
  let stampDrag = null;
  /* ===== 선택 도구: 영역을 골라 떠 있는 상태로 들어올림 → 옮기기·복사·삭제 ===== */
  let selDrag = null, selRect = null;
  function cellFromPointClamped(clientX, clientY){
    const rect = canvas.getBoundingClientRect();
    let j = Math.floor((clientX - rect.left - LABEL_SIZE) / cellW);
    let i = Math.floor((clientY - rect.top - LABEL_SIZE) / cellH);
    i = Math.max(0, Math.min(rows - 1, i)); j = Math.max(0, Math.min(cols - 1, j));
    if(flipped) j = cols - 1 - j;
    return { i, j };
  }
  function drawSelRect(){
    if(!selRect) return;
    const i0 = Math.min(selRect.i0, selRect.i1), i1 = Math.max(selRect.i0, selRect.i1);
    let j0 = Math.min(selRect.j0, selRect.j1), j1 = Math.max(selRect.j0, selRect.j1);
    if(flipped){ const a = cols - 1 - j1, b = cols - 1 - j0; j0 = a; j1 = b; }
    ctx.save();
    ctx.fillStyle = 'rgba(31,92,82,0.12)';
    ctx.fillRect(LABEL_SIZE + j0*cellW, LABEL_SIZE + i0*cellH, (j1-j0+1)*cellW, (i1-i0+1)*cellH);
    ctx.setLineDash([5, 4]); ctx.lineWidth = 2; ctx.strokeStyle = '#1F5C52';
    ctx.strokeRect(LABEL_SIZE + j0*cellW + 1, LABEL_SIZE + i0*cellH + 1, (j1-j0+1)*cellW - 2, (i1-i0+1)*cellH - 2);
    ctx.restore();
  }
  // 고른 영역의 칠한 칸만 떼어내서 떠 있는 상태로. 붙어 있는 덩어리마다 조각으로 나눠 '하나씩 옮기기'도 가능
  function liftSelection(r){
    const i0 = Math.min(r.i0, r.i1), i1 = Math.max(r.i0, r.i1);
    const j0 = Math.min(r.j0, r.j1), j1 = Math.max(r.j0, r.j1);
    const W = j1 - j0 + 1, H = i1 - i0 + 1;
    const colors = [], vals = new Uint8Array(W*H);
    for(let y=0; y<H; y++) for(let x=0; x<W; x++){
      const c = gridData[(i0+y)*cols + (j0+x)];
      if(c == null) continue;
      let k = colors.indexOf(c);
      if(k < 0){ if(colors.length >= 250){ k = 0; } else { colors.push(c); k = colors.length - 1; } }
      vals[y*W+x] = k + 3;
    }
    if(!vals.some(v => v)){ drawGrid(); toast(t('고른 곳에 칠한 칸이 없어요')); return; }
    // 8방향으로 이어진 덩어리 찾기
    const lab = new Int32Array(W*H).fill(-1), comps = [];
    for(let s=0; s<W*H; s++){
      if(!vals[s] || lab[s] >= 0) continue;
      const id = comps.length, stack = [s], cells = [];
      lab[s] = id;
      while(stack.length){
        const q = stack.pop(); cells.push(q);
        const qy = Math.floor(q / W), qx = q % W;
        for(let dy=-1; dy<=1; dy++) for(let dx=-1; dx<=1; dx++){
          const ny = qy+dy, nx = qx+dx;
          if(ny < 0 || nx < 0 || ny >= H || nx >= W) continue;
          const n = ny*W + nx;
          if(vals[n] && lab[n] < 0){ lab[n] = id; stack.push(n); }
        }
      }
      comps.push(cells);
    }
    let mx = Infinity, my = Infinity;
    const pieces = comps.map(cells => {
      let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
      cells.forEach(q => { const y = Math.floor(q/W), x = q%W; x0 = Math.min(x0,x); x1 = Math.max(x1,x); y0 = Math.min(y0,y); y1 = Math.max(y1,y); });
      const w = x1-x0+1, h = y1-y0+1, data = new Uint8Array(w*h);
      cells.forEach(q => { const y = Math.floor(q/W), x = q%W; data[(y-y0)*w + (x-x0)] = vals[q]; });
      mx = Math.min(mx, x0); my = Math.min(my, y0);
      return { data, w, h, ox: x0, oy: y0 };
    });
    pieces.forEach(p => { p.ox -= mx; p.oy -= my; });
    const snap = { rows, cols, data: gridData.slice() };
    for(let y=0; y<H; y++) for(let x=0; x<W; x++) if(vals[y*W+x]) gridData[(i0+y)*cols + (j0+x)] = null;
    startStamp({ pieces, colors }, { decor: true, lifted: true, noExpand: true, snap, at: { x: j0 + mx, y: i0 + my } });
  }

  /* ===== 복사 · 붙여넣기 · 삭제 ===== */
  let clipboard = null;
  function updateClipButtons(){
    const c = document.getElementById('copyBtn'), p = document.getElementById('pasteBtn');
    if(c) c.disabled = !stamp;
    if(p) p.disabled = !clipboard;
  }
  function copyStamp(){
    if(!stamp){ toast(t('선택 도구로 영역을 고르거나 글자·장식을 띄운 뒤 복사해주세요')); return; }
    const colors = [];
    const idx = c => { let k = colors.indexOf(c); if(k < 0){ colors.push(c); k = colors.length - 1; } return k + 3; };
    const pieces = stamp.pieces.map(p => {
      const d = new Uint8Array(p.w*p.h);
      for(let k=0; k<d.length; k++){
        const v = p.data[k]; if(!v) continue;
        const col = stampColor(v); if(col == null) continue;
        d[k] = idx(col);
      }
      return { data: d, w: p.w, h: p.h, ox: p.ox, oy: p.oy };
    });
    clipboard = { pieces, colors, x: stamp.x, y: stamp.y };
    updateClipButtons();
    toast(t('복사했어요. 붙여넣기로 몇 개든 넣을 수 있어요'));
  }
  function pasteClipboard(){
    if(!clipboard) return;
    if(stamp) placeStamp(); // 떠 있던 것은 먼저 그 자리에 놓기
    const pieces = clipboard.pieces.map(p => ({ data: p.data.slice(), w: p.w, h: p.h, ox: p.ox, oy: p.oy }));
    // 원래 자리에서 오른쪽 아래로 2칸 비켜서 붙임
    clipboard.x += 2; clipboard.y += 2;
    startStamp({ pieces, colors: clipboard.colors.slice() }, { decor: true, paste: true, at: { x: clipboard.x, y: clipboard.y } });
    clampStamp(); drawGrid();
  }
  function deleteStamp(){
    if(!stamp) return;
    if(stamp.lifted){
      // 떼어낸 부분을 지운 상태로 확정 (되돌리기로 복구 가능)
      recordUndo(stamp.snap);
      endStamp(); saveState();
      toast(t('지웠어요'));
    } else cancelStamp();
  }
  document.getElementById('copyBtn').addEventListener('click', copyStamp);
  document.getElementById('pasteBtn').addEventListener('click', pasteClipboard);
  document.getElementById('stampCopyBtn').addEventListener('click', copyStamp);
  document.getElementById('stampDeleteBtn').addEventListener('click', deleteStamp);
  // 단축키: Ctrl+C / Ctrl+X / Ctrl+V, Delete, Esc, Enter
  document.addEventListener('keydown', e=>{
    const tg = e.target;
    if(tg && (tg.tagName === 'INPUT' || tg.tagName === 'TEXTAREA' || tg.tagName === 'SELECT')) return;
    const k = e.code;
    if(e.ctrlKey || e.metaKey){
      if(k === 'KeyC'){ if(stamp){ e.preventDefault(); copyStamp(); } }
      else if(k === 'KeyX'){ if(stamp){ e.preventDefault(); copyStamp(); deleteStamp(); } }
      else if(k === 'KeyV'){ if(clipboard){ e.preventDefault(); pasteClipboard(); } }
      return;
    }
    if(!stamp) return;
    if(k === 'Delete' || k === 'Backspace'){ e.preventDefault(); deleteStamp(); }
    else if(k === 'Escape'){ e.preventDefault(); cancelStamp(); }
    else if(k === 'Enter'){ e.preventDefault(); placeStamp(); }
    else if(k === 'ArrowLeft'){ e.preventDefault(); nudge(-1, 0); }
    else if(k === 'ArrowRight'){ e.preventDefault(); nudge(1, 0); }
    else if(k === 'ArrowUp'){ e.preventDefault(); nudge(0, -1); }
    else if(k === 'ArrowDown'){ e.preventDefault(); nudge(0, 1); }
  });
  canvas.addEventListener('pointerdown', (e)=>{
    // 글자 입력칸에 포커스가 남아 있으면 Ctrl+Z가 글자 입력 취소로 가므로, 격자를 누르면 포커스 해제
    if(document.activeElement && document.activeElement !== document.body) document.activeElement.blur();
    if(knitMode){ // 작업 화면에서는 칠하지 않음. 끌지 않고 톡 누르면(손을 뗄 때) 그 단을 작업 단으로
      knitTap = { x: e.clientX, y: e.clientY };
      return;
    }
    if(stamp){
      if(stamp.mode === 'letter'){
        const c = cellFromPoint(e.clientX, e.clientY);
        const k = c ? pieceAt(c.i, c.j) : -1;
        stamp.sel = k;
        drawGrid();
        if(k < 0) return;
        const p = stamp.pieces[k];
        stampDrag = { sx: e.clientX, sy: e.clientY, piece: k, wx: stamp.x + p.ox, wy: stamp.y + p.oy };
        canvas.setPointerCapture(e.pointerId);
        return;
      }
      stampDrag = { sx: e.clientX, sy: e.clientY, x: stamp.x, y: stamp.y };
      canvas.setPointerCapture(e.pointerId);
      return;
    }
    if(tool === 'select'){
      const c = cellFromPointClamped(e.clientX, e.clientY);
      selDrag = { i0: c.i, j0: c.j };
      selRect = { i0: c.i, j0: c.j, i1: c.i, j1: c.j };
      canvas.setPointerCapture(e.pointerId);
      drawGrid();
      return;
    }
    if(tool === 'fill'){
      const c = cellFromPoint(e.clientX, e.clientY);
      if(!c) return;
      const snap = { rows, cols, data: gridData.slice() };
      if(floodFill(c.i, c.j)){
        recordUndo(snap);
        drawGrid();
        saveState();
      }
      return;
    }
    painting = true;
    lastPaint = null;
    strokeSnapshot = { rows, cols, data: gridData.slice() };
    strokeChanged = false;
    canvas.setPointerCapture(e.pointerId);
    paintAt(e.clientX, e.clientY);
  });
  canvas.addEventListener('pointermove', (e)=>{
    if(selDrag){
      const c = cellFromPointClamped(e.clientX, e.clientY);
      if(c.i !== selRect.i1 || c.j !== selRect.j1){ selRect.i1 = c.i; selRect.j1 = c.j; requestDraw(); }
      return;
    }
    if(stampDrag && stamp && stampDrag.piece != null){
      const dx = Math.round((e.clientX - stampDrag.sx) / cellW);
      const dy = Math.round((e.clientY - stampDrag.sy) / cellH);
      const p = stamp.pieces[stampDrag.piece];
      const nx = stampDrag.wx + (flipped ? -dx : dx), ny = stampDrag.wy + dy;
      if(nx !== stamp.x + p.ox || ny !== stamp.y + p.oy) movePiece(stampDrag.piece, nx, ny);
      return;
    }
    if(stampDrag && stamp){
      const dx = Math.round((e.clientX - stampDrag.sx) / cellW);
      const dy = Math.round((e.clientY - stampDrag.sy) / cellH);
      const nx = stampDrag.x + (flipped ? -dx : dx), ny = stampDrag.y + dy;
      if(nx !== stamp.x || ny !== stamp.y){
        stamp.x = nx; stamp.y = ny; stamp.moved = true; clampStamp(); requestDraw();
      }
      return;
    }
    if(!painting) return;
    paintAt(e.clientX, e.clientY);
  });
  canvas.addEventListener('pointerup', (e)=>{
    if(knitMode){
      const tap = knitTap; knitTap = null;
      if(tap && Math.hypot(e.clientX - tap.x, e.clientY - tap.y) < 10){
        const c = cellFromPoint(e.clientX, e.clientY);
        if(c){ currentRow = rows - c.i; applyRowLabel(); }
      }
      return;
    }
    if(selDrag){
      selDrag = null;
      const r = selRect; selRect = null;
      liftSelection(r);
      return;
    }
    const wasDragging = !!stampDrag;
    stampDrag = null;
    endStroke();
    // 글자를 끌어서 옮긴 뒤 손을 떼면 그 자리에 바로 고정 (완료 버튼 없이)
    if(wasDragging && stamp && stamp.moved && stamp.mode !== 'letter') placeStamp();
  });
  canvas.addEventListener('pointercancel', ()=>{
    knitTap = null;
    if(selDrag){ selDrag = null; selRect = null; drawGrid(); } stampDrag = null; endStroke(); });

  document.getElementById('applyBtn').addEventListener('click', ()=>{
    pushUndo();
    const r = Math.min(200, Math.max(1, parseInt(rowsInput.value,10) || 20));
    const c = Math.min(200, Math.max(1, parseInt(colsInput.value,10) || 20));
    rowsInput.value = r; colsInput.value = c;
    initGrid(r, c);
    saveState();
  });
  document.getElementById('clearGridBtn').addEventListener('click', ()=>{
    if(!gridData.some(v => v !== null)) return;
    pushUndo();
    gridData = new Array(rows*cols).fill(null);
    drawGrid();
    saveState();
  });
  document.getElementById('addMarginBtn').addEventListener('click', ()=>{
    const dir = document.getElementById('marginDirSelect').value;
    if(dir === 'top') padGrid(1,0,0,0);
    else if(dir === 'bottom') padGrid(0,1,0,0);
    else if(dir === 'left') padGrid(0,0,1,0);
    else if(dir === 'right') padGrid(0,0,0,1);
    else padGrid(1,1,1,1);
  });
  document.getElementById('trimMarginBtn').addEventListener('click', ()=>{
    const dir = document.getElementById('marginDirSelect').value;
    if(dir === 'top') trimGrid(1,0,0,0);
    else if(dir === 'bottom') trimGrid(0,1,0,0);
    else if(dir === 'left') trimGrid(0,0,1,0);
    else if(dir === 'right') trimGrid(0,0,0,1);
    else trimGrid(1,1,1,1);
  });
  document.getElementById('undoBtn').addEventListener('click', undo);
  document.getElementById('redoBtn').addEventListener('click', redo);
  document.addEventListener('keydown', e=>{
    if(!(e.ctrlKey || e.metaKey)) return;
    const t = e.target;
    if(t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT')) return;
    // 한글 자판 상태에서도 동작하도록 e.key 대신 물리 키(e.code)로 판별
    const isZ = e.code === 'KeyZ' || e.key.toLowerCase() === 'z' || e.key === 'ㅋ';
    const isY = e.code === 'KeyY' || e.key.toLowerCase() === 'y' || e.key === 'ㅛ';
    if(isZ && !e.shiftKey){ e.preventDefault(); undo(); }
    else if((isZ && e.shiftKey) || isY){ e.preventDefault(); redo(); }
  });
  window.addEventListener('resize', ()=>{ sizeCanvas(); drawGrid(); });

  const zoomLabel = document.getElementById('zoomLabel');
  const ZOOM_STEP = 0.25, ZOOM_MIN = 0.5, ZOOM_MAX = 5;
  function applyZoom(){
    zoomLabel.textContent = Math.round(zoomLevel * 100) + '%';
    document.getElementById('knitZoomVal').textContent = Math.round(zoomLevel * 100) + '%';
    sizeCanvas();
    drawGrid();
    saveState();
  }
  document.getElementById('zoomInBtn').addEventListener('click', ()=>{
    zoomLevel = Math.min(ZOOM_MAX, +(zoomLevel + ZOOM_STEP).toFixed(2));
    applyZoom();
  });
  document.getElementById('zoomOutBtn').addEventListener('click', ()=>{
    zoomLevel = Math.max(ZOOM_MIN, +(zoomLevel - ZOOM_STEP).toFixed(2));
    applyZoom();
  });
  document.getElementById('zoomResetBtn').addEventListener('click', ()=>{
    zoomLevel = 1;
    applyZoom();
  });

  /* ===== 게이지 · 실제 비율로 보기 =====
     뜨개는 한 코의 너비와 한 단의 높이가 달라서(보통 코가 더 넓음) 정사각형 격자에 그린 그림이 실물에서는 퍼져 보임.
     10cm 안의 코 수·단 수를 받아 칸 모양을 실물처럼 바꿔 보여 줌. 칠한 칸(도안 자체)은 바뀌지 않음. */
  const gaugeStInput = document.getElementById('gaugeStInput');
  const gaugeRowInput = document.getElementById('gaugeRowInput');
  const gaugePreset = document.getElementById('gaugePreset');
  const ratioToggle = document.getElementById('ratioToggle');
  const roundGauge = v => Math.round(v * 2) / 2; // 0.5 단위
  const fmt1 = v => String(Math.round(v * 10) / 10);
  function validGauge(v){ return typeof v === 'number' && isFinite(v) && v >= GAUGE_MIN && v <= GAUGE_MAX; }
  // 칸 모양·완성 크기 안내 (격자 크기나 언어가 바뀔 때도 다시 씀)
  function renderGaugeText(){
    const r = gaugeSt / gaugeRow;
    let shape;
    if(Math.abs(r - 1) < 0.02) shape = t('칸이 정사각형이에요');
    else if(r < 1) shape = t('한 칸이 세로보다 가로가 {n}배 넓어요', {n: fmt1(1 / r)});
    else shape = t('한 칸이 가로보다 세로가 {n}배 길어요', {n: fmt1(r)});
    document.getElementById('gaugeShape').textContent = shape;
    document.getElementById('gaugeSize').textContent =
      t('이 게이지로 뜨면 완성 크기 약 {w} × {h}cm', {w: fmt1(cols * 10 / gaugeSt), h: fmt1(rows * 10 / gaugeRow)});
  }
  function renderGaugeUI(){
    if(document.activeElement !== gaugeStInput) gaugeStInput.value = gaugeSt;
    if(document.activeElement !== gaugeRowInput) gaugeRowInput.value = gaugeRow;
    const key = gaugeSt + 'x' + gaugeRow;
    gaugePreset.value = [...gaugePreset.options].some(o => o.value === key) ? key : 'custom';
    ratioToggle.checked = realRatio;
    renderGaugeText();
  }
  function refreshRatioView(){
    renderGaugeUI();
    sizeCanvas();
    drawGrid();
    saveState();
  }
  function setGauge(st, row){
    if(!validGauge(st) || !validGauge(row)) return;
    gaugeSt = roundGauge(st); gaugeRow = roundGauge(row);
    refreshRatioView();
  }
  function setRealRatio(on){
    realRatio = !!on;
    refreshRatioView();
    if(realRatio && gaugeSt === gaugeRow) toast(t('게이지에 10cm 안의 코 수·단 수를 넣으면 칸 모양이 실물처럼 바뀌어요'));
  }
  gaugePreset.addEventListener('change', ()=>{
    const v = gaugePreset.value;
    if(v === 'custom'){ gaugeStInput.focus(); return; }
    const [st, row] = v.split('x').map(Number);
    gaugeSt = st; gaugeRow = row;
    realRatio = st !== row; // 예시를 고르면 바로 그 모양으로 보여 줌 (정사각형은 끔)
    refreshRatioView();
  });
  [gaugeStInput, gaugeRowInput].forEach(inp => {
    inp.addEventListener('input', ()=>{
      const st = parseFloat(gaugeStInput.value), row = parseFloat(gaugeRowInput.value);
      if(validGauge(st) && validGauge(row)) setGauge(st, row);
    });
    // 칸을 벗어나면 잘못 넣은 값은 마지막으로 쓴 값으로 되돌림
    inp.addEventListener('blur', ()=>{ gaugeStInput.value = gaugeSt; gaugeRowInput.value = gaugeRow; });
  });
  ratioToggle.addEventListener('change', ()=>setRealRatio(ratioToggle.checked));

  const rowLabel = document.getElementById('rowLabel');
  function applyRowLabel(){
    currentRow = Math.max(1, Math.min(rows, currentRow));
    rowLabel.textContent = t('{n}단', {n: currentRow});
    drawGrid();
    saveState();
  }
  document.getElementById('rowPlusBtn').addEventListener('click', ()=>{
    currentRow++;
    applyRowLabel();
  });
  document.getElementById('rowMinusBtn').addEventListener('click', ()=>{
    currentRow--;
    applyRowLabel();
  });

  /* ===== 작업 시작하기: 다른 도구를 숨기고 도안·격자·작업 단만 ===== */
  const appEl = document.querySelector('.app');
  function setKnitMode(on, quiet){
    if(on && stamp){ toast(t('글자 옮기기를 끝낸 뒤에 작업을 시작해주세요')); return; }
    knitMode = on;
    selRect = null;
    appEl.classList.toggle('knit-mode', on);
    document.body.classList.toggle('knitting', on);
    try{ localStorage.setItem('crochet-knit-mode', on ? '1' : '0'); }catch(e){}
    sizeCanvas();
    drawGrid();
    if(on && !quiet) toast(t('격자의 단을 누르거나 ＋ − 로 한 단씩 옮겨요'));
  }
  // 읽는 방향: alt-r = 홀수 단은 오른쪽부터·짝수 단은 왼쪽부터, alt-l = 그 반대, l/r = 항상 한쪽
  const knitDirSelect = document.getElementById('knitDirSelect');
  try{
    const v = localStorage.getItem('crochet-knit-dir');
    if(v && [...knitDirSelect.options].some(o => o.value === v)) knitDirSelect.value = v;
  }catch(e){}
  knitDirSelect.addEventListener('change', ()=>{
    try{ localStorage.setItem('crochet-knit-dir', knitDirSelect.value); }catch(e){}
    drawGrid();
  });
  function rowFromRight(n){
    const m = knitDirSelect.value;
    if(m === 'r') return true;
    if(m === 'l') return false;
    const odd = n % 2 === 1;
    return m === 'alt-r' ? odd : !odd;
  }
  function updateKnitBar(){
    const fromRight = rowFromRight(currentRow);
    document.getElementById('knitRowNum').textContent = t('{n}단', {n: currentRow});
    document.getElementById('knitRowOf').textContent = t('총 {n}단', {n: rows});
    document.getElementById('knitDir').textContent = fromRight ? t('← 오른쪽부터') : t('왼쪽부터 →');
    document.getElementById('knitFoldLabel').textContent = t('접기');
    document.getElementById('knitMiniRow').textContent = t('{n}단', {n: currentRow});
    const box = document.getElementById('knitRuns');
    box.textContent = '';
    let runs = currentRowRuns();
    if(fromRight) runs = runs.slice().reverse();
    runs.forEach(r => {
      const chip = document.createElement('span');
      chip.className = 'knit-chip';
      const sw = document.createElement('i');
      sw.style.background = r.color || bgColor;
      chip.appendChild(sw);
      chip.appendChild(document.createTextNode(String(r.len)));
      box.appendChild(chip);
    });
  }
  // 위쪽 막대 전체 접기/펼치기 (뜨는 동안 도안을 넓게). 접으면 도안 오른쪽 위에 작은 단 번호 버튼만 남음. 상태는 기억해 둠
  const knitBar = document.getElementById('knitBar');
  function setKnitFolded(folded){
    knitBar.classList.toggle('folded', folded);
    appEl.classList.toggle('knit-folded', folded);
    document.getElementById('knitFoldBtn').setAttribute('aria-expanded', folded ? 'false' : 'true');
    try{ localStorage.setItem('crochet-knit-folded', folded ? '1' : '0'); }catch(e){}
    if(knitMode){ sizeCanvas(); drawGrid(); }
  }
  document.getElementById('knitFoldBtn').addEventListener('click', ()=>setKnitFolded(true));
  document.getElementById('knitUnfoldBtn').addEventListener('click', ()=>setKnitFolded(false));
  try{ setKnitFolded(localStorage.getItem('crochet-knit-folded') === '1'); }catch(e){ setKnitFolded(false); }
  document.getElementById('knitStartBtn').addEventListener('click', ()=>setKnitMode(true));
  document.getElementById('knitExitBtn').addEventListener('click', ()=>setKnitMode(false));
  document.getElementById('knitPlusBtn').addEventListener('click', ()=>{ currentRow++; applyRowLabel(); });
  document.getElementById('knitMinusBtn').addEventListener('click', ()=>{ currentRow--; applyRowLabel(); });
  document.getElementById('knitZoomInBtn').addEventListener('click', ()=>document.getElementById('zoomInBtn').click());
  document.getElementById('knitZoomOutBtn').addEventListener('click', ()=>document.getElementById('zoomOutBtn').click());
  document.getElementById('knitZoomFitBtn').addEventListener('click', ()=>document.getElementById('zoomResetBtn').click());

  // 작업 화면 크기 조절: 두 손가락으로 벌리기/오므리기, 컴퓨터는 Ctrl + 마우스 휠(노트북 터치패드 벌리기도 이걸로 들어옴)
  // 확대한 지점이 손가락·마우스 아래에 그대로 머물도록 스크롤 위치도 같이 맞춤
  const knitWrap = document.querySelector('.stage .canvas-wrap');
  function zoomAround(newZoom, clientX, clientY){
    newZoom = Math.max(ZOOM_MIN, Math.min(ZOOM_MAX, Math.round(newZoom * 100) / 100));
    if(newZoom === zoomLevel) return;
    const r = canvas.getBoundingClientRect();
    const fx = (clientX - r.left - LABEL_SIZE) / (cellW * cols);
    const fy = (clientY - r.top - LABEL_SIZE) / (cellH * rows);
    zoomLevel = newZoom;
    applyZoom();
    const r2 = canvas.getBoundingClientRect();
    knitWrap.scrollLeft += (r2.left + LABEL_SIZE + fx * cellW * cols) - clientX;
    knitWrap.scrollTop += (r2.top + LABEL_SIZE + fy * cellH * rows) - clientY;
  }
  knitWrap.addEventListener('wheel', e=>{
    if(!knitMode || !(e.ctrlKey || e.metaKey)) return;
    e.preventDefault();
    zoomAround(zoomLevel * Math.exp(-e.deltaY * 0.0025), e.clientX, e.clientY);
  }, { passive:false });
  let pinch = null;
  const touchDist = ts => Math.hypot(ts[0].clientX - ts[1].clientX, ts[0].clientY - ts[1].clientY);
  knitWrap.addEventListener('touchstart', e=>{
    if(!knitMode || e.touches.length !== 2) return;
    pinch = { d: touchDist(e.touches), z: zoomLevel };
    knitTap = null; // 두 손가락이면 단 고르기 아님
  }, { passive:true });
  knitWrap.addEventListener('touchmove', e=>{
    if(!pinch || e.touches.length !== 2) return;
    if(e.cancelable) e.preventDefault();
    const cx = (e.touches[0].clientX + e.touches[1].clientX) / 2, cy = (e.touches[0].clientY + e.touches[1].clientY) / 2;
    zoomAround(pinch.z * touchDist(e.touches) / pinch.d, cx, cy);
  }, { passive:false });
  knitWrap.addEventListener('touchend', e=>{ if(e.touches.length < 2) pinch = null; });
  document.addEventListener('keydown', e=>{
    if(!knitMode || e.ctrlKey || e.metaKey) return;
    if(e.code === 'ArrowUp'){ e.preventDefault(); currentRow++; applyRowLabel(); }
    else if(e.code === 'ArrowDown'){ e.preventDefault(); currentRow--; applyRowLabel(); }
    else if(e.code === 'Escape'){ e.preventDefault(); setKnitMode(false); }
  });

  /* ===== 작업창(리본) 접기·펼치기 =====
     접으면 작업창을 통째로 숨기고(높이 0) 펼치기 손잡이 하나만 남김.
     손잡이 위치: 넓은 화면은 오른쪽 패널 탭 줄 오른쪽 끝, 좁은 화면은 캔버스 영역 오른쪽 위.
     상태는 이 브라우저에 기억. 처음 오면 휴대폰(폭 599px 이하)은 접힘, 그보다 넓으면 펼침. */
  const RIBBON_KEY = 'crochet-ribbon-folded';
  const ribbonEl = document.getElementById('ribbon');
  const ribbonFoldBtn = document.getElementById('ribbonFoldBtn');
  const ribbonHandles = [...document.querySelectorAll('.ribbon-handle')];
  let ribbonFolded = false;
  // 좁은 화면(위아래로 쌓는 구성)은 캔버스 높이가 고정이라, 접어서 줄어든 높이만큼 캔버스를 직접 키움
  function updateRibbonGain(){
    let gain = 0;
    if(ribbonFolded && window.matchMedia('(max-width: 899px)').matches){
      appEl.classList.remove('ribbon-folded');
      const openH = ribbonEl.offsetHeight; // 잠깐 펼쳐서 높이만 잼 (그려지기 전에 되돌리므로 화면에는 안 보임)
      appEl.classList.add('ribbon-folded');
      // 단, 캔버스가 화면 아래로 넘치지 않을 만큼만 (작업창이 여러 줄인 휴대폰에서 생길 수 있음)
      const topH = document.querySelector('.appbar').offsetHeight;
      const baseH = window.innerHeight * 0.62;
      gain = Math.max(0, Math.min(openH, window.innerHeight - topH - baseH));
    }
    appEl.style.setProperty('--ribbon-gain', gain + 'px');
  }
  function renderRibbonFoldBtn(){
    const fold = t('작업창 접기'), open = t('작업창 펼치기');
    ribbonFoldBtn.setAttribute('aria-label', fold);
    ribbonFoldBtn.title = fold + ' (Ctrl+\\)';
    ribbonFoldBtn.setAttribute('aria-expanded', ribbonFolded ? 'false' : 'true');
    ribbonHandles.forEach(h => {
      h.setAttribute('aria-label', open);
      h.title = open + ' (Ctrl+\\)';
      h.setAttribute('aria-expanded', ribbonFolded ? 'false' : 'true');
    });
  }
  function visibleHandle(){ return ribbonHandles.find(h => h.offsetParent !== null) || null; }
  function setRibbonFolded(folded, opts){
    opts = opts || {};
    if(opts.init){
      ribbonFolded = folded;
      appEl.classList.toggle('ribbon-folded', folded);
      renderRibbonFoldBtn();
      updateRibbonGain();
      return;
    }
    if(folded === ribbonFolded) return;
    // 접기 버튼이나 손잡이를 누른 채 사라지면 키보드 위치를 잃으므로, 반대쪽 버튼으로 옮겨 줌
    const ae = document.activeElement;
    const hadFocus = ae === ribbonFoldBtn || ribbonHandles.includes(ae);
    // 지금 화면 가운데에 보이는 격자 지점을 기억했다가, 캔버스 크기가 바뀐 뒤에도 같은 지점이 가운데 오게 함
    const wrapR = knitWrap.getBoundingClientRect(), cvR = canvas.getBoundingClientRect();
    const fx = (wrapR.left + knitWrap.clientWidth/2 - cvR.left - LABEL_SIZE) / (cellW * cols);
    const fy = (wrapR.top + knitWrap.clientHeight/2 - cvR.top - LABEL_SIZE) / (cellH * rows);
    ribbonFolded = folded;
    appEl.classList.toggle('ribbon-folded', folded);
    renderRibbonFoldBtn();
    updateRibbonGain();
    try{ localStorage.setItem(RIBBON_KEY, folded ? '1' : '0'); }catch(e){}
    sizeCanvas();
    drawGrid();
    const wrapR2 = knitWrap.getBoundingClientRect(), cvR2 = canvas.getBoundingClientRect();
    knitWrap.scrollLeft += (cvR2.left + LABEL_SIZE + fx * cellW * cols) - (wrapR2.left + knitWrap.clientWidth/2);
    knitWrap.scrollTop += (cvR2.top + LABEL_SIZE + fy * cellH * rows) - (wrapR2.top + knitWrap.clientHeight/2);
    if(hadFocus){
      const target = folded ? visibleHandle() : ribbonFoldBtn;
      if(target) target.focus({ preventScroll: true });
    }
    // 펼칠 때 짧게 나타나는 움직임 (동작 줄이기를 켠 사람은 CSS에서 꺼짐)
    if(!folded){
      ribbonEl.classList.remove('anim');
      void ribbonEl.offsetWidth;
      ribbonEl.classList.add('anim');
      clearTimeout(setRibbonFolded.animTimer);
      setRibbonFolded.animTimer = setTimeout(()=>ribbonEl.classList.remove('anim'), 250);
    }
  }
  ribbonFoldBtn.addEventListener('click', ()=>{ setRibbonFolded(true); showRibbonHint(); });
  ribbonHandles.forEach(h => h.addEventListener('click', ()=>{ hideRibbonHint(); setRibbonFolded(false); }));

  // 처음 한 번만: 손잡이 옆에 "여기를 누르면 도구가 펼쳐져요" 말풍선 (이 브라우저에서 한 번 보여 주면 다시 안 띄움)
  const RIBBON_HINT_KEY = 'crochet-ribbon-hint-shown';
  const ribbonHint = document.getElementById('ribbonHint');
  let ribbonHintTimer = null;
  function hideRibbonHint(){
    clearTimeout(ribbonHintTimer);
    ribbonHint.classList.remove('show');
  }
  function showRibbonHint(){
    if(!ribbonFolded || knitMode) return;
    try{ if(localStorage.getItem(RIBBON_HINT_KEY) === '1') return; }catch(e){ return; }
    const h = visibleHandle();
    if(!h) return;
    try{ localStorage.setItem(RIBBON_HINT_KEY, '1'); }catch(e){}
    ribbonHint.textContent = t('여기를 누르면 도구가 펼쳐져요');
    placeRibbonHint();
    ribbonHint.classList.add('show');
    clearTimeout(ribbonHintTimer);
    ribbonHintTimer = setTimeout(hideRibbonHint, 5000);
  }
  let ribbonHintW = window.innerWidth;
  function placeRibbonHint(){
    ribbonHintW = window.innerWidth;
    const h = visibleHandle();
    if(!h){ hideRibbonHint(); return; }
    const r = h.getBoundingClientRect();
    ribbonHint.style.top = Math.round(r.top + r.height/2) + 'px';
    ribbonHint.style.right = Math.round(window.innerWidth - r.left + 10) + 'px';
  }
  // 아무 데나 누르거나 스크롤하면 닫힘. 화면 폭이 바뀌면(회전 등) 닫고,
  // 높이만 바뀌면(휴대폰 주소창이 접히고 펴질 때) 자리만 다시 맞춤
  document.addEventListener('pointerdown', hideRibbonHint, true);
  window.addEventListener('resize', ()=>{
    if(!ribbonHint.classList.contains('show')) return;
    if(window.innerWidth !== ribbonHintW) hideRibbonHint(); else placeRibbonHint();
  });
  window.addEventListener('scroll', hideRibbonHint, true);
  // 단축키: Ctrl+\ (맥은 Cmd+\)
  document.addEventListener('keydown', e=>{
    if(!(e.ctrlKey || e.metaKey) || e.altKey || e.code !== 'Backslash' || knitMode) return;
    const tg = e.target;
    if(tg && (tg.tagName === 'INPUT' || tg.tagName === 'TEXTAREA' || tg.tagName === 'SELECT')) return;
    e.preventDefault();
    setRibbonFolded(!ribbonFolded);
  });
  window.addEventListener('resize', ()=>{ if(ribbonFolded) updateRibbonGain(); });
  {
    let saved = null;
    try{ saved = localStorage.getItem(RIBBON_KEY); }catch(e){}
    const folded = saved === null ? window.matchMedia('(max-width: 599px)').matches : saved === '1';
    setRibbonFolded(folded, { init: true });
  }
  const flipToggleBtn = document.getElementById('flipToggleBtn');
  flipToggleBtn.addEventListener('click', ()=>{
    flipped = !flipped;
    flipToggleBtn.classList.toggle('active', flipped);
    drawGrid();
    saveState();
  });

  /* ===== 도안 회전 (세로 방향으로 뜨기 시작할 때) ===== */
  // deg=90: 시계 방향 90도, deg=270: 시계 방향 270도(= 반시계 90도)
  function rotateGrid(deg){
    if(stamp){ toast(t('글자 옮기기를 끝낸 뒤에 회전해주세요')); return; }
    pushUndo();
    const nr = cols, nc = rows;
    const nd = new Array(nr*nc).fill(null);
    for(let i=0; i<nr; i++){
      for(let j=0; j<nc; j++){
        nd[i*nc + j] = deg === 90
          ? gridData[(rows-1-j)*cols + i]
          : gridData[j*cols + (cols-1-i)];
      }
    }
    rows = nr; cols = nc; gridData = nd;
    rowsInput.value = rows; colsInput.value = cols;
    currentRow = 1;
    sizeCanvas();
    drawGrid();
    saveState();
    toast(t('{deg}° 회전했어요 ({c}코 × {r}단)', {deg, c: cols, r: rows}));
  }
  document.getElementById('rot90Btn').addEventListener('click', ()=>rotateGrid(90));
  document.getElementById('rot270Btn').addEventListener('click', ()=>rotateGrid(270));

  /* ===== 문구 → 도트 도안 변환 ===== */
  const textInput = document.getElementById('textInput');
  const fontSelect = document.getElementById('fontSelect');
  const convertBtn = document.getElementById('convertBtn');

  async function textToPattern(opts){
    const preview = !!(opts && opts.preview);
    const gen = ++previewGen; // 더 최근 요청이 들어오면 이 결과는 버림
    const busyBtn = convertBtn;
    const idleText = busyBtn.textContent;
    const rawText = textInput.value.replace(/\r\n/g, '\n');
    const text = rawText.trim();
    if(!text){
      if(preview && stamp && stamp.isText) cancelStamp();
      return;
    }
    const lines = rawText.split('\n');
    const [family, sizeStr] = fontSelect.value.split('|');
    // 'v' = 굵은 글씨(일반 벡터 폰트): 원하는 글자 높이(칸)에 맞춰 크기를 자유롭게 정함
    const isVector = sizeStr === 'v';
    if(isVector && textHeight < minTextHeight()) textHeight = minTextHeight();
    let size = isVector ? textHeight : parseInt(sizeStr, 10);
    const RS = 4; // 렌더링 배율: 안티앨리어싱으로 얇아지는 문제를 막기 위해 크게 그린 뒤 평균으로 다운샘플링
    let fontStr = `${drawWeight(family)}${size*RS}px "${family}", sans-serif`;
    // 도트 폰트는 원래 크기(size)로 그려야 한 도트가 정확히 한 칸이 됨.
    // 다른 크기로 그리면 도트가 1.25배처럼 어중간하게 늘어나 획이 뭉개지고 붙어버림.
    const lineGap = Math.max(-40, Math.min(40, parseInt(document.getElementById('lineGapInput').value, 10) || 0));
    let lineHeight = size + lineGap; // 줄 간격 (nominal 단위, 음수면 줄이 겹침)
    const spaceGap = Math.max(0, parseInt(document.getElementById('spaceGapInput').value, 10) || 0);
    // 도스 계열 폰트는 16칸 안을 꽉 채워 그린 글자가 있어서(예: 도스필기 '하'는 오른쪽 끝까지, '이'는 왼쪽 끝부터)
    // 글자끼리 붙어 나올 수 있음 → 글자 사이에 빈 칸을 따로 넣음
    const letterGap = Math.max(0, Math.min(20, parseInt(document.getElementById('letterGapInput').value, 10) || 0));

    if(!preview){
      busyBtn.textContent = t('만드는 중...');
      convertBtn.disabled = true;
    }
    try{
      try{
        await document.fonts.load(`${drawWeight(family)}${isVector ? 100 : size*RS}px "${family}"`, text);
      }catch(loadErr){
        console.warn('폰트 로드 실패, 대체 폰트로 계속 진행합니다', loadErr);
      }
      if(gen !== previewGen) return;
      if(isVector){
        // "글자 높이" = 한글은 '가', 영문은 'H'의 실제 높이. 그 높이가 textHeight칸이 되도록 폰트 크기를 역산
        const mctx = document.createElement('canvas').getContext('2d');
        mctx.font = `${drawWeight(family)}100px "${family}", sans-serif`;
        const ref = /[가-힣]/.test(text) ? '가' : 'H';
        const mm = mctx.measureText(ref);
        const inkH = (mm.actualBoundingBoxAscent || 70) + (ref === '가' ? (mm.actualBoundingBoxDescent || 0) : 0);
        size = textHeight * 100 / Math.max(10, inkH);
        fontStr = `${drawWeight(family)}${size*RS}px "${family}", sans-serif`;
        lineHeight = Math.round(size) + lineGap;
      }
      lineHeight = Math.max(1, lineHeight);

      // 실제보다 RS배 크게 그린 뒤, 블록 평균으로 다운샘플링해서 얇아지는 것을 방지
      const off = document.createElement('canvas');
      const octx = off.getContext('2d');
      octx.font = fontStr;
      const pad = size * RS;
      const spaceGapDevice = spaceGap * RS;
      const lineHeightDevice = lineHeight * RS;
      const letterGapDevice = letterGap * RS;
      // 한 단어를 글자 단위로 나눠 폭을 계산 (글자 사이에 letterGap 추가)
      const wordWidth = word => {
        const chars = Array.from(word);
        let w = 0;
        chars.forEach((ch, i) => { w += octx.measureText(ch).width; if(i < chars.length-1) w += letterGapDevice; });
        return w;
      };

      // 줄마다 단어로 쪼개고, 각 줄의 전체 너비를 커스텀 스페이스 간격으로 계산
      const linesWords = lines.map(line => line.split(' '));
      let maxLineWidth = size * RS;
      const lineWidths = linesWords.map(words => {
        let w = 0;
        words.forEach((word, idx) => {
          w += wordWidth(word);
          if(idx < words.length - 1) w += spaceGapDevice;
        });
        maxLineWidth = Math.max(maxLineWidth, Math.ceil(w));
        return w;
      });

      // 글자 흐름: 한 줄 안에서 글자마다 위아래로 몇 칸 옮길지 (양수 = 위로)
      const lineCharCounts = lines.map(l => Array.from(l.replace(/ /g, '')).length);
      const maxChars = Math.max(1, ...lineCharCounts);
      const flowOffset = (i, n) => {
        if(textFlow === 'wave') return Math.round(flowAmt * Math.sin(2 * Math.PI * i / Math.max(4, n)));
        if(textFlow === 'bounce') return i % 2 === 1 ? flowAmt : 0;
        if(textFlow === 'up') return i * flowAmt;
        if(textFlow === 'down') return -i * flowAmt;
        return 0;
      };
      const maxFlow = textFlow === 'up' || textFlow === 'down' ? flowAmt * (maxChars - 1) : (textFlow === 'none' ? 0 : flowAmt);
      const flowPad = maxFlow * RS;
      off.width = maxLineWidth + pad * 2;
      off.height = pad * 2 + flowPad * 2 + lineHeightDevice * lines.length + size * RS;
      // 캔버스 크기를 바꾸면 폰트 설정이 초기화되므로 다시 지정
      octx.font = fontStr;
      // 'top' 기준선은 폰트마다 위치가 소수점으로 어긋날 수 있어서,
      // 글자 기준선(alphabetic)을 RS의 배수 위치에 두어 도트 경계가 칸 경계와 딱 맞게 함
      octx.textBaseline = 'alphabetic';
      octx.fillStyle = '#000000';
      octx.clearRect(0, 0, off.width, off.height);
      const charRecs = []; // 글자마다 그린 위치 (나중에 글자별 조각을 만들 때 씀)
      linesWords.forEach((words, lineIdx) => {
        // 정렬: 줄 너비 차이만큼 밀기. 도트 폰트는 RS 배수로 맞춰야 도트가 칸에 딱 맞음
        const k = textAlign === 'center' ? 0.5 : textAlign === 'right' ? 1 : 0;
        const shift = Math.round((maxLineWidth - lineWidths[lineIdx]) * k / RS) * RS;
        let x = pad + shift;
        const y = pad + flowPad + lineIdx * lineHeightDevice + size * RS;
        const nChars = lineCharCounts[lineIdx];
        let ci = 0; // 줄 안에서 몇 번째 글자인지 (띄어쓰기 제외)
        words.forEach((word, idx) => {
          const chars = Array.from(word);
          chars.forEach((ch, i) => {
            octx.fillText(ch, x, y - flowOffset(ci, nChars) * RS);
            charRecs.push({ ch, x, y: y - flowOffset(ci, nChars) * RS });
            ci++;
            x += octx.measureText(ch).width;
            if(i < chars.length-1) x += letterGapDevice;
          });
          if(idx < words.length - 1) x += spaceGapDevice;
        });
      });

      // 글자마다 따로 그려서 '조각'으로 만듦 → 옮길 때 글자 하나씩 움직일 수 있음
      // 조각 캔버스의 원점을 RS 배수로 맞춰서, 전체를 한 번에 그렸을 때와 칸 경계가 똑같이 맞도록 함
      const THRESHOLD = 128; // 칸의 절반 이상 채워진 경우만 칠함
      const pieceCells = [];
      let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
      const pc = document.createElement('canvas');
      const pctx = pc.getContext('2d', { willReadFrequently: true });
      charRecs.forEach(rec => {
        const mt = octx.measureText(rec.ch);
        const left = rec.x - (mt.actualBoundingBoxLeft || 0) - RS*2;
        const right = rec.x + (mt.actualBoundingBoxRight || mt.width) + RS*2;
        const top = rec.y - (mt.actualBoundingBoxAscent || size*RS) - RS*2;
        const bottom = rec.y + (mt.actualBoundingBoxDescent || 0) + RS*2;
        const rx0 = Math.floor(left / RS) * RS, ry0 = Math.floor(top / RS) * RS;
        const W = Math.max(RS, Math.ceil(right / RS) * RS - rx0), H = Math.max(RS, Math.ceil(bottom / RS) * RS - ry0);
        pc.width = W; pc.height = H;
        pctx.font = fontStr; pctx.textBaseline = 'alphabetic'; pctx.fillStyle = '#000000';
        pctx.clearRect(0, 0, W, H);
        pctx.fillText(rec.ch, rec.x - rx0, rec.y - ry0);
        const d = pctx.getImageData(0, 0, W, H).data;
        const nw = W / RS, nh = H / RS, cells = [];
        for(let ny=0; ny<nh; ny++){
          for(let nx=0; nx<nw; nx++){
            let sum = 0;
            for(let dy=0; dy<RS; dy++){
              const row = (ny*RS + dy) * W;
              for(let dx=0; dx<RS; dx++) sum += d[(row + nx*RS + dx)*4 + 3];
            }
            if(sum / (RS*RS) > THRESHOLD){
              const gx = nx + rx0/RS, gy = ny + ry0/RS;
              cells.push(gx, gy);
              if(gx < minX) minX = gx; if(gx > maxX) maxX = gx;
              if(gy < minY) minY = gy; if(gy > maxY) maxY = gy;
            }
          }
        }
        if(cells.length) pieceCells.push(cells);
      });
      if(!pieceCells.length){
        warnUser(t('글자를 그리지 못했어요. 다른 문구나 폰트를 시도해보세요.'), preview);
        return;
      }
      // 조각 번호 지도 → 배율 적용(도트 폰트) → 조각마다 비트맵 + 그림자
      const bw = maxX - minX + 1, bh = maxY - minY + 1;
      const label = new Int16Array(bw * bh);
      pieceCells.forEach((cells, pi) => {
        for(let k=0; k<cells.length; k+=2) label[(cells[k+1]-minY)*bw + (cells[k]-minX)] = pi + 1;
      });
      const sc = isVector ? 1 : textScale;
      const SW = Math.round(bw*sc), SH = Math.round(bh*sc);
      const acc = pieceCells.map(() => ({ x0:Infinity, y0:Infinity, x1:-Infinity, y1:-Infinity, pts:[] }));
      for(let y=0; y<SH; y++){
        for(let x=0; x<SW; x++){
          const l = label[Math.min(bh-1, Math.floor(y/sc))*bw + Math.min(bw-1, Math.floor(x/sc))];
          if(!l) continue;
          const A = acc[l-1];
          A.pts.push(x, y);
          if(x < A.x0) A.x0 = x; if(x > A.x1) A.x1 = x;
          if(y < A.y0) A.y0 = y; if(y > A.y1) A.y1 = y;
        }
      }
      const pieces = [];
      acc.forEach(A => {
        if(!A.pts.length) return;
        const w = A.x1 - A.x0 + 1, h = A.y1 - A.y0 + 1, data = new Uint8Array(w*h);
        for(let k=0; k<A.pts.length; k+=2) data[(A.pts[k+1]-A.y0)*w + (A.pts[k]-A.x0)] = 1;
        pieces.push(shadowPiece(outlinePiece({ data, w, h, ox: A.x0, oy: A.y0 })));
      });
      if(gen !== previewGen) return;
      if(preview) refreshTextStamp({ pieces });
      else startStamp({ pieces }, { text: true });
    } catch(err){
      console.error(err);
      warnUser(t('변환 중 오류가 발생했어요: ') + err.message, preview);
    } finally {
      if(!preview){
        busyBtn.textContent = idleText;
        convertBtn.disabled = false;
        renderFitUI();
      }
    }
  }
  /* ===== 글씨 그림자 ===== */
  // 그림자 칸 수는 최종 도안 기준(글자 크기 배율 적용 후)
  const SHADOW_DIRS = { none:[0,0], dr:[1,1], d:[0,1], dl:[-1,1], r:[1,0], l:[-1,0] };
  let shadowDir = 'none', shadowDist = 1, shadowColor = '#222222';
  // 그림자 종류: 'one' = 한 색, 'glitch' = 지직(두 색). 지직은 화살표 방향으로 색 1, 반대쪽으로 색 2를 어긋나게 깖
  const OLD_GLITCH_DEFAULT = ['#D32F2F', '#1976D2']; // 처음 기본값(빨강·파랑). 이 값 그대로 저장돼 있으면 새 기본값으로 바꿔 줌
  const GLITCH_DEFAULT = ['#8FD3FF', '#FF8A1F'];     // 연하늘 · 주황
  let shadowMode = 'one', glitchColors = GLITCH_DEFAULT.slice();
  const SHADOW = 2;    // 비트맵 값: 0 빈칸, 1 글자, 2 그림자(지직일 때 색 1)
  const SHADOW2 = 255; // 지직일 때 색 2 (3 이상은 옮긴 칸의 원래 색 번호라 겹치지 않게 맨 끝 값을 씀)
  const OUTLINE = 254; // 글자 둘레 테두리
  const isShadowVal = v => v === SHADOW || v === SHADOW2;
  // 글자 둘레 테두리: 글자 칸에서 상하좌우와 대각선으로 outlineSize칸 안에 있는 빈칸을 테두리 색으로 칠함
  let outlineSize = 0, outlineColor = '#FBC02D';
  function outlinePiece(p){
    const k = outlineSize;
    if(!k) return p;
    const W = p.w + k*2, H = p.h + k*2, out = new Uint8Array(W*H);
    for(let y=0; y<p.h; y++) for(let x=0; x<p.w; x++){
      if(!p.data[y*p.w+x]) continue;
      for(let dy=-k; dy<=k; dy++) for(let dx=-k; dx<=k; dx++) out[(y+k+dy)*W + (x+k+dx)] = OUTLINE;
    }
    for(let y=0; y<p.h; y++) for(let x=0; x<p.w; x++){ const v = p.data[y*p.w+x]; if(v) out[(y+k)*W + (x+k)] = v; }
    return { data: out, w: W, h: H, ox: p.ox - k, oy: p.oy - k };
  }

  // 조각 하나에 그림자를 붙이고, 그림자 때문에 늘어난 만큼 조각 위치를 보정
  function shadowPiece(p){
    const [vx, vy] = SHADOW_DIRS[shadowDir] || [0,0];
    const r = addShadow(p);
    const dx = vx*shadowDist, dy = vy*shadowDist;
    if(shadowMode === 'glitch' && (dx || dy)) return { data: r.data, w: r.w, h: r.h, ox: p.ox - Math.abs(dx), oy: p.oy - Math.abs(dy) };
    return { data: r.data, w: r.w, h: r.h, ox: p.ox - (dx < 0 ? -dx : 0), oy: p.oy - (dy < 0 ? -dy : 0) };
  }
  function addShadow(bm){
    const [vx, vy] = SHADOW_DIRS[shadowDir] || [0,0];
    if(!vx && !vy) return bm;
    const dx = vx*shadowDist, dy = vy*shadowDist;
    const glitch = shadowMode === 'glitch';
    // 지직은 양쪽으로 어긋나므로 양쪽 다 늘림
    const W = bm.w + Math.abs(dx)*(glitch ? 2 : 1), H = bm.h + Math.abs(dy)*(glitch ? 2 : 1);
    const ox = glitch ? Math.abs(dx) : (dx < 0 ? -dx : 0), oy = glitch ? Math.abs(dy) : (dy < 0 ? -dy : 0); // 글자 시작 위치
    const out = new Uint8Array(W*H);
    // v가 null이면 원래 값(글자·테두리)을 그대로 옮김
    const stampAt = (sx, sy, v) => { for(let y=0; y<bm.h; y++) for(let x=0; x<bm.w; x++){ const o = bm.data[y*bm.w+x]; if(o) out[(y+oy+sy)*W + (x+ox+sx)] = v == null ? o : v; } };
    if(glitch) stampAt(-dx, -dy, SHADOW2); // 색 2 (반대쪽) 먼저
    stampAt(dx, dy, SHADOW);                // 색 1 (화살표 방향). 두 색이 겹치는 칸은 색 1만 남음
    stampAt(0, 0, null);                    // 글자(와 테두리)가 그림자 위에 오도록
    return { data: out, w: W, h: H };
  }
  const cellColor = v => v === SHADOW2 ? glitchColors[1]
    : v === OUTLINE ? outlineColor
    : v === SHADOW ? (shadowMode === 'glitch' ? glitchColors[0] : shadowColor)
    : activeColor;
  // 1 = 칠할 색, 2 = 그림자 색(지직이면 색 1), 254 = 테두리, 255 = 지직 색 2, 3 이상 = 옮기거나 복사한 칸의 원래 색 (stamp.colors)
  const stampColor = v => (v === SHADOW2 || v === OUTLINE) ? cellColor(v) : v >= 3 ? (stamp && stamp.colors ? stamp.colors[v-3] : null) : cellColor(v);

  function renderShadowUI(){
    document.querySelectorAll('#shadowDirRow .dir-btn').forEach(b =>
      b.classList.toggle('active', b.dataset.dir === shadowDir));
    document.getElementById('shadowOpts').classList.toggle('show', shadowDir !== 'none');
    document.getElementById('shadowDistLabel').textContent = t('{n}칸', {n: shadowDist});
    document.getElementById('shadowDistDown').disabled = shadowDist <= 1;
    document.getElementById('shadowDistUp').disabled = shadowDist >= 4;
    document.querySelectorAll('#outlineRow .dir-btn').forEach(b => {
      const n = +b.dataset.ol;
      b.classList.toggle('active', n === outlineSize);
      if(n) b.textContent = t('{n}칸', {n});
    });
    document.getElementById('outlineOpts').classList.toggle('show', outlineSize > 0);
    if(outlineSize) renderShadowPalette('outlinePalette', outlineColor, c => { outlineColor = c; }, '테두리 색 고르기');
    const glitch = shadowMode === 'glitch';
    document.querySelectorAll('#shadowModeRow .dir-btn').forEach(b => b.classList.toggle('active', b.dataset.smode === shadowMode));
    document.getElementById('shadowColorLabel').textContent = t(glitch ? '색 1' : '색');
    document.getElementById('shadowColor2Label').textContent = t('색 2');
    document.getElementById('shadowColor2Row').style.display = glitch ? '' : 'none';
    document.getElementById('shadowHint').textContent = glitch ? t('화살표 방향으로 색 1, 반대쪽으로 색 2가 어긋나요. 두 색이 겹치는 칸은 색 1이에요.') : '';
    if(glitch){
      renderShadowPalette('shadowPalette', glitchColors[0], c => { glitchColors[0] = c; }, '그림자 색 1 고르기');
      renderShadowPalette('shadowPalette2', glitchColors[1], c => { glitchColors[1] = c; }, '그림자 색 2 고르기');
    } else {
      renderShadowPalette('shadowPalette', shadowColor, c => { shadowColor = c; }, '그림자 색 고르기');
    }
  }
  // 그림자 색 고르는 작은 팔레트 (칠할 색 팔레트 + 지금 색 + 직접 입력)
  function renderShadowPalette(id, current, setColor, pickerTitle){
    const el = document.getElementById(id);
    el.innerHTML = '';
    const cur = current.toUpperCase();
    const list = [...new Set(PRESET_COLORS.map(c => c.toUpperCase()))];
    if(!list.includes(cur)) list.unshift(cur);
    const pick = c => { setColor(c); renderShadowUI(); if(stamp) drawGrid(); saveState(); };
    list.forEach(c => {
      const sw = document.createElement('div');
      sw.className = 'swatch' + (c === cur ? ' selected' : '');
      sw.style.background = c; sw.title = c;
      sw.addEventListener('click', ()=>pick(c));
      el.appendChild(sw);
    });
    const add = document.createElement('button');
    add.type = 'button'; add.className = 'add-color'; add.textContent = '+'; add.title = t('다른 색 (헥스코드 입력)');
    add.style.width = add.style.height = '32px';
    add.addEventListener('click', ()=>openHexPicker(current, pickerTitle, pick));
    el.appendChild(add);
  }
  document.querySelectorAll('#shadowDirRow .dir-btn').forEach(b => b.addEventListener('click', ()=>{
    shadowDir = b.dataset.dir; renderShadowUI(); saveState();
  }));
  document.querySelectorAll('#outlineRow .dir-btn').forEach(b => b.addEventListener('click', ()=>{
    outlineSize = +b.dataset.ol; renderShadowUI(); saveState();
  }));
  document.querySelectorAll('#shadowModeRow .dir-btn').forEach(b => b.addEventListener('click', ()=>{
    shadowMode = b.dataset.smode; renderShadowUI(); saveState();
  }));
  document.getElementById('shadowDistDown').addEventListener('click', ()=>{ shadowDist = Math.max(1, shadowDist-1); renderShadowUI(); saveState(); });
  document.getElementById('shadowDistUp').addEventListener('click', ()=>{ shadowDist = Math.min(4, shadowDist+1); renderShadowUI(); saveState(); });

  /* ===== 숫자칸 − ＋ 버튼 (꾹 누르면 계속) ===== */
  document.querySelectorAll('.num-step .step-btn').forEach(btn => {
    const inp = document.getElementById(btn.dataset.for);
    const step = parseInt(btn.dataset.step, 10);
    const bump = () => {
      const mn = parseInt(inp.min, 10), mx = parseInt(inp.max, 10);
      const cur = parseInt(inp.value, 10);
      const next = Math.max(mn, Math.min(mx, (isNaN(cur) ? 0 : cur) + step));
      if(next === cur) return;
      inp.value = next;
      inp.dispatchEvent(new Event('input', { bubbles: true })); // 저장·미리보기 갱신
    };
    let holdT = null, repT = null;
    const stop = () => { clearTimeout(holdT); clearInterval(repT); holdT = repT = null; };
    btn.addEventListener('pointerdown', e => {
      e.preventDefault();
      bump();
      holdT = setTimeout(() => { repT = setInterval(bump, 80); }, 400);
    });
    ['pointerup', 'pointerleave', 'pointercancel'].forEach(ev => btn.addEventListener(ev, stop));
    btn.addEventListener('keydown', e => { if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); bump(); } });
  });

  /* ===== 실시간 미리보기 ===== */
  // 문구·폰트·크기·간격·흐름·그림자를 바꾸면 '도안에 글자 넣기'를 누르지 않아도 캔버스에 바로 떠서 보임.
  // 확정 전까지는 떠 있는 상태라, 완료를 누르거나 끌어서 놓아야 실제 도안에 들어감.
  let livePreview = true, previewGen = 0, quietStamp = false, previewTimer = null;
  function warnUser(msg, quiet){
    if(quiet){ setPreviewNote(msg); return; }
    uiAlert(msg);
  }
  function setPreviewNote(msg){
    const el = document.getElementById('previewNote');
    if(!el) return;
    el.textContent = msg || '';
    el.style.display = msg ? '' : 'none';
  }
  function refreshTextStamp(input){
    const prev = stamp && stamp.isText ? { x: stamp.x, y: stamp.y, w: stamp.w, h: stamp.h, mode: stamp.mode } : null;
    setPreviewNote('');
    quietStamp = true;
    try{ startStamp(input, { text: true, keepPos: prev }); }
    finally{ quietStamp = false; }
  }
  function schedulePreview(){
    if(!livePreview) return;
    clearTimeout(previewTimer);
    previewTimer = setTimeout(()=>textToPattern({ preview: true }), 180);
  }
  // 글자 탭 안에서 무언가 바뀌면 미리보기 갱신 (확정 버튼·미리보기 스위치 자체는 제외)
  const paneText = document.getElementById('pane-text');
  ['input', 'change'].forEach(ev => paneText.addEventListener(ev, e => {
    if(e.target.id === 'liveToggle') return;
    // 글자칸·숫자칸은 칠 때마다 'input'이 이미 미리보기를 갱신함. 커서가 빠질 때 오는 'change'까지 받으면
    // "이대로 도안에 넣기"를 누르는 순간 확정된 글자가 곧바로 다시 떠오름 (change는 확정보다 먼저, 미리보기 예약은 확정보다 뒤에 실행됨)
    if(ev === 'change' && (e.target.tagName === 'TEXTAREA' || e.target.type === 'number' || e.target.type === 'text')) return;
    schedulePreview();
  }));
  paneText.addEventListener('click', e => {
    const btn = e.target.closest('button, .swatch');
    if(!btn || btn.id === 'convertBtn' || btn.closest('.live-row')) return;
    schedulePreview();
  });
  document.getElementById('liveToggle').addEventListener('change', e => {
    livePreview = e.target.checked;
    try{ localStorage.setItem('crochet-live-preview', livePreview ? '1' : '0'); }catch(err){}
    if(!livePreview && stamp && stamp.isText) cancelStamp();
    renderFitUI();
    if(livePreview) schedulePreview();
  });
  try{ livePreview = localStorage.getItem('crochet-live-preview') !== '0'; }catch(e){}
  document.getElementById('liveToggle').checked = livePreview;

  convertBtn.addEventListener('click', ()=>{
    // 미리보기로 떠 있는 글자가 있으면 그대로 확정, 없으면 새로 만들기
    if(livePreview && stamp && stamp.isText){ placeStamp(); renderFitUI(); return; }
    textToPattern();
  });

  /* ===== 글자 옮기기 (넣은 글자를 원하는 위치로 옮긴 뒤 확정) ===== */
  // stamp.x, stamp.y = 글자 왼쪽 위 칸의 위치 (도안 데이터 기준, 격자 밖으로 일부 나가도 됨)
  let stamp = null;
  const stampBar = document.getElementById('stampBar');
  const workArea = document.querySelector('.area-work');

  function clampStamp(){
    if(!stamp) return;
    // 옮기는 글자이 최소 한 칸은 격자 안에 걸쳐 있도록
    stamp.x = Math.max(-(stamp.w - 1), Math.min(cols - 1, stamp.x));
    stamp.y = Math.max(-(stamp.h - 1), Math.min(rows - 1, stamp.y));
  }
  let fitMode = 'keep', fitMargin = 2, lastTextSize = null;
  const LIVE_HINT = '캔버스에서 끌어 위치를 정한 뒤 넣어주세요.';
  const KEEP_HINT = '누르면 글자가 도안 위에 올라와요.';
  function renderFitUI(){
    document.querySelectorAll('#fitModeRow .fit-btn').forEach(b => b.classList.toggle('active', b.dataset.fit === fitMode));
    document.getElementById('fitOpts').classList.toggle('show', fitMode === 'fit');
    document.getElementById('fitMarginInput').value = fitMargin;
    const floating = typeof stamp !== 'undefined' && stamp && stamp.isText;
    document.getElementById('convertBtn').textContent = (livePreview && floating)
      ? t('이대로 도안에 넣기')
      : (fitMode === 'fit' ? t('글자에 맞춰 도안 만들기') : t('도안에 글자 넣기'));
    document.getElementById('convertHint').style.display = (fitMode === 'fit' && !livePreview) ? 'none' : '';
    document.getElementById('convertHint').textContent = livePreview ? t(LIVE_HINT) : t(KEEP_HINT);
    const pv = document.getElementById('fitPreview');
    pv.textContent = lastTextSize
      ? t('→ {c}코 × {r}단', {c: lastTextSize.w + fitMargin*2, r: lastTextSize.h + fitMargin*2})
      : '';
  }
  document.querySelectorAll('#fitModeRow .fit-btn').forEach(b => b.addEventListener('click', ()=>{
    fitMode = b.dataset.fit; renderFitUI(); saveState();
  }));
  document.getElementById('fitMarginInput').addEventListener('input', e=>{
    const v = parseInt(e.target.value, 10);
    if(isNaN(v)) return;
    fitMargin = Math.max(0, Math.min(20, v));
    renderFitUI(); saveState();
  });

  // 격자를 글자 크기 + 여백에 딱 맞게 새로 만들고 글자를 가운데에 바로 넣음
  function fitGridToText(bm){
    const m = fitMargin;
    const nc = bm.w + m*2, nr = bm.h + m*2;
    if(nc > 200 || nr > 200){
      uiAlert(t('글자가 여백 포함 {c}코 × {r}단이라 최대 크기(200)를 넘어요. 글자 크기나 여백을 줄이거나 문구를 나눠서 넣어주세요.', {c: nc, r: nr}));
      return;
    }
    const snap = { rows, cols, data: gridData.slice() };
    rows = nr; cols = nc;
    gridData = new Array(nr*nc).fill(null);
    rowsInput.value = rows; colsInput.value = cols;
    for(let y=0; y<bm.h; y++){
      for(let x=0; x<bm.w; x++){
        const v = bm.data[y*bm.w+x];
        if(v) gridData[(y+m)*nc + (x+m)] = cellColor(v);
      }
    }
    recordUndo(snap);
    sizeCanvas();
    drawGrid();
    saveState();
    if(!window.matchMedia('(min-width: 900px)').matches) document.querySelector('.canvas-card').scrollIntoView({ behavior:'smooth', block:'start' }); // 좁은 화면에서만 (넓은 화면은 캔버스가 늘 보임)
    toast(t('격자를 {c}코 × {r}단으로 맞췄어요', {c: cols, r: rows}));
  }

  // 조각들을 하나의 비트맵으로 합침 (그림자 먼저, 글자를 위에). 조각 위치가 음수가 되면 전체 기준점을 옮겨 화면상 위치는 그대로 유지
  function composeStamp(st){
    const ps = st.pieces;
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    ps.forEach(p => { x0 = Math.min(x0, p.ox); y0 = Math.min(y0, p.oy); x1 = Math.max(x1, p.ox + p.w); y1 = Math.max(y1, p.oy + p.h); });
    if(x0 !== 0 || y0 !== 0){
      ps.forEach(p => { p.ox -= x0; p.oy -= y0; });
      if(st.x != null){ st.x += x0; st.y += y0; }
    }
    const W = x1 - x0, H = y1 - y0, data = new Uint8Array(W*H);
    // 그림자 → 테두리 → 글자·장식·옮긴 칸 순서로 깔아서, 옆 글자의 테두리가 글자를 덮지 않게 함
    const layer = v => isShadowVal(v) ? 0 : v === OUTLINE ? 1 : 2;
    [0, 1, 2].forEach(pass => ps.forEach(p => {
      for(let y=0; y<p.h; y++) for(let x=0; x<p.w; x++){
        const v = p.data[y*p.w+x];
        if(v && layer(v) === pass) data[(p.oy+y)*W + (p.ox+x)] = v;
      }
    }));
    st.data = data; st.w = W; st.h = H;
  }

  function startStamp(input, opts){
    if(stamp) cancelStamp(); // 옮기던 글자가 있으면 먼저 취소
    const isDecor = opts && opts.decor;
    const pieces = input.pieces || [{ data: input.data, w: input.w, h: input.h, ox: 0, oy: 0 }];
    const st = { pieces };
    composeStamp(st);
    const snap = (opts && opts.snap) || { rows, cols, data: gridData.slice() };
    let resized = false, px, py;
    if(!isDecor) lastTextSize = { w: st.w, h: st.h };
    if(!isDecor && fitMode === 'fit'){
      // 격자를 글자 + 여백에 딱 맞게 새로 만들고, 글자는 떠 있는 상태로 올려서 바로 다듬을 수 있게 함
      const m = fitMargin, nc = st.w + m*2, nr = st.h + m*2;
      if(nc > 200 || nr > 200){
        warnUser(t('글자가 여백 포함 {c}코 × {r}단이라 최대 크기(200)를 넘어요. 글자 크기나 여백을 줄이거나 문구를 나눠서 넣어주세요.', {c: nc, r: nr}), quietStamp);
        return;
      }
      rows = nr; cols = nc; gridData = new Array(nr*nc).fill(null);
      rowsInput.value = rows; colsInput.value = cols;
      sizeCanvas();
      resized = true; px = m; py = m;
      renderFitUI();
    } else {
      const needW = st.w + 2, needH = st.h + 2; // 둘레 1칸 여백
      if(needW > 200 || needH > 200){
        warnUser(t('글자가 {c}코 × {r}단이라 최대 크기(200)를 넘어요. 글자 크기를 줄이거나 문구를 나눠서 넣어주세요.', {c: needW, r: needH}), quietStamp);
        return;
      }
      var expL = 0, expT = 0; // 격자를 늘릴 때 기존 내용이 밀린 칸 수
      if(!(opts && opts.noExpand) && (needW > cols || needH > rows)){
        const nc = Math.max(cols, needW), nr = Math.max(rows, needH);
        const left = Math.floor((nc - cols) / 2), top = Math.floor((nr - rows) / 2);
        expL = left; expT = top;
        const nd = new Array(nr*nc).fill(null);
        for(let y=0; y<rows; y++) for(let x=0; x<cols; x++) nd[(y+top)*nc + (x+left)] = gridData[y*cols+x];
        rows = nr; cols = nc; gridData = nd;
        rowsInput.value = rows; colsInput.value = cols;
        sizeCanvas();
        resized = true;
      }
      px = Math.floor((cols - st.w) / 2); py = Math.floor((rows - st.h) / 2);
      if(opts && opts.at && !resized){ px = opts.at.x; py = opts.at.y; }
      // 미리보기 갱신: 직전 위치의 가운데를 기준으로 유지 (글자가 커지거나 작아져도 제자리에서)
      const kp = opts && opts.keepPos;
      if(kp){
        px = kp.x + expL + Math.round((kp.w - st.w) / 2);
        py = kp.y + expT + Math.round((kp.h - st.h) / 2);
        // 격자 안에 다 들어갈 수 있으면 밖으로 삐져나가지 않게
        if(st.w <= cols) px = Math.min(Math.max(px, 0), cols - st.w);
        if(st.h <= rows) py = Math.min(Math.max(py, 0), rows - st.h);
      }
    }
    const keepMode = opts && opts.keepPos && opts.keepPos.mode === 'letter' && st.pieces.length > 1;
    stamp = Object.assign(st, { snap, resized, x: px, y: py, mode: keepMode ? 'letter' : 'whole', sel: -1,
                                isText: !isDecor, colors: input.colors || null,
                                lifted: !!(opts && opts.lifted), restoreOnCancel: !!(opts && opts.lifted),
                                origOffsets: pieces.map(p => [p.ox, p.oy]) });
    clampStamp();
    stampBar.classList.add('show');
    workArea.classList.add('stamping');
    renderStampMode();
    updateUndoButtons();
    drawGrid();
    renderFitUI();
    if(quietStamp || (opts && (opts.lifted || opts.paste))) return;
    if(!window.matchMedia('(min-width: 900px)').matches) document.querySelector('.canvas-card').scrollIntoView({ behavior:'smooth', block:'start' }); // 좁은 화면에서만 (넓은 화면은 캔버스가 늘 보임)
    if(resized) toast(t(fitMode === 'fit' && !isDecor ? '격자를 {c}코 × {r}단으로 맞췄어요' : '글자가 들어가도록 격자를 {c}코 × {r}단으로 늘렸어요', {c: cols, r: rows}));
  }

  /* ----- 통째로 / 글자 하나씩 옮기기 ----- */
  function renderStampMode(){
    if(!stamp) return;
    const multi = stamp.pieces.length > 1;
    if(!multi) stamp.mode = 'whole';
    document.getElementById('stampModeRow').classList.toggle('hide', !multi);
    document.querySelectorAll('#stampModeRow .smode-btn').forEach(b => b.classList.toggle('active', b.dataset.smode === stamp.mode));
    const letter = stamp.mode === 'letter';
    document.getElementById('stampTitle').textContent = t(letter ? '글자 하나씩 옮기기' : (stamp.lifted ? '선택한 부분 옮기기' : (stamp.isText ? '글자 위치 옮기기' : '위치 옮기기')));
    document.getElementById('stampDesc').textContent = t(letter
      ? '· 옮길 글자를 눌러서 끌어요. 화살표는 고른 글자만 한 칸씩 움직여요. 다 되면 완료를 눌러요.'
      : '· 격자를 손가락으로 끌면 손을 뗀 자리에 고정돼요. 화살표로 한 칸씩 맞춘 뒤엔 완료를 눌러요. 칠할 색을 누르면 글자 색이 바뀌어요.');
    document.getElementById('stampResetBtn').style.display = letter ? '' : 'none';
  }
  document.querySelectorAll('#stampModeRow .smode-btn').forEach(b => b.addEventListener('click', ()=>{
    if(!stamp) return;
    stamp.mode = b.dataset.smode;
    if(stamp.mode === 'whole') stamp.sel = -1;
    renderStampMode(); drawGrid();
  }));
  document.getElementById('stampResetBtn').addEventListener('click', ()=>{
    if(!stamp) return;
    // 첫 글자의 화면 위치는 그대로 두고, 나머지 글자를 처음 배치로 되돌림
    const p0 = stamp.pieces[0], wx = stamp.x + p0.ox, wy = stamp.y + p0.oy;
    stamp.pieces.forEach((p, i) => { p.ox = stamp.origOffsets[i][0]; p.oy = stamp.origOffsets[i][1]; });
    stamp.x = wx - p0.ox; stamp.y = wy - p0.oy;
    composeStamp(stamp); clampStamp(); drawGrid();
  });
  // 누른 칸에 있는 글자 조각 찾기 (정확히 안 맞으면 가장 가까운 글자)
  function pieceAt(gi, gj){
    if(!stamp) return -1;
    const lx = gj - stamp.x, ly = gi - stamp.y;
    const ps = stamp.pieces;
    for(let k=ps.length-1; k>=0; k--){
      const p = ps[k], x = lx - p.ox, y = ly - p.oy;
      if(x >= 0 && y >= 0 && x < p.w && y < p.h && p.data[y*p.w+x]) return k;
    }
    let best = -1, bestD = 4; // 4칸 이내만
    ps.forEach((p, k) => {
      const dx = Math.max(p.ox - lx, 0, lx - (p.ox + p.w - 1));
      const dy = Math.max(p.oy - ly, 0, ly - (p.oy + p.h - 1));
      const dd = Math.max(dx, dy);
      if(dd < bestD){ bestD = dd; best = k; }
    });
    return best;
  }
  function movePiece(k, wx, wy){
    const p = stamp.pieces[k];
    p.ox = wx - stamp.x; p.oy = wy - stamp.y;
    composeStamp(stamp); clampStamp(); requestDraw();
  }

  function cancelStamp(){
    if(!stamp) return;
    if(stamp.resized || stamp.restoreOnCancel){
      rows = stamp.snap.rows; cols = stamp.snap.cols; gridData = stamp.snap.data;
      rowsInput.value = rows; colsInput.value = cols;
      sizeCanvas();
    }
    endStamp();
  }
  function endStamp(){
    stamp = null;
    setTimeout(()=>{ try{ renderFitUI(); }catch(e){} }, 0);
    stampBar.classList.remove('show');
    workArea.classList.remove('stamping');
    updateUndoButtons();
    drawGrid();
  }
  function placeStamp(){
    if(!stamp) return;
    // 되돌리기하면 글자를 넣기 전(격자를 늘리기 전) 상태로
    recordUndo(stamp.snap);
    let n = 0;
    for(let y=0; y<stamp.h; y++){
      for(let x=0; x<stamp.w; x++){
        const v = stamp.data[y*stamp.w+x];
        if(!v) continue;
        const gy = stamp.y + y, gx = stamp.x + x;
        if(gy < 0 || gx < 0 || gy >= rows || gx >= cols) continue;
        gridData[gy*cols+gx] = stampColor(v); n++;
      }
    }
    const wasText = stamp.isText;
    endStamp();
    saveState();
    toast(t(wasText ? '글자를 넣었어요' : '제자리에 놓았어요'));
  }
  function drawStampOverlay(){
    if(!stamp) return;
    drawStampBody();
    if(stamp.mode === 'letter' && stamp.sel >= 0 && stamp.pieces[stamp.sel]){
      const p = stamp.pieces[stamp.sel];
      const gx0 = stamp.x + p.ox, gy0 = stamp.y + p.oy;
      const left = flipped ? (cols - (gx0 + p.w)) : gx0;
      ctx.save();
      ctx.setLineDash([4, 3]);
      ctx.lineWidth = 2;
      ctx.strokeStyle = '#DFA53C';
      ctx.strokeRect(LABEL_SIZE + left*cellW - 1, LABEL_SIZE + gy0*cellH - 1, p.w*cellW + 2, p.h*cellH + 2);
      ctx.restore();
    }
  }
  function drawStampBody(){
    const dc = j => flipped ? (cols - 1 - j) : j;
    // 옮기는 글자 칸: 칠할 색으로 표시 (지우개면 배경색)
    ctx.globalAlpha = 0.85;
    for(let y=0; y<stamp.h; y++){
      for(let x=0; x<stamp.w; x++){
        const v = stamp.data[y*stamp.w+x];
        if(!v) continue;
        ctx.fillStyle = stampColor(v) || bgColor;
        const gy = stamp.y + y, gx = stamp.x + x;
        if(gy < 0 || gx < 0 || gy >= rows || gx >= cols) continue;
        ctx.fillRect(LABEL_SIZE + dc(gx)*cellW + 1, LABEL_SIZE + gy*cellH + 1, cellW - 1, cellH - 1);
      }
    }
    ctx.globalAlpha = 1;
    // 옮기는 글자 범위 점선 테두리
    const x0 = Math.max(0, stamp.x), x1 = Math.min(cols, stamp.x + stamp.w);
    const y0 = Math.max(0, stamp.y), y1 = Math.min(rows, stamp.y + stamp.h);
    if(x1 > x0 && y1 > y0){
      const left = flipped ? (cols - x1) : x0;
      ctx.save();
      ctx.setLineDash([5, 4]);
      ctx.lineWidth = 2;
      ctx.strokeStyle = '#1F5C52';
      ctx.strokeRect(LABEL_SIZE + left*cellW + 1, LABEL_SIZE + y0*cellH + 1, (x1-x0)*cellW - 1, (y1-y0)*cellH - 1);
      ctx.restore();
    }
  }
  function nudge(dx, dy){
    if(!stamp) return;
    if(stamp.mode === 'letter'){
      if(stamp.sel < 0){ toast(t('먼저 옮길 글자를 눌러주세요')); return; }
      const p = stamp.pieces[stamp.sel];
      movePiece(stamp.sel, stamp.x + p.ox + (flipped ? -dx : dx), stamp.y + p.oy + dy);
      return;
    }
    stamp.x += flipped ? -dx : dx; stamp.y += dy;
    clampStamp(); drawGrid();
  }
  document.getElementById('nudgeL').addEventListener('click', ()=>nudge(-1, 0));
  document.getElementById('nudgeR').addEventListener('click', ()=>nudge(1, 0));
  document.getElementById('nudgeU').addEventListener('click', ()=>nudge(0, -1));
  document.getElementById('nudgeD').addEventListener('click', ()=>nudge(0, 1));
  // 격자 안에서 가로/세로 가운데로 정렬
  document.getElementById('centerH').addEventListener('click', ()=>{
    if(!stamp) return;
    stamp.x = Math.floor((cols - stamp.w) / 2); clampStamp(); drawGrid();
  });
  document.getElementById('centerV').addEventListener('click', ()=>{
    if(!stamp) return;
    stamp.y = Math.floor((rows - stamp.h) / 2); clampStamp(); drawGrid();
  });
  document.getElementById('stampCancelBtn').addEventListener('click', cancelStamp);
  document.getElementById('stampPlaceBtn').addEventListener('click', placeStamp);

  /* ===== 변환할 글자 크기 (도안 격자 확대/축소와는 별개) ===== */
  // 기본(×1) = 폰트의 도트 하나가 한 칸. 키우면 도트 하나가 2×2, 3×3칸…이 되어 모양이 그대로 커짐.
  // 기본보다 작게(½배, 원래보다 작은 크기로 직접 그리기)도 시험해봤지만 한글 획이 붙어서 읽을 수 없어
  // 기본이 가장 작은 크기. 더 작은 도안이 필요하면 전기칩 한글(12칸)을 쓰면 됨.
  const SCALE_STEPS = [1, 1.5, 2, 2.5, 3, 4];
  let textScale = 1;
  // 굵은 글씨(벡터 폰트)용 글자 높이
  // 최소 16칸: 손글씨처럼 획이 가는 글꼴은 12칸쯤에서 획이 1칸 두께로 뭉개져 알아보기 어려움 (나눔손글씨 펜으로 확인)
  const DEFAULT_TEXT_HEIGHT = 20, TEXT_HEIGHT_MIN = 16, TEXT_HEIGHT_MAX = 120;
  let textHeight = DEFAULT_TEXT_HEIGHT;
  const isVectorFont = () => fontSelect.value.split('|')[1] === 'v';
  // 폰트별 최소 글자 높이(칸). 표에 없는 글꼴은 TEXT_HEIGHT_MIN(16칸).
  // 획이 가늘거나 장식이 많은 글꼴은 작게 줄이면 획이 뭉개지거나 사라져서 글꼴마다 따로 정함.
  // 본명조는 가로획이 아주 가늘어서 30칸보다 작으면 가로획이 사라짐 (月의 가로줄 3개 중 2개가 없어지는 등)
  const FONT_MIN_HEIGHT = {
    NotoSerifKRSemiBold: 30, NotoSerifKRBold: 30,
    DongleBold: 14, SingleDay: 14, EastSeaDokdo: 20,
    LeckerliOne: 12, PirataOne: 18, AbrilFatface: 18, DancingScript: 18, UnifrakturMaguntia: 24
  };
  const ABS_MIN_HEIGHT = Math.min(TEXT_HEIGHT_MIN, ...Object.values(FONT_MIN_HEIGHT)); // 어느 글꼴에서든 가능한 가장 작은 높이 (저장된 값 확인용)
  const currentFamily = () => fontSelect.value.split('|')[0];
  const hasOwnMinHeight = () => Object.prototype.hasOwnProperty.call(FONT_MIN_HEIGHT, currentFamily());
  const minTextHeight = () => hasOwnMinHeight() ? FONT_MIN_HEIGHT[currentFamily()] : TEXT_HEIGHT_MIN;
  // 가변 폰트는 도안으로 그릴 때 굵기를 지정함 (Dancing Script = 700). 표에 없는 글꼴은 굵기를 지정하지 않음(예전과 똑같이)
  const FONT_DRAW_WEIGHT = { DancingScript: 700 };
  const drawWeight = family => FONT_DRAW_WEIGHT[family] ? FONT_DRAW_WEIGHT[family] + ' ' : '';
  const defaultTextHeight = () => Math.max(DEFAULT_TEXT_HEIGHT, minTextHeight());
  // 글자 흐름 (물결/통통/오르막/내리막)
  let textFlow = 'none', flowAmt = 2;
  const FLOW_HINTS = {
    wave: '한 줄 안에서 글자가 위아래로 한 번 출렁여요.',
    bounce: '글자가 하나씩 번갈아 위로 올라가 통통 튀는 느낌이 나요.',
    up: '글자마다 조금씩 올라가요. 높낮이 = 글자 하나당 올라가는 칸 수예요.',
    down: '글자마다 조금씩 내려가요. 높낮이 = 글자 하나당 내려가는 칸 수예요.'
  };
  function renderFlow(){
    document.querySelectorAll('#flowRow .dir-btn').forEach(b => b.classList.toggle('active', b.dataset.flow === textFlow));
    document.getElementById('flowOpts').classList.toggle('show', textFlow !== 'none');
    document.getElementById('flowLabel').textContent = t('{n}칸', {n: flowAmt});
    document.getElementById('flowAmtCap').textContent = t('높낮이');
    document.getElementById('flowHint').textContent = FLOW_HINTS[textFlow] ? t(FLOW_HINTS[textFlow]) : '';
    document.getElementById('flowDown').disabled = flowAmt <= 1;
    document.getElementById('flowUp').disabled = flowAmt >= 10;
  }
  document.querySelectorAll('#flowRow .dir-btn').forEach(b => b.addEventListener('click', ()=>{
    textFlow = b.dataset.flow; renderFlow(); saveState();
  }));
  document.getElementById('flowDown').addEventListener('click', ()=>{ flowAmt = Math.max(1, flowAmt - 1); renderFlow(); saveState(); });
  document.getElementById('flowUp').addEventListener('click', ()=>{ flowAmt = Math.min(10, flowAmt + 1); renderFlow(); saveState(); });

  // 여러 줄 정렬
  let textAlign = 'left';
  function renderAlign(){
    document.querySelectorAll('#alignRow .align-btn').forEach(b => b.classList.toggle('active', b.dataset.align === textAlign));
  }
  document.querySelectorAll('#alignRow .align-btn').forEach(b => b.addEventListener('click', ()=>{
    textAlign = b.dataset.align; renderAlign(); saveState();
  }));

  function scaleBitmap(src, w, h, s){
    if(s === 1) return { data: src, w, h };
    if(s > 1){
      // 1.5배처럼 정수가 아닌 배율은 칸 수가 1,2,1,2…로 번갈아 늘어남 (모양은 유지, 획 굵기만 살짝 차이)
      const W = Math.round(w*s), H = Math.round(h*s), out = new Uint8Array(W*H);
      for(let y=0; y<H; y++) for(let x=0; x<W; x++)
        out[y*W+x] = src[Math.min(h-1, Math.floor(y/s))*w + Math.min(w-1, Math.floor(x/s))];
      return { data: out, w: W, h: H };
    }
    return { data: src, w, h };
  }

  const scaleBig = document.getElementById('scaleBig');
  const scaleSub = document.getElementById('scaleSub');
  const scaleWarn = document.getElementById('scaleWarn');
  const scaleDownBtn = document.getElementById('scaleDownBtn');
  const scaleUpBtn = document.getElementById('scaleUpBtn');
  const scaleResetBtn = document.getElementById('scaleResetBtn');
  function renderScale(){
    if(isVectorFont()){
      if(textHeight < minTextHeight()) textHeight = minTextHeight();
      scaleBig.textContent = t('{n}칸', {n: textHeight});
      scaleBig.classList.toggle('basic', textHeight === defaultTextHeight());
      scaleSub.textContent = hasOwnMinHeight() ? t('글자 높이 ({n}칸부터)', {n: minTextHeight()}) : t('글자 높이');
      document.getElementById('gapHint').style.display = 'none';
      scaleWarn.classList.remove('show');
      scaleDownBtn.disabled = textHeight <= minTextHeight();
      scaleUpBtn.disabled = textHeight >= TEXT_HEIGHT_MAX;
      scaleResetBtn.disabled = textHeight === defaultTextHeight();
      return;
    }
    document.getElementById('gapHint').style.display = '';
    const size = parseInt(fontSelect.value.split('|')[1], 10);
    const idx = SCALE_STEPS.indexOf(textScale);
    scaleBig.textContent = textScale === 1 ? t('기본') : t('{n}배', {n: textScale});
    scaleBig.classList.toggle('basic', textScale === 1);
    scaleSub.textContent = t('약 {n}칸', {n: Math.round(size * textScale)});
    scaleWarn.classList.toggle('show', textScale === 1);
    scaleDownBtn.disabled = idx <= 0;
    scaleUpBtn.disabled = idx >= SCALE_STEPS.length - 1;
    scaleResetBtn.disabled = textScale === 1;
  }
  function stepScale(d){
    if(isVectorFont()){
      // 작을 땐 1칸씩, 클수록 성큼성큼
      const step = textHeight < 20 || (d < 0 && textHeight <= 20) ? 1 : textHeight < 40 || (d < 0 && textHeight <= 40) ? 2 : 4;
      const next = Math.max(minTextHeight(), Math.min(TEXT_HEIGHT_MAX, textHeight + d*step));
      if(next === textHeight) return;
      textHeight = next; renderScale(); saveState();
      return;
    }
    const idx = SCALE_STEPS.indexOf(textScale);
    const next = SCALE_STEPS[Math.max(0, Math.min(SCALE_STEPS.length-1, idx + d))];
    if(next === textScale) return;
    textScale = next; renderScale(); saveState();
  }
  scaleDownBtn.addEventListener('click', ()=>stepScale(-1));
  scaleUpBtn.addEventListener('click', ()=>stepScale(1));
  scaleResetBtn.addEventListener('click', ()=>{
    if(isVectorFont()) textHeight = defaultTextHeight(); else textScale = 1;
    renderScale(); saveState();
  });
  fontSelect.addEventListener('change', renderScale);

  /* ===== 장식 넣기 ===== */
  // 직접 그린 작은 도트 무늬. '#' = 칠할 칸
  const DECOR_GROUPS = [
    { group:"반짝이·별", items:[
      { name:"반짝이 (소)", rows:[".#.", "###", ".#."] },
      { name:"반짝이 (중)", rows:["..#..", "..#..", "##.##", "..#..", "..#.."] },
      { name:"반짝이 (대)", rows:["...#...", "...#...", "..###..", "#######", "..###..", "...#...", "...#..."] },
      { name:"반짝임 (X)", rows:["#...#", ".#.#.", "..#..", ".#.#.", "#...#"] },
      { name:"별 (소)", rows:["..#..", "..#..", "#####", ".###.", ".#.#."] },
      { name:"별 (중)", rows:["...#...", "..###..", "#######", ".#####.", "..###..", ".##.##.", ".#...#."] },
      { name:"별 (대)", rows:["....#....", "....#....", "...###...", "#########", ".#######.", "..#####..", "..##.##..", ".##...##.", ".#.....#."] }
    ]},
    { group:"하트", items:[
      { name:"하트 (소)", rows:[".#.#.", "#####", ".###.", "..#.."] },
      { name:"하트 (중)", rows:[".##.##.", "#######", "#######", ".#####.", "..###..", "...#..."] },
      { name:"하트 (대)", rows:[".##...##.", "####.####", "#########", "#########", ".#######.", "..#####..", "...###...", "....#...."] },
      { name:"빈 하트", rows:[".##...##.", "#..#.#..#", "#...#...#", "#.......#", ".#.....#.", "..#...#..", "...#.#...", "....#...."] }
    ]},
    { group:"자연", items:[
      { name:"꽃", rows:["..#..", ".###.", "##.##", ".###.", "..#.."] },
      { name:"튤립", rows:["#.#.#", "#####", "#####", ".###.", "..#..", "#.#.#", ".###."] },
      { name:"잎사귀", rows:["...##", "..###", ".###.", "###..", "##...", "#...."] },
      { name:"달", rows:["..###.", ".##...", "##....", "##....", "##....", ".##...", "..###."] },
      { name:"해", rows:["....#....", ".#.....#.", "...###...", "..#####..", "#.#####.#", "..#####..", "...###...", ".#.....#.", "....#...."] },
      { name:"구름", rows:["..##.....", ".####.##.", "#########", "#########", ".#######."] },
      { name:"물방울", rows:["..#..", ".###.", ".###.", "#####", "#####", ".###."] }
    ]},
    { group:"귀여운 것", items:[
      { name:"웃는 얼굴", rows:["..#####..", ".#.....#.", "#..#.#..#", "#.......#", "#.#...#.#", "#..###..#", ".#.....#.", "..#####.."] },
      { name:"리본", rows:["##.....##", "###.#.###", "#########", "###.#.###", "##.....##"] },
      { name:"왕관", rows:["#..#..#", "##.#.##", "#######", "#######"] },
      { name:"음표", rows:["..##.", "..#.#", "..#..", "..#..", "###..", "###.."] }
    ]},
    { group:"테두리 줄", items:[
      { name:"점선", rows:["#.#.#.#.#.#.#.#.#"] },
      { name:"물결선", rows:[".##....##....##...", "#..#..#..#..#..#..", "....##....##....##"] },
      { name:"지그재그", rows:["#...#...#...#...#", ".#.#.#.#.#.#.#.#.", "..#...#...#...#.."] },
      { name:"체크 줄", rows:["#.#.#.#.#.#.#.#.", ".#.#.#.#.#.#.#.#"] }
    ]}
  ];
  function decorBitmap(d){
    const h = d.rows.length, w = d.rows[0].length, data = new Uint8Array(w*h);
    d.rows.forEach((r, y) => { for(let x=0; x<w; x++) data[y*w+x] = r[x] === '#' ? 1 : 0; });
    return { data, w, h };
  }
  function buildDecorRow(){
    const host = document.getElementById('decorRow');
    host.innerHTML = '';
    DECOR_GROUPS.forEach(g => {
    const cap = document.createElement('div');
    cap.className = 'decor-cap';
    cap.textContent = t(g.group);
    host.appendChild(cap);
    const row = document.createElement('div');
    row.className = 'decor-grid';
    host.appendChild(row);
    g.items.forEach(d => {
      const bm = decorBitmap(d);
      const btn = document.createElement('button');
      btn.className = 'decor-btn';
      btn.setAttribute('aria-label', t(d.name));
      btn.title = t(d.name);
      const cv = document.createElement('canvas');
      const px = Math.max(2, Math.min(4, Math.floor(30 / Math.max(bm.w, bm.h))));
      cv.width = bm.w * px; cv.height = bm.h * px;
      const c = cv.getContext('2d');
      c.fillStyle = (activeColor && activeColor !== bgColor) ? activeColor : '#24261F';
      for(let y=0; y<bm.h; y++) for(let x=0; x<bm.w; x++) if(bm.data[y*bm.w+x]) c.fillRect(x*px, y*px, px, px);
      btn.appendChild(cv);
      btn.addEventListener('click', ()=>startStamp(decorBitmap(d), { decor:true }));
      row.appendChild(btn);
    });
    });
  }

  /* ===== 내 장식 (사용자가 만든 장식) ===== */
  // 저장 형식: { id, name, w, h, data:[0|1|k+3...], colors:[...]|null }
  // 1 = 넣을 때 '칠할 색', 3 이상 = 저장할 때의 색(여러 색 장식)
  const UDECOR_KEY = 'crochet-user-decor-v1';
  let userDecors = [];
  try{ userDecors = JSON.parse(localStorage.getItem(UDECOR_KEY) || '[]').filter(d => d && d.w > 0 && d.h > 0 && Array.isArray(d.data) && d.data.length === d.w*d.h); }catch(e){ userDecors = []; }
  function saveUserDecors(){
    try{ localStorage.setItem(UDECOR_KEY, JSON.stringify(userDecors)); }
    catch(e){ toast(t('저장 공간이 부족해서 장식을 저장하지 못했어요')); }
  }
  function userDecorInput(d){
    return { data: Uint8Array.from(d.data), w: d.w, h: d.h, colors: d.colors ? d.colors.slice() : null };
  }
  function drawDecorPreview(cv, d){
    const px = Math.max(2, Math.min(4, Math.floor(30 / Math.max(d.w, d.h))));
    cv.width = d.w * px; cv.height = d.h * px;
    const c = cv.getContext('2d');
    const mono = (activeColor && activeColor !== bgColor) ? activeColor : '#24261F';
    for(let y=0; y<d.h; y++) for(let x=0; x<d.w; x++){
      const v = d.data[y*d.w+x];
      if(!v) continue;
      c.fillStyle = v >= 3 && d.colors ? d.colors[v-3] : mono;
      c.fillRect(x*px, y*px, px, px);
    }
  }
  function buildUserDecors(){
    const grid = document.getElementById('userDecorGrid');
    if(!grid) return;
    grid.innerHTML = '';
    if(!userDecors.length){
      const e = document.createElement('div');
      e.className = 'ud-empty';
      e.textContent = t('아직 만든 장식이 없어요');
      grid.appendChild(e);
      return;
    }
    userDecors.forEach(d => {
      const wrap = document.createElement('div');
      wrap.className = 'udecor';
      const btn = document.createElement('button');
      btn.className = 'decor-btn';
      btn.title = d.name; btn.setAttribute('aria-label', d.name);
      const cv = document.createElement('canvas');
      drawDecorPreview(cv, d);
      btn.appendChild(cv);
      btn.addEventListener('click', ()=>startStamp(userDecorInput(d), { decor:true }));
      wrap.appendChild(btn);
      if(!d.colors){
        const ed = document.createElement('button');
        ed.className = 'ud-act ud-edit'; ed.textContent = '✎';
        ed.title = t('편집'); ed.setAttribute('aria-label', t('편집'));
        ed.addEventListener('click', e => { e.stopPropagation(); openDecorEditor(d); });
        wrap.appendChild(ed);
      }
      const del = document.createElement('button');
      del.className = 'ud-act ud-del'; del.textContent = '✕';
      del.title = t('삭제'); del.setAttribute('aria-label', t('삭제'));
      del.addEventListener('click', async e => {
        e.stopPropagation();
        const yes = await uiDialog({ title: t('장식 지우기'), msg: t('"{n}" 장식을 지울까요?', {n: d.name}), ok: t('삭제'), danger: true });
        if(!yes) return;
        userDecors = userDecors.filter(x => x.id !== d.id);
        saveUserDecors(); buildUserDecors();
      });
      wrap.appendChild(del);
      grid.appendChild(wrap);
    });
  }
  function addUserDecor(d){
    if(userDecors.length >= 60){ toast(t('내 장식은 60개까지 저장할 수 있어요')); return false; }
    d.id = 'u' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    userDecors.push(d);
    saveUserDecors(); buildUserDecors();
    return true;
  }
  // 떠 있는 것(선택 영역·글자·장식)을 내 장식으로 저장. 한 가지 색이면 넣을 때 '칠할 색'을 따르게 함
  document.getElementById('stampSaveDecorBtn').addEventListener('click', async ()=>{
    if(!stamp) return;
    if(stamp.w > 60 || stamp.h > 60){ toast(t('장식은 60칸 이하만 저장할 수 있어요')); return; }
    const cols_ = [], data = new Array(stamp.w*stamp.h).fill(0);
    for(let k=0; k<data.length; k++){
      const v = stamp.data[k]; if(!v) continue;
      const c = stampColor(v); if(c == null) continue;
      let q = cols_.indexOf(c); if(q < 0){ cols_.push(c); q = cols_.length - 1; }
      data[k] = q + 3;
    }
    if(!data.some(v => v)){ toast(t('저장할 칸이 없어요')); return; }
    const mono = cols_.length === 1;
    const typed = await uiDialog({ title: t('내 장식에 추가'), msg: t('장식 이름을 정해주세요'), input: true,
                                   value: t('내 장식 {n}', {n: userDecors.length + 1}), ok: t('저장') });
    if(typed === null) return;
    const name = typed.trim() || t('내 장식 {n}', {n: userDecors.length + 1});
    const ok = addUserDecor({ name: name.slice(0, 20), w: stamp.w, h: stamp.h,
                              data: mono ? data.map(v => v ? 1 : 0) : data, colors: mono ? null : cols_ });
    if(ok) toast(t('내 장식에 추가했어요. 장식 탭에서 언제든 넣을 수 있어요'));
  });

  // ----- 새 장식 그리기 팝업 -----
  const decorModal = document.getElementById('decorModal');
  const deCanvas = document.getElementById('deCanvas'), deCtx = deCanvas.getContext('2d');
  let deW = 9, deH = 9, deData = new Uint8Array(81), deMode = 'draw', deCell = 20, deEditing = null, dePainting = false, dePaintVal = 1;
  const DE_MAX = 30;
  function deResize(nw, nh){
    nw = Math.max(1, Math.min(DE_MAX, nw)); nh = Math.max(1, Math.min(DE_MAX, nh));
    const nd = new Uint8Array(nw*nh);
    for(let y=0; y<Math.min(nh, deH); y++) for(let x=0; x<Math.min(nw, deW); x++) nd[y*nw+x] = deData[y*deW+x];
    deW = nw; deH = nh; deData = nd;
    deDraw();
  }
  function deDraw(){
    document.getElementById('deWLabel').textContent = deW;
    document.getElementById('deHLabel').textContent = deH;
    deCell = Math.max(6, Math.min(28, Math.floor(300 / Math.max(deW, deH))));
    const dpr = window.devicePixelRatio || 1;
    const W = deW*deCell, H = deH*deCell;
    deCanvas.style.width = W + 'px'; deCanvas.style.height = H + 'px';
    deCanvas.width = W*dpr; deCanvas.height = H*dpr;
    deCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
    deCtx.fillStyle = '#FFFFFF'; deCtx.fillRect(0, 0, W, H);
    deCtx.fillStyle = (activeColor && activeColor.toUpperCase() !== '#FFFFFF') ? activeColor : '#24261F';
    for(let y=0; y<deH; y++) for(let x=0; x<deW; x++) if(deData[y*deW+x]) deCtx.fillRect(x*deCell, y*deCell, deCell, deCell);
    for(let i=0; i<=deH; i++){ deCtx.strokeStyle = i % 5 === 0 ? 'rgba(0,0,0,0.35)' : 'rgba(0,0,0,0.12)'; deCtx.beginPath(); deCtx.moveTo(0, i*deCell+0.5); deCtx.lineTo(W, i*deCell+0.5); deCtx.stroke(); }
    for(let j=0; j<=deW; j++){ deCtx.strokeStyle = j % 5 === 0 ? 'rgba(0,0,0,0.35)' : 'rgba(0,0,0,0.12)'; deCtx.beginPath(); deCtx.moveTo(j*deCell+0.5, 0); deCtx.lineTo(j*deCell+0.5, H); deCtx.stroke(); }
    document.getElementById('deSave').disabled = !deData.some(v => v);
  }
  function deAt(e){
    const r = deCanvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - r.left) / deCell), y = Math.floor((e.clientY - r.top) / deCell);
    if(x < 0 || y < 0 || x >= deW || y >= deH) return -1;
    return y*deW + x;
  }
  deCanvas.addEventListener('pointerdown', e => {
    const k = deAt(e); if(k < 0) return;
    dePainting = true; deCanvas.setPointerCapture(e.pointerId);
    dePaintVal = deMode === 'draw' ? 1 : 0;
    deData[k] = dePaintVal; deDraw();
  });
  deCanvas.addEventListener('pointermove', e => {
    if(!dePainting) return;
    const k = deAt(e); if(k < 0 || deData[k] === dePaintVal) return;
    deData[k] = dePaintVal; deDraw();
  });
  ['pointerup', 'pointercancel'].forEach(ev => deCanvas.addEventListener(ev, ()=>{ dePainting = false; }));
  document.querySelectorAll('#deModeRow .dir-btn').forEach(b => b.addEventListener('click', ()=>{
    deMode = b.dataset.de;
    document.querySelectorAll('#deModeRow .dir-btn').forEach(x => x.classList.toggle('active', x === b));
  }));
  document.getElementById('deWDown').addEventListener('click', ()=>deResize(deW-1, deH));
  document.getElementById('deWUp').addEventListener('click', ()=>deResize(deW+1, deH));
  document.getElementById('deHDown').addEventListener('click', ()=>deResize(deW, deH-1));
  document.getElementById('deHUp').addEventListener('click', ()=>deResize(deW, deH+1));
  document.getElementById('deClearBtn').addEventListener('click', ()=>{ deData = new Uint8Array(deW*deH); deDraw(); });
  function openDecorEditor(d){
    deEditing = d || null;
    if(d){ deW = d.w; deH = d.h; deData = Uint8Array.from(d.data.map(v => v ? 1 : 0)); }
    else { deW = 9; deH = 9; deData = new Uint8Array(81); }
    document.getElementById('deName').value = d ? d.name : '';
    document.getElementById('decorModalTitle').textContent = t(d ? '장식 편집' : '새 장식 그리기');
    deMode = 'draw';
    document.querySelectorAll('#deModeRow .dir-btn').forEach(x => x.classList.toggle('active', x.dataset.de === 'draw'));
    decorModal.classList.add('show');
    deDraw();
  }
  function closeDecorEditor(){ decorModal.classList.remove('show'); deEditing = null; }
  document.getElementById('newDecorBtn').addEventListener('click', ()=>openDecorEditor(null));
  document.getElementById('deCancel').addEventListener('click', closeDecorEditor);
  decorModal.addEventListener('click', e => { if(e.target === decorModal) closeDecorEditor(); });
  document.getElementById('deSave').addEventListener('click', ()=>{
    // 빈 줄·빈 칸은 잘라내고 그린 부분만 저장
    let x0 = deW, y0 = deH, x1 = -1, y1 = -1;
    for(let y=0; y<deH; y++) for(let x=0; x<deW; x++) if(deData[y*deW+x]){ x0 = Math.min(x0,x); x1 = Math.max(x1,x); y0 = Math.min(y0,y); y1 = Math.max(y1,y); }
    if(x1 < 0) return;
    const w = x1-x0+1, h = y1-y0+1, data = [];
    for(let y=y0; y<=y1; y++) for(let x=x0; x<=x1; x++) data.push(deData[y*deW+x] ? 1 : 0);
    const name = (document.getElementById('deName').value || '').trim() || t('내 장식 {n}', {n: userDecors.length + 1});
    if(deEditing){
      Object.assign(deEditing, { name: name.slice(0, 20), w, h, data, colors: null });
      saveUserDecors(); buildUserDecors();
      toast(t('장식을 고쳤어요'));
    } else if(addUserDecor({ name: name.slice(0, 20), w, h, data, colors: null })){
      toast(t('내 장식에 추가했어요. 눌러서 도안에 넣어보세요'));
    }
    closeDecorEditor();
  });
  document.addEventListener('keydown', e => { if(e.key === 'Escape' && decorModal.classList.contains('show')) closeDecorEditor(); });

  /* ===== 색 한번에 바꾸기 ===== */
  // 빈칸(null)도 하나의 '색'으로 다룸
  const EMPTY = '__empty__';
  const toKey = v => v === null ? EMPTY : v;
  const fromKey = k => k === EMPTY ? null : k;
  const replaceFromEl = document.getElementById('replaceFrom');
  const replaceToEl = document.getElementById('replaceTo');
  const replaceBtn = document.getElementById('replaceBtn');
  let replaceFrom = null, replaceTo = null; // 선택된 키 (없으면 null)
  let lastFromSig = '', lastToSig = '';

  function makeSwatch(key, selected, onClick){
    const sw = document.createElement('div');
    if(key === EMPTY){
      sw.className = 'swatch eraser' + (selected ? ' selected' : '');
      sw.title = t('배경 (칠하지 않은 칸)');
      if(bgColor !== DEFAULT_BG) sw.style.background = bgColor;
    } else {
      sw.className = 'swatch' + (selected ? ' selected' : '');
      sw.style.background = key;
      sw.title = key;
    }
    sw.addEventListener('click', onClick);
    return sw;
  }

  function usedCounts(){
    const m = new Map();
    for(const v of gridData){ const k = toKey(v); m.set(k, (m.get(k) || 0) + 1); }
    return m;
  }

  function refreshReplaceUI(force){
    const counts = usedCounts();
    // 도안에서 사라진 색을 고르고 있었다면 선택 해제
    if(replaceFrom && !counts.has(replaceFrom)) replaceFrom = null;
    const fromKeys = [...counts.keys()].sort((a,b)=> (a===EMPTY) - (b===EMPTY));
    const fromSig = fromKeys.join(',') + '|' + replaceFrom + '|' + bgColor;
    if(force || fromSig !== lastFromSig){
      lastFromSig = fromSig;
      replaceFromEl.innerHTML = '';
      fromKeys.forEach(k => replaceFromEl.appendChild(
        makeSwatch(k, k === replaceFrom, ()=>{ replaceFrom = k; refreshReplaceUI(true); })
      ));
    }
    const toKeys = [...new Set(PRESET_COLORS)].concat([EMPTY]);
    const toSig = toKeys.join(',') + '|' + replaceTo + '|' + bgColor + '|' + LANG;
    if(force || toSig !== lastToSig){
      lastToSig = toSig;
      replaceToEl.innerHTML = '';
      toKeys.forEach(k => replaceToEl.appendChild(
        makeSwatch(k, k === replaceTo, ()=>{ replaceTo = k; refreshReplaceUI(true); })
      ));
    }
    // 버튼 상태
    if(!replaceFrom || !replaceTo){
      replaceBtn.disabled = true;
      replaceBtn.textContent = t('바꿀 색과 새 색을 골라주세요');
    } else if(replaceFrom === replaceTo){
      replaceBtn.disabled = true;
      replaceBtn.textContent = t('같은 색이에요. 다른 새 색을 골라주세요');
    } else {
      replaceBtn.disabled = false;
      replaceBtn.textContent = t('{n}칸 바꾸기', {n: counts.get(replaceFrom)});
    }
  }

  replaceBtn.addEventListener('click', ()=>{
    if(!replaceFrom || !replaceTo || replaceFrom === replaceTo) return;
    const from = fromKey(replaceFrom), to = fromKey(replaceTo);
    pushUndo();
    let n = 0;
    for(let i=0; i<gridData.length; i++){
      if(gridData[i] === from){ gridData[i] = to; n++; }
    }
    replaceFrom = null;
    drawGrid();
    saveState();
    toast(t('{n}칸의 색을 바꿨어요', {n}));
  });

  /* ===== 상태 표시줄 ===== */
  function updateStatus(){
    const a = document.getElementById('statusSize');
    if(!a) return;
    a.textContent = t('{c}코 × {r}단', {c: cols, r: rows});
    document.getElementById('statusRow').textContent = t('작업 단 {n}', {n: currentRow});
    document.getElementById('statusZoom').textContent = Math.round(zoomLevel * 100) + '%' + (realRatio ? ' · ' + t('실제 비율') : '');
    if(typeof renderGaugeText === 'function') renderGaugeText();
  }

  /* ===== 오른쪽 패널 탭 ===== */
  function showPane(name){
    document.querySelectorAll('.insp-tab').forEach(b => b.classList.toggle('active', b.dataset.pane === name));
    document.querySelectorAll('.pane').forEach(p => p.classList.toggle('active', p.id === 'pane-' + name));
    try{ localStorage.setItem('crochet-insp-pane', name); }catch(e){}
  }
  document.querySelectorAll('.insp-tab').forEach(b => b.addEventListener('click', ()=>showPane(b.dataset.pane)));
  try{
    const savedPane = localStorage.getItem('crochet-insp-pane');
    if(savedPane && document.getElementById('pane-' + savedPane)) showPane(savedPane);
  }catch(e){}
  // 패널 크기가 바뀌면(모바일 회전 등) 격자도 다시 맞춤
  if(window.ResizeObserver){
    let roTimer = null;
    new ResizeObserver(()=>{ clearTimeout(roTimer); roTimer = setTimeout(()=>{ sizeCanvas(); drawGrid(); }, 60); })
      .observe(document.querySelector('.stage .canvas-wrap'));
  }

  /* ===== 설정 카드 펼침 상태 기억 ===== */
  document.querySelectorAll('details.sec').forEach(d => {
    const key = 'crochet-sec-' + d.id;
    try{
      const v = localStorage.getItem(key);
      if(v !== null) d.open = v === '1';
    }catch(e){}
    d.addEventListener('toggle', ()=>{
      try{ localStorage.setItem(key, d.open ? '1' : '0'); }catch(e){}
    });
  });

  /* ===== 토스트 ===== */
  const toastEl = document.getElementById('toast');
  let toastTimer = null;
  function toast(msg){
    toastEl.textContent = msg;
    toastEl.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(()=>toastEl.classList.remove('show'), 2200);
  }

  /* ===== 자동 저장 (이 기기의 브라우저에 보관) ===== */
  const STORE_KEY = 'crochet-tool-v1';
  let restoring = true; // 복원 중에는 저장하지 않음
  let saveTimer = null;
  function saveState(){
    if(restoring) return;
    clearTimeout(saveTimer);
    savePending = true;
    saveTimer = setTimeout(writeState, 250);
  }
  // 창을 닫거나 새로고침·다른 앱으로 넘어갈 때 아직 안 쓴 변경을 바로 저장
  let savePending = false;
  function flushSave(){ if(savePending){ clearTimeout(saveTimer); writeState(); } }
  window.addEventListener('pagehide', flushSave);
  document.addEventListener('visibilitychange', () => { if(document.visibilityState === 'hidden') flushSave(); });
  function writeState(){
    savePending = false;
    {
      try{
        localStorage.setItem(STORE_KEY, JSON.stringify({
          rows, cols, gridData, palette: PRESET_COLORS, paletteV: 2, activeColor, bgColor,
          currentRow, flipped, zoomLevel, tool, gaugeSt, gaugeRow, realRatio,
          text: textInput.value, font: fontSelect.value, textScale,
          spaceGap: document.getElementById('spaceGapInput').value,
          shadowDir, shadowDist, shadowColor, shadowMode, glitchColors, outlineSize, outlineColor, fitMode, fitMargin,
          letterGap: document.getElementById('letterGapInput').value,
          lineGap: document.getElementById('lineGapInput').value, textAlign, textHeight, textFlow, flowAmt
        }));
      }catch(e){ console.warn('저장 실패', e); }
    }
  }
  function loadState(){
    let s = null;
    try{ s = JSON.parse(localStorage.getItem(STORE_KEY) || 'null'); }catch(e){}
    if(!s) return false;
    if(Array.isArray(s.palette)){
      if(s.paletteV === 2){
        PRESET_COLORS.length = 0;
        s.palette.forEach(c => PRESET_COLORS.push(c));
      } else if(Array.isArray(s.gridData)){
        // 예전 저장본: 기본 5색 + 도안에 실제로 쓰인 색만 남김
        const used = new Set(s.gridData.filter(Boolean).map(c => String(c).toUpperCase()));
        if(s.activeColor) used.add(String(s.activeColor).toUpperCase());
        used.forEach(c => { if(!PRESET_COLORS.some(p => p.toUpperCase() === c)) PRESET_COLORS.push(c); });
      }
    }
    if(s.activeColor !== undefined) activeColor = s.activeColor;
    if(typeof s.bgColor === 'string' && /^#[0-9A-Fa-f]{6}$/.test(s.bgColor)) bgColor = s.bgColor;
    if(s.rows && s.cols && Array.isArray(s.gridData) && s.gridData.length === s.rows*s.cols){
      rows = s.rows; cols = s.cols; gridData = s.gridData;
    }
    if(s.currentRow) currentRow = s.currentRow;
    flipped = !!s.flipped;
    if(s.zoomLevel) zoomLevel = s.zoomLevel;
    if(validGauge(s.gaugeSt) && validGauge(s.gaugeRow)){ gaugeSt = roundGauge(s.gaugeSt); gaugeRow = roundGauge(s.gaugeRow); }
    realRatio = !!s.realRatio;
    if(s.tool) setTool(s.tool);
    if(s.text != null) textInput.value = s.text;
    if(s.font) fontSelect.value = s.font;
    // 저장된 폰트가 목록에서 빠졌으면(예: 드림흐물체) 첫 번째 폰트로
    if(fontSelect.selectedIndex < 0) fontSelect.selectedIndex = 0;
    if(SCALE_STEPS.includes(s.textScale)) textScale = s.textScale;
    if(s.spaceGap != null) document.getElementById('spaceGapInput').value = s.spaceGap;
    if(s.letterGap != null) document.getElementById('letterGapInput').value = Math.max(0, Math.min(20, parseInt(s.letterGap, 10) || 0));
    if(s.lineGap != null) document.getElementById('lineGapInput').value = s.lineGap;
    if(['left','center','right'].includes(s.textAlign)) textAlign = s.textAlign;
    if(['none','wave','bounce','up','down'].includes(s.textFlow)) textFlow = s.textFlow;
    if(s.flowAmt >= 1 && s.flowAmt <= 10) flowAmt = s.flowAmt;
    if(s.textHeight >= ABS_MIN_HEIGHT && s.textHeight <= TEXT_HEIGHT_MAX) textHeight = s.textHeight;
    if(s.shadowDir && SHADOW_DIRS[s.shadowDir]) shadowDir = s.shadowDir;
    if(s.shadowDist >= 1 && s.shadowDist <= 4) shadowDist = s.shadowDist;
    if(s.fitMode === 'fit' || s.fitMode === 'keep') fitMode = s.fitMode;
    if(typeof s.fitMargin === 'number' && s.fitMargin >= 0 && s.fitMargin <= 20) fitMargin = s.fitMargin;
    if(typeof s.shadowColor === 'string' && /^#[0-9A-Fa-f]{6}$/.test(s.shadowColor)) shadowColor = s.shadowColor.toUpperCase();
    if(s.shadowMode === 'one' || s.shadowMode === 'glitch') shadowMode = s.shadowMode;
    if(Array.isArray(s.glitchColors) && s.glitchColors.length === 2 && s.glitchColors.every(c => typeof c === 'string' && /^#[0-9A-Fa-f]{6}$/.test(c))) glitchColors = s.glitchColors.map(c => c.toUpperCase());
    // 처음 기본값(빨강·파랑)을 그대로 쓰고 있었다면 새 기본값(연하늘·주황)으로
    if(glitchColors.join() === OLD_GLITCH_DEFAULT.join()) glitchColors = GLITCH_DEFAULT.slice();
    if(s.outlineSize === 0 || s.outlineSize === 1 || s.outlineSize === 2) outlineSize = s.outlineSize;
    if(typeof s.outlineColor === 'string' && /^#[0-9A-Fa-f]{6}$/.test(s.outlineColor)) outlineColor = s.outlineColor.toUpperCase();
    return true;
  }
  textInput.addEventListener('input', saveState);
  fontSelect.addEventListener('change', saveState);

  /* ===== 폰트에 없는 글자 안내 ===== */
  // 고른 폰트에 없는 글자를 입력하면 다른 글꼴로 대신 그려져 도트 모양이 깨짐 → 그때만 한 줄로 알려 줌.
  // assets/fonts/coverage.json = 폰트 파일마다 들어 있는 글자 목록 ("차이값, 개수" 쌍을 쉼표로 이은 것).
  // 폰트를 새로 넣으면 이 파일도 다시 만들어야 해요. 목록에 없는 폰트는 안내를 건너뜀.
  let fontCoverage = null, coverageReq = null, glyphNoteGen = 0;
  function loadCoverage(){
    if(!coverageReq){
      coverageReq = fetch('/assets/fonts/coverage.json')
        .then(r => r.ok ? r.json() : {})
        .catch(() => ({}))
        .then(raw => {
          fontCoverage = {};
          Object.keys(raw).forEach(k => {
            const a = String(raw[k]).split(',').map(Number), ranges = [];
            let end = 0;
            for(let i=0; i+1<a.length; i+=2){ const s = end + a[i]; end = s + a[i+1]; ranges.push(s, end); }
            fontCoverage[k] = ranges;
          });
        });
    }
    return coverageReq;
  }
  function fontHasChar(ranges, cp){ // ranges = [시작, 끝(미포함), 시작, 끝, ...]
    let lo = 0, hi = ranges.length/2 - 1;
    while(lo <= hi){
      const mid = (lo + hi) >> 1;
      if(cp < ranges[mid*2]) hi = mid - 1;
      else if(cp >= ranges[mid*2+1]) lo = mid + 1;
      else return true;
    }
    return false;
  }
  async function updateGlyphNote(){
    const el = document.getElementById('glyphNote');
    const gen = ++glyphNoteGen;
    const hide = () => { el.textContent = ''; el.style.display = 'none'; };
    const chars = Array.from(new Set(Array.from(textInput.value).filter(ch => !/\s/.test(ch))));
    // 기본 영문·숫자·기호만 썼으면 모든 폰트에 있으니, 글자 목록 파일을 아직 안 받았다면 받지 않고 넘어감
    if(!chars.length || (chars.every(ch => ch.codePointAt(0) < 0x7F) && !fontCoverage)){ hide(); return; }
    await loadCoverage();
    if(gen !== glyphNoteGen) return;
    const familyOf = v => v.split('|')[0];
    const cov = fontCoverage[familyOf(fontSelect.value)];
    if(!cov){ hide(); return; }
    const missing = chars.filter(ch => !fontHasChar(cov, ch.codePointAt(0)));
    if(!missing.length){ hide(); return; }
    const shown = missing.slice(0, 8).join(' ') + (missing.length > 8 ? ' …' : '');
    let msg = t('이 폰트에 없는 글자가 있어서 다른 글꼴로 대신 그려져요: {chars}', {chars: shown});
    const better = Array.from(fontSelect.options)
      .filter(o => o.value !== fontSelect.value && fontCoverage[familyOf(o.value)] && chars.every(ch => fontHasChar(fontCoverage[familyOf(o.value)], ch.codePointAt(0))))
      .map(o => o.textContent.trim())
      .slice(0, 3);
    if(better.length) msg += '\n' + t('이 글자가 모두 있는 폰트: {fonts}', {fonts: better.join(', ')});
    el.textContent = msg;
    el.style.display = '';
  }
  textInput.addEventListener('input', updateGlyphNote);
  fontSelect.addEventListener('change', updateGlyphNote);
  document.getElementById('spaceGapInput').addEventListener('input', saveState);
  document.getElementById('letterGapInput').addEventListener('input', saveState);
  document.getElementById('lineGapInput').addEventListener('input', saveState);

  /* ===== 도안 이미지 저장 ===== */
  function renderExport(){
    // 실제 비율로 보기를 켜 두었으면 이미지도 그 칸 모양으로 (CW = 칸 너비, CH = 칸 높이)
    const CELL = Math.max(12, Math.min(28, Math.floor(1600 / Math.max(rows, cols))));
    const CW = CELL, CH = Math.max(6, Math.round(CELL * cellAspect()));
    const LBL = 26, PAD = 16;
    const W = PAD*2 + LBL + CW*cols;
    const H = PAD*2 + LBL + CH*rows;
    const c = document.createElement('canvas');
    c.width = W; c.height = H;
    const x = c.getContext('2d');
    x.fillStyle = '#F3EFE4'; x.fillRect(0, 0, W, H);
    const ox = PAD + LBL, oy = PAD + LBL;
    const dcol = j => flipped ? (cols - 1 - j) : j;
    for(let i=0; i<rows; i++){
      for(let j=0; j<cols; j++){
        x.fillStyle = gridData[i*cols+j] || bgColor;
        x.fillRect(ox + dcol(j)*CW, oy + i*CH, CW, CH);
      }
    }
    for(let i=0; i<=rows; i++){
      const bold = (rows - i) % 5 === 0;
      x.strokeStyle = lumOf(bgColor) < 110 ? (bold ? 'rgba(255,255,255,0.5)' : 'rgba(255,255,255,0.2)') : (bold ? 'rgba(36,38,31,0.5)' : 'rgba(36,38,31,0.2)');
      x.lineWidth = bold ? 2 : 1;
      x.beginPath(); x.moveTo(ox, oy + i*CH + 0.5); x.lineTo(ox + CW*cols, oy + i*CH + 0.5); x.stroke();
    }
    for(let j=0; j<=cols; j++){
      const bold = j % 5 === 0;
      x.strokeStyle = lumOf(bgColor) < 110 ? (bold ? 'rgba(255,255,255,0.5)' : 'rgba(255,255,255,0.2)') : (bold ? 'rgba(36,38,31,0.5)' : 'rgba(36,38,31,0.2)');
      x.lineWidth = bold ? 2 : 1;
      x.beginPath(); x.moveTo(ox + j*CW + 0.5, oy); x.lineTo(ox + j*CW + 0.5, oy + CH*rows); x.stroke();
    }
    x.fillStyle = '#5B5C4F';
    x.font = '600 12px "IBM Plex Mono", monospace';
    x.textAlign = 'center'; x.textBaseline = 'middle';
    for(const col of gridLabelNums(cols, Math.ceil(24 / CW))){
      x.fillText(String(col), ox + dcol(col-1)*CW + CW/2, PAD + LBL/2);
    }
    for(const row of gridLabelNums(rows, Math.ceil(14 / CH))){
      x.fillText(String(row), PAD + LBL/2, oy + (rows - row)*CH + CH/2);
    }
    return c;
  }
  // 도안 이미지(PNG)를 만들어 콜백에 넘김: (blob, 파일 이름)
  function makeExportImage(done){
    const c = renderExport();
    const d = new Date();
    const name = `${t('코바늘도안')}_${cols}x${rows}_${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}.png`;
    c.toBlob(blob => {
      if(!blob){ toast(t('이미지를 만들지 못했어요. 격자를 줄여서 다시 시도해보세요.')); return; }
      done(blob, name);
    }, 'image/png');
  }
  function downloadExportImage(blob, name, msg){
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = name;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=>URL.revokeObjectURL(url), 2000);
    toast(msg || t('도안 이미지를 저장했어요'));
  }
  // '이미지로 저장'은 어느 기기에서나 바로 PNG 파일을 내려받음 (공유 창을 열지 않음)
  document.getElementById('saveImgBtn').addEventListener('click', ()=>{
    makeExportImage(downloadExportImage);
  });
  // '공유'는 파일 공유가 되는 터치 기기(휴대폰·태블릿)에서만 보임. 공유 시트로 사진 앱 등에 바로 저장할 수 있음
  const shareImgBtn = document.getElementById('shareImgBtn');
  try{
    const probe = new File([new Uint8Array([137, 80, 78, 71])], 'probe.png', { type:'image/png' });
    const coarse = !!(window.matchMedia && window.matchMedia('(pointer: coarse)').matches);
    shareImgBtn.hidden = !(coarse && navigator.canShare && navigator.canShare({ files:[probe] }));
  }catch(e){ shareImgBtn.hidden = true; }
  shareImgBtn.addEventListener('click', ()=>{
    makeExportImage(async (blob, name) => {
      const file = new File([blob], name, { type:'image/png' });
      try{ await navigator.share({ files:[file], title:t('코바늘 도안') }); }
      catch(e){
        if(e && e.name === 'AbortError') return; // 사용자가 공유 창을 닫음
        downloadExportImage(blob, name);         // 공유가 안 되면 내려받기로
      }
    });
  });

  /* ===== 필레로 보기 (보기 전용: 도안 데이터·저장 내용은 바꾸지 않음) ===== */
  // 필레 크로셰 공식의 숫자는 모두 이 버전 표 한 곳에 있음.
  //   k = 빈 칸을 채우는 사슬 수, h = 기둥 높이(사슬 수로 셈: 한길긴뜨기 3, 두길긴뜨기 4)
  //   turnSolid / turnEmpty = 단 바꿀 때 세우는 사슬 수 (다음 단 첫 칸이 막힌 칸이면 3코 = 첫 기둥 1코로 셈 / 빈 칸이면 3코 + k코)
  // 이 표로 filetPlan이 계산하는 값 (n = 도안 가로 칸 수):
  //   한 줄 총 코수 = (k+1)×n + 1
  //   1단 첫 칸이 빈 칸:   시작 사슬 = (k+1)×n + k + h, 첫 코는 바늘에서 (h + 2k + 1)번째 사슬
  //   1단 첫 칸이 막힌 칸: 시작 사슬 = (k+1)×n + h,     첫 코는 바늘에서 (h + 1)번째 사슬
  //   a: 2n+1 / 빈 칸 시작 2n+4코·6번째 / 막힌 칸 시작 2n+3코·4번째 / 단 바꿀 때 4코·3코
  //   b: 3n+1 / 빈 칸 시작 3n+5코·8번째 / 막힌 칸 시작 3n+3코·4번째 / 단 바꿀 때 5코·3코
  //   c: 3n+1 / 빈 칸 시작 3n+6코·9번째 / 막힌 칸 시작 3n+4코·5번째 / 단 바꿀 때 5코·3코
  // ※ 아직 실제로 떠서 확인하지 않은 값 3개: a의 막힌 칸 시작(2n+3, 4번째), a의 단 바꿀 때 4코(turnEmpty),
  //    c의 막힌 칸 시작(3n+4, 5번째). 떠 보고 다르면 이 표의 숫자만 고치면 됨.
  const FILET_VERSIONS = {
    a: { k:1, h:3, stitch:'dc', turnSolid:3, turnEmpty:4, label:'사슬 1 + 한길긴뜨기' }, // 확인 전: 막힌 칸 시작 2n+3·4번째, 단 바꿀 때 4코
    b: { k:2, h:3, stitch:'dc', turnSolid:3, turnEmpty:5, label:'사슬 2 + 한길긴뜨기' }, // 기본값
    c: { k:2, h:4, stitch:'tr', turnSolid:3, turnEmpty:5, label:'사슬 2 + 두길긴뜨기' }, // 확인 전: 막힌 칸 시작 3n+4·5번째
  };
  const FILET_DEFAULT_VERSION = 'b';
  // 순수 계산 함수 (화면·저장과 상관없음. 자동 점검이 직접 부름)
  // input = { cols, rows, solid }: solid[i*cols + j]가 true면 막힌 칸 (i = 위에서 0, j = 왼쪽에서 0)
  // 1단 = 맨 아래 줄. 홀수 단은 오른쪽→왼쪽, 짝수 단은 왼쪽→오른쪽 → 1단 첫 칸 = 맨 아래 줄의 맨 오른쪽 칸
  function filetPlan(input, version){
    const ver = FILET_VERSIONS[version] ? version : FILET_DEFAULT_VERSION;
    const v = FILET_VERSIONS[ver];
    const n = input.cols, R = input.rows, k = v.k, h = v.h;
    const rowList = [];
    for(let r = 1; r <= R; r++){
      const i = R - r, rtl = r % 2 === 1;
      const cells = [];
      for(let q = 0; q < n; q++) cells.push(!!input.solid[i*n + (rtl ? n-1-q : q)]); // 작업 순서대로
      const runs = [];
      cells.forEach(s => { const last = runs[runs.length-1]; if(last && last.solid === s) last.n++; else runs.push({ solid:s, n:1 }); });
      rowList.push({ row:r, dir: rtl ? 'rtl' : 'ltr', cells, runs, turn: r === 1 ? null : (cells[0] ? v.turnSolid : v.turnEmpty) });
    }
    const firstEmpty = !(rowList[0] && rowList[0].cells[0]);
    const base = (k+1)*n;
    return {
      version: ver, k, h, stitch: v.stitch, cols: n, rows: R,
      rowStitches: base + 1,
      firstEmpty,
      startChain: firstEmpty ? base + k + h : base + h,
      firstStitchAt: firstEmpty ? h + 2*k + 1 : h + 1,
      startParts: { upright: h, firstChains: firstEmpty ? k : 0, base },
      turnSolid: v.turnSolid, turnEmpty: v.turnEmpty,
      rowList,
    };
  }
  // "빈 칸 7, 막힌 칸 2, 빈 칸 1"
  function filetRunsText(runs){
    return runs.map(u => t(u.solid ? '막힌 칸 {n}' : '빈 칸 {n}', { n:u.n })).join(', ');
  }
  const filetOrd = m => {
    if(LANG !== 'en') return String(m);
    const s = ['th','st','nd','rd'], v = m % 100;
    return m + (s[(v-20)%10] || s[v] || s[0]);
  };
  const filetStName = plan => t(plan.stitch === 'tr' ? '두길긴뜨기' : '한길긴뜨기');
  const filetAbbr = plan => plan.stitch === 'tr' ? 'tr' : 'dc'; // 영어 문구의 {ab} (한국어 문구에는 없음)
  function filetStartLines(plan){
    const p = plan.startParts;
    const l1 = t('1단 시작: 사슬 {n}코를 뜨고, 바늘에서 {m}번째 사슬에 첫 {st}를 떠요.', { n:plan.startChain, m:filetOrd(plan.firstStitchAt), st:filetStName(plan) });
    const l2 = plan.firstEmpty
      ? t('{n}코 = 오른쪽 세로 사슬 {h}코 + 첫 빈 칸의 사슬 {k}코 + 맨 아래 사슬 {b}코', { n:plan.startChain, h:p.upright, k:p.firstChains, b:p.base })
      : t('{n}코 = 오른쪽 세로 사슬 {h}코 + 맨 아래 사슬 {b}코', { n:plan.startChain, h:p.upright, b:p.base });
    return [l1, l2];
  }
  const filetTitleText = plan => `${t('필레 도안')} · ${t(FILET_VERSIONS[plan.version].label)} · ${t('가로 {c}칸 × 세로 {r}단', { c:plan.cols, r:plan.rows })}`;

  // 기호도 그리기 재료: 선·타원·글자 목록 (화면은 SVG, 이미지 저장은 캔버스로 같은 목록을 그림)
  function filetChartPrims(plan){
    const CW = 26, RH = plan.h === 4 ? 40 : 32, LM = 48, TOP = 12, BOT = 26;
    const n = plan.cols, R = plan.rows, k = plan.k;
    const W = LM*2 + CW*n, H = TOP + RH*R + BOT;
    const P = [];
    const xOf = c => LM + c*CW; // c번째 기둥 자리 (왼쪽부터 0..n)
    const slashes = plan.stitch === 'tr' ? 2 : 1;
    const stem = (x, yb, yt) => {
      P.push({ t:'line', x1:x, y1:yb, x2:x, y2:yt });
      P.push({ t:'line', x1:x-5, y1:yt, x2:x+5, y2:yt });              // 기둥 위 가로 막대
      for(let s = 0; s < slashes; s++){                                  // 기둥 중간 빗금 (두길긴뜨기는 2개)
        const ym = yt + (yb - yt) * (slashes === 1 ? 0.55 : 0.42 + s*0.24);
        P.push({ t:'line', x1:x-4, y1:ym+3, x2:x+4, y2:ym-3 });
      }
    };
    // 사슬 모양: p = 코 한 칸의 가로 간격. 가로 사슬은 납작한 타원(가로 반지름 0.45p, 세로 반지름 0.17p)이라 옆 사슬과 거의 닿아 한 줄로 이어져 보임.
    // 세우는 사슬은 그것을 세운 모양(가로 반지름 0.17p, 세로 반지름 = 사슬 하나 높이의 0.45배)
    const p = CW / (k+1), chRX = 0.45*p, chRY = 0.17*p;
    const chainH = (cx, cy, tag) => P.push({ t:'ell', cx, cy, rx:chRX, ry:chRY, tag });
    const chainV = (cx, cy, ry, tag) => P.push({ t:'ell', cx, cy, rx:chRY, ry, tag });
    plan.rowList.forEach(row => {
      const r = row.row, rtl = row.dir === 'rtl';
      const yb = TOP + (R - r + 1)*RH, yt = TOP + (R - r)*RH + 5;
      const startEdge = rtl ? n : 0; // 시작 쪽 가장자리: 첫 기둥 대신 세우는 사슬
      for(let c = 0; c <= n; c++) if(c !== startEdge) stem(xOf(c), yb, yt);
      row.cells.forEach((solid, q) => {
        const x0 = xOf(rtl ? n-1-q : q);
        if(solid){ for(let s = 1; s <= k; s++) stem(x0 + CW*s/(k+1), yb, yt); }
        else {
          const tag = (r === 1 && q === 0) ? 'fc-first' : '';
          // 빈 칸 사슬은 막힌 칸의 기둥 자리(코 간격 p)에, 기둥 위 막대보다 살짝 아래 높이로
          for(let s = 1; s <= k; s++) chainH(x0 + p*s, yt + chRY + 3.4, tag);
        }
      });
      const cnt = r === 1 ? plan.h : plan.turnSolid, seg = (yb - yt) / cnt;
      for(let s = 0; s < cnt; s++) chainV(xOf(startEdge), yb - seg*(s+0.5), seg*0.45, r === 1 ? 'fc-up' : '');
      P.push({ t:'text', x: rtl ? W - LM/2 : LM/2, y:(yt + yb)/2, s: rtl ? '← ' + r : r + ' →' });
    });
    // 맨 아래 시작 사슬: 가로 타원 (k+1)×n개
    const fy = TOP + R*RH + 11;
    for(let s = 0; s < (k+1)*n; s++) chainH(LM + p*(s+0.5), fy, 'fc-base');
    return { W, H, P };
  }
  const filetF = v => Math.round(v*10)/10;
  function filetChartSvg(ch){
    let lines = '', ells = '', tagged = '', texts = '';
    ch.P.forEach(p => {
      if(p.t === 'line') lines += `M${filetF(p.x1)} ${filetF(p.y1)}L${filetF(p.x2)} ${filetF(p.y2)}`;
      else if(p.t === 'ell'){
        if(p.tag) tagged += `<ellipse class="${p.tag}" cx="${filetF(p.cx)}" cy="${filetF(p.cy)}" rx="${filetF(p.rx)}" ry="${filetF(p.ry)}"/>`;
        else ells += `M${filetF(p.cx - p.rx)} ${filetF(p.cy)}a${filetF(p.rx)} ${filetF(p.ry)} 0 1 0 ${filetF(2*p.rx)} 0a${filetF(p.rx)} ${filetF(p.ry)} 0 1 0 ${filetF(-2*p.rx)} 0`;
      } else texts += `<text x="${filetF(p.x)}" y="${filetF(p.y)}">${p.s}</text>`;
    });
    return `<svg xmlns="http://www.w3.org/2000/svg" width="${ch.W}" height="${ch.H}" viewBox="0 0 ${ch.W} ${ch.H}" role="img">`
      + `<rect width="${ch.W}" height="${ch.H}" fill="#FFFFFF"/>`
      + `<g fill="none" stroke="#222222" stroke-width="1.4" stroke-linecap="round"><path d="${lines}"/><path d="${ells}"/>${tagged}</g>`
      + `<g fill="#4E5045" font-size="12" font-weight="600" font-family="IBM Plex Mono, monospace" text-anchor="middle" dominant-baseline="central">${texts}</g></svg>`;
  }
  function filetDrawChart(x, ch, ox, oy){
    x.save(); x.translate(ox, oy);
    x.fillStyle = '#FFFFFF'; x.fillRect(0, 0, ch.W, ch.H);
    x.strokeStyle = '#222222'; x.lineWidth = 1.4; x.lineCap = 'round';
    x.beginPath();
    ch.P.forEach(p => {
      if(p.t === 'line'){ x.moveTo(p.x1, p.y1); x.lineTo(p.x2, p.y2); }
      else if(p.t === 'ell'){ x.moveTo(p.cx + p.rx, p.cy); x.ellipse(p.cx, p.cy, p.rx, p.ry, 0, 0, Math.PI*2); }
    });
    x.stroke();
    x.fillStyle = '#4E5045'; x.font = '600 12px "IBM Plex Mono", monospace'; x.textAlign = 'center'; x.textBaseline = 'middle';
    ch.P.forEach(p => { if(p.t === 'text') x.fillText(p.s, p.x, p.y); });
    x.restore();
  }
  // 막힌 칸/빈 칸 미리보기 격자 (검정 = 막힌 칸, 흰색 = 빈 칸, 양옆에 단 번호)
  function filetPreviewGeom(plan){
    const cell = Math.max(8, Math.min(18, Math.floor(560 / Math.max(plan.cols, 1))));
    const L = 34;
    return { cell, L, W: L*2 + cell*plan.cols, H: cell*plan.rows + 1 };
  }
  function filetDrawPreview(x, plan, ox, oy, g){
    const { cell, L } = g, n = plan.cols, R = plan.rows;
    x.save(); x.translate(ox, oy);
    x.fillStyle = '#FFFFFF'; x.fillRect(0, 0, g.W, g.H);
    x.fillStyle = '#111111';
    plan.rowList.forEach(row => {
      const y = (R - row.row)*cell;
      row.cells.forEach((s, q) => { if(s) x.fillRect(L + (row.dir === 'rtl' ? n-1-q : q)*cell, y, cell, cell); });
    });
    x.strokeStyle = 'rgba(128,128,128,0.55)'; x.lineWidth = 1; x.beginPath();
    for(let i = 0; i <= R; i++){ x.moveTo(L, i*cell + 0.5); x.lineTo(L + n*cell, i*cell + 0.5); }
    for(let j = 0; j <= n; j++){ x.moveTo(L + j*cell + 0.5, 0); x.lineTo(L + j*cell + 0.5, R*cell); }
    x.stroke();
    x.fillStyle = '#5B5C4F'; x.font = `600 ${Math.max(9, Math.min(12, cell - 3))}px "IBM Plex Mono", monospace`; x.textBaseline = 'middle';
    const nums = cell >= 14 ? Array.from({ length:R }, (_, q) => q + 1) : [...new Set([1, ...gridLabelNums(R, Math.ceil(14 / cell))])];
    nums.forEach(r => {
      const y = (R - r)*cell + cell/2;
      x.textAlign = 'right'; x.fillText(String(r), L - 5, y);
      x.textAlign = 'left';  x.fillText(String(r), L + n*cell + 5, y);
    });
    x.restore();
  }

  const filetView = document.getElementById('filetView');
  let filetMode = false; // 필레 탭을 보고 있는 중 (도안 칸은 읽기만 함)
  const FILET_GUIDE_KEY = 'crochet-filet-guide-hide'; // '오늘은 보지 않기'를 누른 날짜 (YYYY-MM-DD)
  let filetVersion = FILET_DEFAULT_VERSION;
  let filetColorList = [];          // [색, 칸 수] 도안에 실제로 쓴 색 (많이 쓴 순서)
  let filetSolidColors = new Set(); // 막힌 칸으로 볼 색
  let filetInvert = false;
  let filetGuideShown = true;
  let filetCurrentPlan = null;
  const filetToday = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
  // 지금 도안 → 막힌 칸 표. 화면에 보이는 좌우 방향(좌우 뒤집기 포함) 그대로. gridData는 읽기만 함
  function filetSolidGrid(){
    const solid = new Array(rows*cols);
    for(let i = 0; i < rows; i++) for(let j = 0; j < cols; j++){
      const c = gridData[i*cols + j];
      let s = !!c && filetSolidColors.has(String(c).toUpperCase());
      if(filetInvert) s = !s;
      solid[i*cols + (flipped ? cols-1-j : j)] = s;
    }
    return { cols, rows, solid };
  }
  function renderFiletColors(){
    const el = document.getElementById('filetColors');
    el.innerHTML = '';
    if(!filetColorList.length){
      const e = document.createElement('span'); e.className = 'filet-empty'; e.textContent = t('칠한 칸이 없어요');
      el.appendChild(e); return;
    }
    const bgU = bgColor.toUpperCase();
    filetColorList.forEach(([c, cnt]) => {
      const lab = document.createElement('label'); lab.className = 'filet-chip';
      lab.title = (c === bgU ? c + ' · ' + t('배경색과 같은 색') : c) + ' · ' + t('{n}칸', { n:cnt });
      const cb = document.createElement('input'); cb.type = 'checkbox'; cb.checked = filetSolidColors.has(c); cb.dataset.color = c;
      cb.setAttribute('aria-label', c);
      cb.addEventListener('change', () => { if(cb.checked) filetSolidColors.add(c); else filetSolidColors.delete(c); renderFilet(); });
      const sw = document.createElement('span'); sw.className = 'filet-sw'; sw.style.background = c;
      lab.append(cb, sw); el.appendChild(lab);
    });
  }
  function filetLegendHtml(plan){
    const slashes = plan.stitch === 'tr' ? '<path d="M9 19l8-6"/><path d="M9 25l8-6"/>' : '<path d="M9 21l8-6"/>';
    const stemSvg = `<svg viewBox="0 0 26 34" aria-hidden="true"><g fill="none" stroke="#222" stroke-width="1.6" stroke-linecap="round"><path d="M13 30V5M8 5h10"/>${slashes}</g></svg>`;
    const chSvg = '<svg viewBox="0 0 26 34" aria-hidden="true"><ellipse cx="13" cy="17" rx="10.5" ry="4" fill="none" stroke="#222" stroke-width="1.4"/></svg>';
    const upSvg = '<svg viewBox="0 0 26 34" aria-hidden="true"><g fill="none" stroke="#222" stroke-width="1.4"><ellipse cx="13" cy="7" rx="1.8" ry="4.5"/><ellipse cx="13" cy="17" rx="1.8" ry="4.5"/><ellipse cx="13" cy="27" rx="1.8" ry="4.5"/></g></svg>';
    // 영어는 기둥 이름 뒤에 한 번만 (US terms)를 붙임 (사전의 "{st}" 항목, 한국어는 이름 그대로)
    return `<span>${stemSvg}${t('{st}', { st:filetStName(plan) })}</span><span>${chSvg}${t('사슬')}</span><span>${upSvg}${t('세우는 사슬 3코 - 첫 기둥 1코로 셈', { ab:filetAbbr(plan) })}</span>`;
  }
  // 보는 법 카드: 짧은 3줄 (k와 기둥 이름은 버전에 맞게)
  function renderFiletGuide(plan){
    const st = filetStName(plan), k = plan.k, ab = filetAbbr(plan);
    const items = [
      t('검정 = 막힌 칸({st} {m}코), 흰색 = 빈 칸(사슬 {k}코 + {st} 1코)', { st, ab, m:k+1, k }),
      t('홀수 단은 ←, 짝수 단은 →'),
      t('단 바꿀 때 세우는 사슬: 다음 첫 칸이 막힌 칸 {ts}코, 빈 칸 {te}코', { ts:plan.turnSolid, te:plan.turnEmpty }),
    ];
    const ul = document.getElementById('filetGuideList');
    ul.innerHTML = '';
    items.forEach(x => { const li = document.createElement('li'); li.textContent = x; ul.appendChild(li); });
    document.getElementById('filetGuide').hidden = !filetGuideShown;
    document.getElementById('filetGuideOpen').hidden = filetGuideShown;
  }
  // 줄별 설명 한 줄: "9단 ← 빈 7 · 막 2 · 빈 1 (세우는 사슬 3)"
  const filetRunsShort = runs => runs.map(u => t(u.solid ? '막 {n}' : '빈 {n}', { n:u.n })).join(' · ');
  function filetRowLine(row, plan){
    const tail = row.turn === null ? t('시작 사슬 {n}코', { n:plan.startChain }) : t('세우는 사슬 {n}', { n:row.turn });
    return `${t('{n}단', { n:row.row })} ${row.dir === 'rtl' ? '←' : '→'} ${filetRunsShort(row.runs)} (${tail})`;
  }
  function renderFilet(){
    const plan = filetPlan(filetSolidGrid(), filetVersion);
    filetCurrentPlan = plan;
    document.getElementById('filetInvertBtn').setAttribute('aria-pressed', filetInvert ? 'true' : 'false');
    const bgU = bgColor.toUpperCase();
    document.getElementById('filetColorNote').hidden = filetColorList.filter(([c]) => c !== bgU).length < 2;
    renderFiletGuide(plan);
    const st = document.getElementById('filetStart');
    st.innerHTML = '';
    filetStartLines(plan).forEach(x => { const p = document.createElement('p'); p.textContent = x; st.appendChild(p); });
    // 미리보기 격자
    const g = filetPreviewGeom(plan), pc = document.getElementById('filetPreview');
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    pc.width = Math.round(g.W * dpr); pc.height = Math.round(g.H * dpr);
    pc.style.width = g.W + 'px'; pc.style.height = g.H + 'px';
    const pctx = pc.getContext('2d'); pctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    filetDrawPreview(pctx, plan, 0, 0, g);
    // 기호도
    document.getElementById('filetLegend').innerHTML = filetLegendHtml(plan);
    const chartBox = document.getElementById('filetChart');
    chartBox.innerHTML = filetChartSvg(filetChartPrims(plan));
    chartBox.firstChild.setAttribute('aria-label', t('기호도'));
    // 줄별 설명: 한 단에 한 줄
    const ol = document.getElementById('filetRows');
    ol.innerHTML = '';
    plan.rowList.forEach(row => { const li = document.createElement('li'); li.textContent = filetRowLine(row, plan); ol.appendChild(li); });
  }
  // 도안 탭 ↔ 필레 탭. 필레 탭은 캔버스 자리에 겹쳐 보이고(캔버스는 그대로 두고 가림), 도안 데이터는 읽기만 함
  function setFiletMode(on){
    on = !!on;
    if(on === filetMode || (on && knitMode)) return;
    filetMode = on;
    appEl.classList.toggle('filet-mode', on);
    [['tabDesign', !on], ['tabFilet', on]].forEach(([id, sel]) => { const b = document.getElementById(id); b.setAttribute('aria-selected', sel ? 'true' : 'false'); b.tabIndex = sel ? 0 : -1; });
    if(on){
      const counts = new Map();
      gridData.forEach(c => { if(c){ const u = String(c).toUpperCase(); counts.set(u, (counts.get(u) || 0) + 1); } });
      filetColorList = [...counts.entries()].sort((a, b) => b[1] - a[1]);
      const bgU = bgColor.toUpperCase();
      // 기본: 배경이 아닌 칸은 전부 막힌 칸 (칠하지 않은 칸과 배경색으로 칠한 칸은 빈 칸)
      filetSolidColors = new Set(filetColorList.map(e => e[0]).filter(c => c !== bgU));
      filetInvert = false;
      let hide = null;
      try{ hide = localStorage.getItem(FILET_GUIDE_KEY); }catch(e){}
      filetGuideShown = hide !== filetToday();
      document.getElementById('filetVerSel').value = filetVersion;
      document.getElementById('filetShareBtn').hidden = shareImgBtn.hidden;
      renderFiletColors();
      renderFilet();
      filetView.scrollTop = 0; filetView.scrollLeft = 0;
      window.addEventListener('keydown', filetKey, true);
    } else {
      window.removeEventListener('keydown', filetKey, true);
      // 큰 도안이면 기호도가 무거우니 도안 탭으로 돌아갈 때 비움
      document.getElementById('filetChart').innerHTML = '';
      document.getElementById('filetRows').innerHTML = '';
      filetCurrentPlan = null;
      sizeCanvas(); drawGrid();
    }
  }
  // 필레 탭에서는 키보드 단축키(되돌리기·붙여넣기·지우기·화살표 등)가 도안에 닿지 않게 막고, Esc는 도안 탭으로
  function filetKey(e){
    if(e.key === 'Escape'){ e.preventDefault(); setFiletMode(false); document.getElementById('tabDesign').focus({ preventScroll:true }); }
    else if((e.ctrlKey || e.metaKey) && ['KeyZ','KeyY','KeyS','KeyO','KeyV','KeyX','KeyC'].includes(e.code)) e.preventDefault();
    e.stopPropagation();
  }
  document.getElementById('tabDesign').addEventListener('click', () => setFiletMode(false));
  document.getElementById('tabFilet').addEventListener('click', () => setFiletMode(true));
  document.getElementById('filetBtn').addEventListener('click', () => { setFiletMode(true); document.getElementById('tabFilet').focus({ preventScroll:true }); });
  document.getElementById('filetVerSel').addEventListener('change', e => { filetVersion = FILET_VERSIONS[e.target.value] ? e.target.value : FILET_DEFAULT_VERSION; renderFilet(); });
  document.getElementById('filetInvertBtn').addEventListener('click', () => { filetInvert = !filetInvert; renderFilet(); });
  document.getElementById('filetGuideClose').addEventListener('click', () => { filetGuideShown = false; renderFiletGuide(filetCurrentPlan); });
  document.getElementById('filetGuideToday').addEventListener('click', () => {
    try{ localStorage.setItem(FILET_GUIDE_KEY, filetToday()); }catch(e){}
    filetGuideShown = false; renderFiletGuide(filetCurrentPlan);
  });
  document.getElementById('filetGuideOpen').addEventListener('click', () => { filetGuideShown = true; renderFiletGuide(filetCurrentPlan); });

  // 필레 도안 이미지: 제목 + 시작 안내 + 미리보기 격자 + 기호도를 한 장의 PNG로
  function wrapCanvasText(x, s, maxW){
    const out = []; let line = '';
    s.split(' ').forEach(w => {
      const next = line ? line + ' ' + w : w;
      if(line && x.measureText(next).width > maxW){ out.push(line); line = w; } else line = next;
    });
    if(line) out.push(line);
    return out;
  }
  function makeFiletImage(done){
    const plan = filetCurrentPlan;
    if(!plan) return;
    const ch = filetChartPrims(plan), pv = filetPreviewGeom(plan);
    const PAD = 28, GAP = 22, FONT = 'Inter, "Apple SD Gothic Neo", "Malgun Gothic", "Noto Sans KR", sans-serif';
    const W0 = Math.max(720, ch.W, pv.W) + PAD*2;
    const meas = document.createElement('canvas').getContext('2d');
    const [l1, l2] = filetStartLines(plan);
    const lines = [];
    [['700 22px ' + FONT, filetTitleText(plan), 32], ['700 18px ' + FONT, l1, 27], ['600 16px ' + FONT, l2, 25]].forEach(([f, s, lh]) => {
      meas.font = f; wrapCanvasText(meas, s, W0 - PAD*2).forEach(l => lines.push([f, l, lh]));
    });
    const textH = lines.reduce((a, l) => a + l[2], 0);
    const H0 = PAD + textH + GAP + pv.H + GAP + ch.H + PAD;
    // 큰 도안은 휴대폰 브라우저의 캔버스 한도(약 1,600만 화소)를 넘지 않게 줄여서 그림
    const sc = Math.min(1, 8000 / W0, 8000 / H0, Math.sqrt(16e6 / (W0*H0)));
    const c = document.createElement('canvas');
    c.width = Math.max(1, Math.floor(W0*sc)); c.height = Math.max(1, Math.floor(H0*sc));
    const x = c.getContext('2d');
    x.scale(sc, sc);
    x.fillStyle = '#F3EFE4'; x.fillRect(0, 0, W0, H0);
    let y = PAD;
    x.fillStyle = '#24261F'; x.textAlign = 'left'; x.textBaseline = 'top';
    lines.forEach(([f, s, lh]) => { x.font = f; x.fillText(s, PAD, y); y += lh; });
    y += GAP;
    filetDrawPreview(x, plan, PAD, y, pv); y += pv.H + GAP;
    filetDrawChart(x, ch, PAD, y);
    const d = new Date();
    const name = `${t('필레도안')}_${plan.cols}x${plan.rows}_${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}.png`;
    c.toBlob(blob => {
      if(!blob){ toast(t('이미지를 만들지 못했어요. 격자를 줄여서 다시 시도해보세요.')); return; }
      done(blob, name);
    }, 'image/png');
  }
  document.getElementById('filetSaveImgBtn').addEventListener('click', () => {
    makeFiletImage((blob, name) => downloadExportImage(blob, name, t('필레 도안 이미지를 저장했어요')));
  });
  document.getElementById('filetShareBtn').addEventListener('click', () => {
    makeFiletImage(async (blob, name) => {
      const file = new File([blob], name, { type:'image/png' });
      try{ await navigator.share({ files:[file], title:t('필레 도안') }); }
      catch(e){
        if(e && e.name === 'AbortError') return;
        downloadExportImage(blob, name, t('필레 도안 이미지를 저장했어요'));
      }
    });
  });

  /* ===== 페이지 안 대화상자 (확인·입력·알림) ===== */
  // opts: { title, msg, input:true|false, value, ok, cancel(null이면 숨김), danger }
  // 결과: 입력창이면 글자(취소 시 null), 아니면 true/false
  function uiDialog(opts){
    return new Promise(resolve => {
      const m = document.getElementById('askModal');
      const inp = document.getElementById('askInput');
      const okB = document.getElementById('askOk'), noB = document.getElementById('askCancel');
      document.getElementById('askTitle').textContent = opts.title || '';
      document.getElementById('askMsg').textContent = opts.msg || '';
      inp.style.display = opts.input ? '' : 'none';
      inp.value = opts.value || '';
      inp.readOnly = !!opts.readOnly;
      okB.textContent = opts.ok || t('확인');
      okB.classList.toggle('danger', !!opts.danger);
      noB.textContent = opts.cancel || t('취소');
      noB.style.display = opts.cancel === null ? 'none' : '';
      const done = val => {
        m.classList.remove('show');
        okB.onclick = noB.onclick = m.onclick = inp.onkeydown = null;
        document.removeEventListener('keydown', onKey, true);
        resolve(val);
      };
      const onKey = e => { if(e.key === 'Escape'){ e.stopPropagation(); done(opts.input ? null : false); } };
      okB.onclick = () => done(opts.input ? inp.value : true);
      noB.onclick = () => done(opts.input ? null : false);
      m.onclick = e => { if(e.target === m) done(opts.input ? null : false); };
      inp.onkeydown = e => { if(e.key === 'Enter' && !e.isComposing) okB.click(); };
      document.addEventListener('keydown', onKey, true);
      m.classList.add('show');
      setTimeout(() => { if(opts.input){ inp.focus(); inp.select(); } else okB.focus(); }, 30);
    });
  }
  const uiAlert = msg => uiDialog({ msg, ok: t('확인'), cancel: null });

  /* ===== 도안 파일 저장 · 열기 · 링크 ===== */
  // 파일 형식: 쓰인 색 목록 + 칸 번호를 '연속 길이'로 줄여 담음 (200×200도 수 KB)
  const FILE_APP = 'crochet-pattern-tool';
  function patternToObject(){
    const colors = [], runs = [];
    let prev = -1, count = 0;
    for(let k=0; k<gridData.length; k++){
      const c = gridData[k];
      let v = 0;
      if(c != null){ v = colors.indexOf(c); if(v < 0){ colors.push(c); v = colors.length - 1; } v += 1; }
      if(v === prev) count++;
      else { if(count) runs.push([prev, count]); prev = v; count = 1; }
    }
    if(count) runs.push([prev, count]);
    const o = { app: FILE_APP, version: 1, savedAt: new Date().toISOString(),
             cols, rows, bg: bgColor, colors, cells: runs, palette: PRESET_COLORS.slice() };
    if(gaugeSt !== gaugeRow) o.gauge = { st: gaugeSt, row: gaugeRow }; // 정사각형(기본)이면 넣지 않음 (링크가 짧게)
    return o;
  }
  // 받은 내용을 꼼꼼히 확인한 뒤에만 적용 (잘못된 파일로 작업이 깨지지 않게)
  function validatePattern(o){
    const hex = /^#[0-9A-Fa-f]{6}$/;
    if(!o || typeof o !== 'object' || o.app !== FILE_APP) throw new Error(t('도트뜨개에서 저장한 도안 파일이 아니에요'));
    const c = o.cols|0, r = o.rows|0;
    if(c < 1 || r < 1 || c > 200 || r > 200) throw new Error(t('격자 크기가 올바르지 않아요'));
    if(!Array.isArray(o.colors) || !o.colors.every(x => hex.test(x))) throw new Error(t('색 정보가 올바르지 않아요'));
    if(!Array.isArray(o.cells)) throw new Error(t('칸 정보가 올바르지 않아요'));
    const data = new Array(c*r);
    let k = 0;
    for(const run of o.cells){
      const v = run[0]|0, n = run[1]|0;
      if(n < 1 || v < 0 || v > o.colors.length || k + n > c*r) throw new Error(t('칸 정보가 올바르지 않아요'));
      const col = v === 0 ? null : o.colors[v-1].toUpperCase();
      for(let q=0; q<n; q++) data[k++] = col;
    }
    if(k !== c*r) throw new Error(t('칸 정보가 올바르지 않아요'));
    return { cols: c, rows: r, data,
             bg: hex.test(o.bg) ? o.bg.toUpperCase() : null,
             gauge: o.gauge && validGauge(o.gauge.st) && validGauge(o.gauge.row) ? { st: roundGauge(o.gauge.st), row: roundGauge(o.gauge.row) } : null,
             palette: Array.isArray(o.palette) ? o.palette.filter(x => hex.test(x)).map(x => x.toUpperCase()).slice(0, 40) : null };
  }
  function applyPattern(p, msg){
    if(stamp) cancelStamp();
    recordUndo({ rows, cols, data: gridData.slice(), bg: bgColor }); // 열기 전 상태(배경색 포함)로 되돌릴 수 있게
    rows = p.rows; cols = p.cols; gridData = p.data;
    rowsInput.value = rows; colsInput.value = cols;
    if(p.palette && p.palette.length){
      // 내 팔레트에 없는 색만 더함 (기존 팔레트는 지우지 않음)
      p.palette.forEach(c => { if(!PRESET_COLORS.some(x => x.toUpperCase() === c)) PRESET_COLORS.push(c); });
    }
    // 도안에 쓰인 색도 팔레트에 보이게
    gridData.forEach(c => { if(c && !PRESET_COLORS.some(x => x.toUpperCase() === c.toUpperCase())) PRESET_COLORS.push(c); });
    if(p.bg) bgColor = p.bg;
    // 게이지가 담긴 도안이면 그 게이지로 실제 비율 보기를 켬
    if(p.gauge){ gaugeSt = p.gauge.st; gaugeRow = p.gauge.row; realRatio = true; renderGaugeUI(); }
    currentRow = Math.min(currentRow, rows);
    buildPalette();
    sizeCanvas(); drawGrid(); saveState();
    toast(msg || t('도안을 열었어요 ({c}코 × {r}단)', {c: cols, r: rows}));
  }
  function downloadText(text, name, type){
    const blob = new Blob([text], { type });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = name;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=>URL.revokeObjectURL(url), 2000);
  }
  function savePatternFile(){
    const d = new Date();
    const stampStr = `${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}-${String(d.getHours()).padStart(2,'0')}${String(d.getMinutes()).padStart(2,'0')}`;
    const name = `${t('코바늘도안')}_${cols}x${rows}_${stampStr}.json`;
    downloadText(JSON.stringify(patternToObject()), name, 'application/json');
    toast(stamp ? t('저장했어요. 떠 있는 글자·장식은 확정한 뒤에 저장돼요') : t('도안 파일을 저장했어요'));
  }
  function openPatternFile(file){
    if(!file) return;
    if(file.size > 5 * 1024 * 1024){ toast(t('파일이 너무 커요')); return; }
    const reader = new FileReader();
    reader.onload = () => {
      try{ applyPattern(validatePattern(JSON.parse(reader.result))); }
      catch(err){ uiAlert(t('도안을 열지 못했어요: ') + (err && err.message ? err.message : err)); }
    };
    reader.readAsText(file);
  }
  const openFileInput = document.getElementById('openFileInput');
  const pickFile = () => { openFileInput.value = ''; openFileInput.click(); };
  openFileInput.addEventListener('change', () => openPatternFile(openFileInput.files[0]));
  ['saveFileBtn', 'saveFileBtn2'].forEach(id => document.getElementById(id).addEventListener('click', savePatternFile));
  ['openFileBtn', 'openFileBtn2'].forEach(id => document.getElementById(id).addEventListener('click', pickFile));
  // 캔버스에 파일을 끌어다 놓아도 열림
  const stageEl = document.querySelector('.stage');
  stageEl.addEventListener('dragover', e => { if(e.dataTransfer && [...e.dataTransfer.types].includes('Files')){ e.preventDefault(); stageEl.classList.add('drop-over'); } });
  stageEl.addEventListener('dragleave', e => { if(e.target === stageEl || !stageEl.contains(e.relatedTarget)) stageEl.classList.remove('drop-over'); });
  stageEl.addEventListener('drop', e => {
    e.preventDefault(); stageEl.classList.remove('drop-over');
    const f = e.dataTransfer && e.dataTransfer.files[0];
    if(f && !filetMode) openPatternFile(f); // 필레 탭은 보기 전용
  });
  // Ctrl+S 저장, Ctrl+O 열기
  document.addEventListener('keydown', e => {
    if(!(e.ctrlKey || e.metaKey)) return;
    if(e.code === 'KeyS'){ e.preventDefault(); savePatternFile(); }
    else if(e.code === 'KeyO'){ e.preventDefault(); pickFile(); }
  });

  // 링크: 주소 끝(#p=...)에 도안을 담음 → 예시 페이지의 '이 도안 열어서 고쳐보기'에 그대로 씀
  function toBase64Url(str){
    const bytes = new TextEncoder().encode(str);
    let bin = ''; bytes.forEach(b => bin += String.fromCharCode(b));
    return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  }
  function fromBase64Url(s){
    s = s.replace(/-/g, '+').replace(/_/g, '/');
    while(s.length % 4) s += '=';
    const bin = atob(s), bytes = new Uint8Array(bin.length);
    for(let i=0; i<bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return new TextDecoder().decode(bytes);
  }
  function patternLink(){
    const o = patternToObject();
    delete o.savedAt; delete o.palette; // 링크는 짧게
    return location.href.split('#')[0] + '#p=' + toBase64Url(JSON.stringify(o));
  }
  document.getElementById('copyLinkBtn').addEventListener('click', async () => {
    const link = patternLink();
    try{ await navigator.clipboard.writeText(link); toast(t('도안 링크를 복사했어요')); }
    catch(e){ uiDialog({ title: t('링크 복사'), msg: t('아래 링크를 복사하세요'), input: true, value: link, readOnly: true, ok: t('닫기'), cancel: null }); }
  });
  function loadPatternFromHash(){
    const m = location.hash.match(/^#p=([A-Za-z0-9_-]+)$/);
    if(!m) return;
    try{ applyPattern(validatePattern(JSON.parse(fromBase64Url(m[1]))), t('링크의 도안을 열었어요. 이전 작업은 되돌리기로 돌아갈 수 있어요')); }
    catch(err){ toast(t('링크의 도안을 열지 못했어요')); }
    try{ history.replaceState(null, '', location.href.split('#')[0]); }catch(e){}
  }

  /* ===== 언어·화면 모드 버튼 ===== */
  const ICON_AUTO = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="8.5"/><path d="M12 3.5v17" /><path d="M12 3.5a8.5 8.5 0 0 1 0 17z" fill="currentColor"/></svg>';
  const ICON_SUN = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="4"/><path d="M12 2.5v2M12 19.5v2M4.6 4.6l1.4 1.4M18 18l1.4 1.4M2.5 12h2M19.5 12h2M4.6 19.4 6 18M18 6l1.4-1.4"/></svg>';
  const ICON_MOON = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 14.5A8 8 0 1 1 9.5 4a6.5 6.5 0 0 0 10.5 10.5z"/></svg>';
  const themeBtn = document.getElementById('themeBtn');
  const langBtn = document.getElementById('langBtn');
  function renderThemeBtn(){
    themeBtn.innerHTML = THEME_PREF === 'dark' ? ICON_MOON : THEME_PREF === 'light' ? ICON_SUN : ICON_AUTO;
    const label = t(THEME_PREF === 'dark' ? '화면: 어둡게' : THEME_PREF === 'light' ? '화면: 밝게' : '화면: 시스템 설정');
    themeBtn.title = label; themeBtn.setAttribute('aria-label', label);
  }
  themeBtn.addEventListener('click', ()=>{
    THEME_PREF = THEME_PREF === 'auto' ? 'dark' : THEME_PREF === 'dark' ? 'light' : 'auto';
    try{ localStorage.setItem('crochet-ui-theme', THEME_PREF); }catch(e){}
    applyThemeAttr(); renderThemeBtn(); drawGrid();
    toast(themeBtn.title);
  });
  if(window.matchMedia){
    const mq = window.matchMedia('(prefers-color-scheme: dark)');
    const onMq = ()=>{ if(THEME_PREF === 'auto'){ readThemeColors(); drawGrid(); } };
    if(mq.addEventListener) mq.addEventListener('change', onMq); else if(mq.addListener) mq.addListener(onMq);
  }
  function applyLang(){
    translateStatic();
    langBtn.textContent = LANG === 'en' ? '한국어' : 'EN';
    langBtn.title = LANG === 'en' ? '한국어로 보기' : 'View in English';
    langBtn.setAttribute('aria-label', langBtn.title);
    renderThemeBtn();
    buildPalette();
    renderShadowUI();
    renderScale();
    renderAlign();
    renderFlow();
    buildDecorRow();
    renderFitUI();
    refreshReplaceUI(true);
    updateUndoButtons();
    renderRibbonFoldBtn();
    updateRibbonGain(); // 영어로 바뀌면 글자 폭이 달라져 작업창 줄 수가 바뀔 수 있음
    sizeCanvas();
    drawGrid();
  }
  // 언어 바꾸기 = 반대편 주소(/pattern/ ↔ /en/pattern/)로 가는 링크. 주소에 도안(#p=…)이 남아 있으면 그대로 이어 붙임.
  // (#p=로 연 도안은 자동 저장에도 들어가므로, 해시가 지워진 뒤에도 반대편 페이지에서 같은 도안이 열림)
  document.querySelectorAll('[data-lang-switch]').forEach(a => {
    a.addEventListener('click', () => {
      const base = a.getAttribute('href').split('#')[0];
      a.setAttribute('href', /^#p=/.test(location.hash) ? base + location.hash : base);
      flushSave();
    });
  });

  /* ===== 시작 ===== */
  const restored = loadState();
  buildPalette();
  renderGaugeUI();
  sizeCanvas();
  flipToggleBtn.classList.toggle('active', flipped);
  zoomLabel.textContent = Math.round(zoomLevel * 100) + '%';
  document.getElementById('knitZoomVal').textContent = Math.round(zoomLevel * 100) + '%';
  rowsInput.value = rows; colsInput.value = cols;
  if(!restored) gridData = new Array(rows*cols).fill(null);
  drawGrid();
  refreshReplaceUI(true);
  renderScale();
  renderAlign();
  renderFlow();
  buildDecorRow();
  buildUserDecors();
  renderShadowUI();
  updateUndoButtons();
  renderFitUI();
  applyLang();
  updateGlyphNote();
  restoring = false;
  loadPatternFromHash();
  // 넓은 화면은 페이지 전체가 스크롤되지 않는 구성이라, 브라우저가 예전 스크롤 위치를 기억해 두었더라도 맨 위로 되돌림
  // (좁은 화면은 위아래로 스크롤하는 페이지라 그대로 둠)
  function resetWideScroll(){
    if(window.matchMedia('(min-width: 900px)').matches && (window.scrollY || document.documentElement.scrollTop)) window.scrollTo(0, 0);
  }
  if('scrollRestoration' in history && window.matchMedia('(min-width: 900px)').matches) history.scrollRestoration = 'manual';
  resetWideScroll();
  window.addEventListener('load', resetWideScroll);
  window.addEventListener('resize', resetWideScroll);
  // 지난번에 작업 화면에서 나갔다면 그대로 이어서
  try{ if(localStorage.getItem('crochet-knit-mode') === '1') setKnitMode(true, true); }catch(e){}
  // 작업창이 접힌 채로 열렸으면, 처음 한 번만 펼치는 곳을 알려 줌 (화면이 다 자리 잡은 뒤에)
  setTimeout(showRibbonHint, 700);
